def expect_is_installed() -> bool:
    """Whether the `expect` binary can be run. Relayed sessions need it."""
    try:
        return (
            subprocess.run(
                ["expect", "-v"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
            ).returncode
            == 0
        )
    except (OSError, RuntimeError):
        return False


def require_expect() -> None:
    """Refuse to start without `expect`, reporting it in a way someone can receive.

    Called from main() rather than at import (#118). It used to run while the module was
    being imported, and to report through a modal Gtk.MessageDialog whose run() blocks
    until a button is clicked -- so importing this module with no one at the screen hung
    forever, and importing it at all could exit the interpreter.

    That is not a hypothetical: it made CI look slow rather than broken. Every test that
    imports the module in a subprocess sat on the invisible dialog until its own timeout.

    The dialog is still right when there is a display and a user. Without one, say it on
    stderr, where a log will keep it.
    """
    if expect_is_installed():
        return
    message = "You must install expect"
    if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
        error = Gtk.MessageDialog(
            modal=True,
            message_type=Gtk.MessageType.ERROR,
            buttons=Gtk.ButtonsType.OK,
            text=message,
        )
        error.run()
        error.destroy()
    else:
        print(f"{message}. Install it with: sudo apt install expect", file=sys.stderr)
    sys.exit(1)


def require_config_dir() -> None:
    """Create the configuration directory, having already chosen which one it is.

    The choosing happens at import (`CONFIG_DIRECTORY`), the creating here, and they are
    apart on purpose: a directory created before the choice satisfies the rule that looks
    for it, so ``~/.config/gcm`` created eagerly would make ``~/.gcm`` unreachable for
    every later start (#192). This also keeps importing the module free of side effects,
    which is why the expect check moved out of import as well (#118).

    A failure here is fatal and said plainly, the way the other two startup checks say
    theirs: without the directory nothing can be saved, and finding that out at the first
    write means finding out through a dialog, with a window full of hosts that cannot be
    kept.
    """
    try:
        configpaths.ensure(CONFIG_DIRECTORY.path)
    except OSError as error:
        message = _("GCM could not create its configuration directory, so it has not started.")
        detail = f"{CONFIG_DIRECTORY.path}\n\n{error}"
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            dialog = Gtk.MessageDialog(
                modal=True,
                message_type=Gtk.MessageType.ERROR,
                buttons=Gtk.ButtonsType.OK,
                text=message,
            )
            dialog.format_secondary_text(detail)
            dialog.run()
            dialog.destroy()
        else:
            print(f"{message}\n{detail}", file=sys.stderr)
        sys.exit(1)
    logger.debug(
        "configuration directory %s (%s), pre-XDG location %s",
        CONFIG_DIRECTORY.path,
        CONFIG_DIRECTORY.source,
        CONFIG_DIRECTORY.legacy,
    )


def require_readable_config() -> None:
    """Refuse to start on a gcm.conf that cannot be read, saying what is wrong and where.

    Starting without it is the worse choice, measured (#161): configparser skipped a file
    it could not open, GCM came up with an empty tree, and closing the window wrote that
    empty tree over the file. Every other refusal left GCM running with no window and the
    reason only on stderr. Reported the way require_expect reports -- a dialog when there
    is a display, stderr when not -- and before anything exists that could write.
    """
    try:
        configfile.load(Path(CONFIG_FILE))
    except configfile.UnreadableError as error:
        message = _("GCM could not read its configuration file, so it has not started.")
        detail = "{}\n\n{}".format(
            error,
            _(
                "Nothing has been changed. Correct the file, or move it aside to start with an empty configuration."
            ),
        )
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            dialog = Gtk.MessageDialog(
                modal=True,
                message_type=Gtk.MessageType.ERROR,
                buttons=Gtk.ButtonsType.OK,
                text=message,
            )
            dialog.format_secondary_text(detail)
            dialog.run()
            dialog.destroy()
        else:
            print(f"{message}\n{detail}", file=sys.stderr)
        sys.exit(1)


