def sync_folders():
    """Bind every host to a folder record, rebuild `groups` from the result, and return
    each folder's children in the order the tree draws them.

    Every edit to the host list -- the dialog, delete, duplicate, import, a drag --
    changes `groups` or a folder record and then calls updateTree, so doing this there
    keeps those callers simple. A folder whose last host has gone stays: folders are
    records now, not a side effect of some host's path. Positions are renumbered here
    too, so a host that left a folder leaves no gap and one that arrived without a
    position gets one -- see `number` for when a folder keeps positions at all.
    """
    hosts = [host for group_hosts in groups.values() for host in group_hosts]
    folders.bind(hosts)
    groups.clear()
    for host in hosts:
        groups.setdefault(host.group, []).append(host)
    contents = folders.contents(hosts)
    for order in contents.values():
        number(order)
    return contents


def configured_host(host, hosts):
    """The host among `hosts` with `host`'s id, else `host` itself (#346).

    The host dialog builds a new record for a host it edits, keeping the id, and a tab
    keeps the record it was opened for, as a clone of that tab does. So it is the host
    with the id that says what a tab is called now, and where it is filed.
    """
    return next((each for each in hosts if each.id == host.id), host)


def tab_namer():
    """What names a host's tab as the configuration now stands, for naming many at once.

    A tab is named by Preferences' Tab name, with as much of its folder in front as tells
    it apart from each other host the template names alike (#346, #348), or by its host's
    own tab name, as it is (#349). The host in the configuration with the tab's host's id
    decides it, its own tab name included, where there is one. One with none, deleted or
    never configured, is named against the hosts there are.

    The Local console is named `local` whatever the template: it is no host, and its
    values stand in for none, so `[{type}] {name}` would have called it `[ssh] local`.
    """
    hosts = [each for filed in groups.values() for each in filed]
    name_of = tabnames.namer(hosts, conf.TAB_NAME)

    def name(host):
        if is_local_console(host, hosts):
            return host.name
        return name_of(configured_host(host, hosts))

    return name


def is_local_console(host, hosts):
    """Whether `host` is the Local console's: the record the Local button makes, and a
    clone of its tab, named `local`, with no folder and no address, and the id of none of
    `hosts`, the configuration's. A host there of that name is a host."""
    return (
        host.name == "local"
        and not host.group
        and not host.host
        and all(each.id != host.id for each in hosts)
    )


def host_tab_name(host):
    """What `host`'s tab is called, as tab_namer names it."""
    return tab_namer()(host)


def host_path(host):
    """`host`'s whole place in the folder tree, its folders and its name, as the host with
    its id is filed in the configuration (#347). A tab's tooltip, the open-console list
    and the cluster window show it beside the tab's name."""
    hosts = [each for filed in groups.values() for each in filed]
    return tabnames.whole_path(configured_host(host, hosts))


def host_tab_color(host):
    """The colour `host`'s tabs are marked with, "" for none (#350): that of the host with
    its id in the configuration, its own or its folder's, as utils/tabcolors.py finds it."""
    hosts = [each for filed in groups.values() for each in filed]
    return tabcolors.tab_color(configured_host(host, hosts), folders)


def refile_ambiguous_hosts(groups_by_path, ambiguous_folders):
    """Forget a folder id that named two folder records in the file (#161).

    The id cannot say which record a host meant, but the `group` path saved beside it
    can: with the id cleared, FolderTree.bind files the host by that path instead.
    """
    for hosts in groups_by_path.values():
        for host in hosts:
            if host.folder in ambiguous_folders:
                host.folder = ""


def carried_config():
    """The gcm.conf a save starts from: the file as it is now, less what the save writes.

    Read when saving rather than kept from startup, so a [keys] line added by hand while
    GCM runs survives the save (#163). A file that cannot be read in full is kept aside
    rather than written over, as main() refuses to start on one (#161), and the save then
    starts from nothing.
    """
    path = Path(CONFIG_FILE)
    try:
        return configfile.unwritten(configfile.load(path).config)
    except configfile.UnreadableError as error:
        aside = configfile.aside_path(path, time.strftime("%Y%m%d-%H%M%S"))
        path.replace(aside)
        logger.warning("Kept %s as %s rather than write over it. %s", path.name, aside, error)
        return configparser.RawConfigParser()


def folder_contents():
    """Each folder's children as drawn, as sync_folders returns them, changing nothing."""
    return folders.contents(host for group_hosts in groups.values() for host in group_hosts)


def place_copy(original, copy):
    """Put a duplicate straight after its original in a folder someone has arranged. In
    one still in name order it needs nothing: it sorts in by name like any new host."""
    order = folder_contents().get(original.folder, [])
    if any(child.position is not None for child in order):
        place(order, copy, original, after=True)


enc_passwd = ""


class GladeComponent:
    def __init__(self, path, root=None, domain=None, application=None, parent=None, **kwargs):
        self.builder = Gtk.Builder()
        if domain:
            self.builder.set_translation_domain(domain)
        self.application = application
        for key, value in kwargs.items():
            try:
                setattr(self, key, weakref.proxy(value))
            except TypeError:
                setattr(self, key, value)

        glade_path = Path(path)
        if not glade_path.is_file():
            glade_path = Path(sys.argv[0]).parent / path
        self.glade_path = str(glade_path)

        if root:
            if parent:
                self.builder.expose_object("wMain", parent)
            self.builder.add_objects_from_file(self.glade_path, [root])
            self.main_widget = self.builder.get_object(root)
            if isinstance(self.main_widget, (Gtk.Window, Gtk.Dialog)):
                if parent and isinstance(parent, Gtk.Window):
                    self.main_widget.set_transient_for(parent)
                if application is not None:
                    self.main_widget.set_application(application)
                self.main_widget.show_all()
                self.main_widget.present()
                while Gtk.events_pending():
                    Gtk.main_iteration()
        else:
            self.builder.add_from_file(self.glade_path)
            self.main_widget = None

        self.normalize_names()
        self.new()
        self.builder.connect_signals(self)

        # The dialogs are already on screen by now: they are presented before
        # new() fills them, and Whost is filled later still by its init(). Wait
        # for the size to settle before deciding whether it fits the monitor.
        if isinstance(self.main_widget, Gtk.Dialog):
            GLib.idle_add(fit_window_to_monitor, self.main_widget, priority=GLib.PRIORITY_LOW)

    def new(self):
        pass

    def normalize_names(self):
        for widget in self.get_widgets():
            if isinstance(widget, Gtk.Buildable):
                widget_name = Gtk.Buildable.get_name(widget)
                prefixes_name_l = widget_name.split(":")
                prefixes = prefixes_name_l[:-1]
                widget_api_name = prefixes_name_l[-1]
                widget_api_name = "_".join(re.findall(tokenize.Name, widget_api_name))
                Gtk.Buildable.set_name(widget, widget_api_name)
                if hasattr(self, widget_api_name):
                    raise AttributeError(
                        f"instance {self} already has an attribute {widget_api_name}"
                    )
                setattr(self, widget_api_name, widget)
                if prefixes:
                    Gtk.Buildable.set_data(widget, "prefixes", prefixes)

    def get_widget(self, widget_name):
        return self.builder.get_object(widget_name)

    def get_widgets(self):
        return self.builder.get_objects()


