# Path separators, the control range and the Windows-reserved set must never reach a
# log filename. Tab labels can carry any of them -- a host name, a manual rename, or
# (once tab titles follow the terminal) a string chosen by whatever is running in it.


_FILE_LOCATION = re.compile(r"^(?P<path>.+?):(?P<line>[0-9]+)(?::(?P<col>[0-9]+))?$")


def parse_file_location(match):
    """Split "path/to/file.py:42:7" into its parts, or None if it is not that shape."""
    found = _FILE_LOCATION.match((match or "").strip())
    if not found:
        return None
    return (
        found.group("path"),
        int(found.group("line")),
        int(found.group("col") or 0),
    )


def terminal_is_local(terminal):
    """True when the terminal runs a local shell rather than an ssh/telnet session.

    A path printed by a remote host does not exist here, so opening it locally would
    silently open the wrong file or nothing at all.
    """
    host = getattr(terminal, "host", None)
    if host is None:
        return False
    return not (getattr(host, "host", "") or "")


def host_sends_commands(host):
    """True when a host's stored commands should be sent on connect.

    The checkbox in the host dialog decides this, not whether there is any text: an
    entry keeps its commands when they are switched off, so the two are separate (#151).
    A type can send none, as RDP does (#225).
    """
    return (
        bool(host.commands_enabled and host.commands)
        and connections.named(host.type).sends_commands
    )


def terminal_working_directory(terminal):
    """Best-effort cwd for resolving a relative path.

    OSC 7 first: a shell that emits it stays correct even mid-command. Otherwise read
    the pty's foreground process group, which needs no shell cooperation -- measured on
    this platform, bash emits no OSC 7 at all, so that fallback is the path that runs.
    """
    uri = (
        terminal.get_current_directory_uri()
        if hasattr(terminal, "get_current_directory_uri")
        else None
    )
    if uri:
        try:
            path, _host = GLib.filename_from_uri(uri)
            return path
        except Exception:
            logger.debug("Undecodable OSC 7 directory URI: %r", uri)
    pty = terminal.get_pty() if hasattr(terminal, "get_pty") else None
    if pty is None:
        return None
    try:
        return str(Path(f"/proc/{os.tcgetpgrp(pty.get_fd())}/cwd").readlink())
    except OSError:
        return None


def build_editor_command(path, line, col):
    """Command to open a file at a line, as a list ready for Popen.

    conf.EDITOR_COMMAND wins when set, as a template over {file}, {line} and {col}.
    Otherwise $VISUAL or $EDITOR with the +LINE convention that vi, vim, nano and emacs
    all understand, and xdg-open as the last resort -- which cannot take a line number.
    """
    template = (conf.EDITOR_COMMAND or "").strip()
    if template:
        return shlex.split(template.format(file=path, line=line, col=col))
    editor = os.environ.get("VISUAL") or os.environ.get("EDITOR")
    if editor:
        return [*shlex.split(editor), f"+{line}", path]
    return ["xdg-open", path]


def open_in_browser(url):
    """Open `url` through xdg-open, in the browser, or the mail client for mailto: (#231, #232).

    Not Gtk.show_uri. GIO finds a browser only through a MIME cache or a default named
    in mimeapps.list, and WSLg can have neither: there it raised "Operation not
    supported", while xdg-open found the browser from its desktop file. On a GNOME
    desktop xdg-open hands the URL to gio anyway.

    Not waited for: with no desktop session, xdg-open runs the browser itself and returns
    only when it closes, measured. A failure it reports is shown once it exits.
    """
    # xdg-open looks for a handler by the scheme as written: measured, HTTPS: and MAILTO:
    # went to $BROWSER where https: and mailto: found theirs. RFC 3986 makes a scheme's
    # case no part of it, so it goes in lower case.
    url = re.sub(r"^[A-Za-z][A-Za-z0-9+.-]*:", lambda scheme: scheme[0].lower(), url)
    open_with(["xdg-open", url], url)


def open_with(argv, target):
    """Run `argv` to open `target`, without waiting for it, and say so if it fails."""
    try:
        pid, *_pipes = GLib.spawn_async(
            argv,
            flags=GLib.SpawnFlags.SEARCH_PATH | GLib.SpawnFlags.DO_NOT_REAP_CHILD,
        )
    except GLib.Error as error:
        msgbox("{} {}: {}".format(_("Could not open"), target, error.message))
        return

    def exited(pid, status):
        GLib.spawn_close_pid(pid)
        code = os.waitstatus_to_exitcode(status)
        if code != 0:
            msgbox(
                "{} {}: {} {} {}".format(
                    _("Could not open"),
                    target,
                    Path(argv[0]).name,
                    _("exited with status"),
                    code,
                )
            )

    GLib.child_watch_add(GLib.PRIORITY_DEFAULT, pid, exited)


def open_in_file_manager(address):
    """Open a host's `sftp://` address in the file manager (#267), or a folder's `file://`
    one, a mount's in ~/mnt (#269).

    Not through xdg-open: measured, with nothing to handle sftp: it gave the address to the
    web browser and exited 0. No file manager in Ubuntu 24.04 handles the scheme, and every
    one opens folders and takes an address, read from their desktop files. So GIO's default
    application for folders, and where GIO knows none, the first of
    remotefiles.FILE_MANAGERS on PATH: GIO finds that default only through a MIME cache or
    mimeapps.list, measured, and a system without either, as WSL can be, has none.
    """
    application = Gio.AppInfo.get_default_for_type("inode/directory", True)
    if application is not None:
        try:
            application.launch_uris([address], None)
        except GLib.Error as error:
            msgbox("{} {}: {}".format(_("Could not open"), address, error.message))
        return
    command = remotefiles.file_manager_command(shutil.which)
    if command is None:
        # One literal each: tests/test_i18n.py does not follow a message split across two.
        if address.startswith("file:"):
            # A folder on this computer, which mounting a host is no way round.
            msgbox(
                _(
                    "No file manager was found to open {}. Install one, such as Files (nautilus), Nemo, Thunar or Dolphin."
                ).format(Gio.File.new_for_uri(address).get_path())
            )
            return
        msgbox(
            _(
                "No file manager was found to open {}. Install one, such as Files (nautilus), Nemo, Thunar or Dolphin, or mount the host with SSHFS."
            ).format(address)
        )
        return
    open_with([*command, address], address)


def read_mount_table():
    """The text of /proc/self/mountinfo, or nothing where it cannot be read."""
    try:
        return Path("/proc/self/mountinfo").read_text(errors="replace")
    except OSError:
        return ""


def remove_mount_folder(folder):
    """Remove a host's folder under ~/mnt once nothing is mounted there, so that one is not
    left behind for every host ever mounted. rmdir, and only that: measured, it refuses a
    folder still mounted, as busy, and one holding anything, which keeps what it holds."""
    with contextlib.suppress(OSError):
        folder.rmdir()


def fusermount():
    """What unmounts what sshfs mounted: FUSE 3's fusermount, or FUSE 2's where only that is
    installed, or None."""
    return shutil.which("fusermount3") or shutil.which("fusermount")


# What the tree and the Hosts menu put before the name of a host mounted with sshfs. Text,
# so that it is drawn at the name's size: measured at a font scale of 2.25, the 16 pixel
# icon that took the host's place sat beside a line of text 46 pixels tall, and went
# unnoticed. Before the name, not after it, where a name wider than the tree puts it out
# of sight.
MOUNTED_MARK = "✓"


def mounted_at(host, found):
    """The tree's column for where `host` is mounted, from `found`, {host: folder}: the
    folder, or "" where it is not mounted."""
    return str(found[host]) if host in found else ""


def marked_name(name, folder):
    """A host's name as the tree and the Hosts menu draw it: after MOUNTED_MARK while it is
    mounted, at `folder`."""
    return f"{MOUNTED_MARK} {name}" if folder else name


def draw_mount_mark(_column, cell, model, iter_, *_data):
    """Draw a host mounted with sshfs with MOUNTED_MARK before its name. Only that row's
    text is set here: the name column sets every row's before this runs."""
    folder = model.get_value(iter_, 5)
    if folder:
        cell.set_property("text", marked_name(model.get_value(iter_, 0), folder))


def row_color(model, iter_):
    """The colour the tree's row shows (#358): a host's, as its tabs take it, its own or
    its folder's, or a folder's, as it gives it to the hosts in it. "" for none."""
    host = model.get_value(iter_, 1)
    if host is not None:
        return tabcolors.tab_color(host, folders)
    return tabcolors.folder_color(folders, model.get_value(iter_, 4))


def marked_markup(text, color, background):
    """`text` as markup, after the square of `color` on a patch of `background`, as the
    tree and the Hosts menu draw a host or a folder with a colour (#358)."""
    return f"{tabcolors.mark_markup(color, background)} {GLib.markup_escape_text(text)}"


def draw_name(column, cell, model, iter_, *_data):
    """Draw a row's name after its marks: the square of its colour, on a patch of the
    row's own background, which shows on the selected row alone (#358), then
    MOUNTED_MARK, as draw_mount_mark draws it. In the name's own text, so at its size and
    on its line. A row with no colour is drawn as before."""
    color = row_color(model, iter_)
    if not color:
        draw_mount_mark(column, cell, model, iter_)
        return
    text = marked_name(model.get_value(iter_, 0), model.get_value(iter_, 5))
    cell.set_property("markup", marked_markup(text, color, model.get_value(iter_, 3)))


def mount_names(mounts, found):
    """What each of `mounts`, {folder: what is mounted there}, is called: the name of the
    first host `found`, {host: folder}, has mounted there, or else what is mounted."""
    named: dict = {}
    for host, folder in found.items():
        named.setdefault(folder, host.name)
    return {folder: named.get(folder, source) for folder, source in mounts.items()}


def read_finished(fd):
    """What a finished child wrote to the pipe `fd`, which this closes.

    Without waiting: a mount's ssh keeps its descriptors for as long as the mount lasts."""
    os.set_blocking(fd, False)
    chunks = []
    try:
        while chunk := os.read(fd, 65536):
            chunks.append(chunk)
    except BlockingIOError:
        pass
    finally:
        os.close(fd)
    return b"".join(chunks).decode(errors="replace")


def session_tail(terminal, rows=4):
    """The last lines a terminal's session printed, up to its cursor (#239)."""
    column, row = terminal.get_cursor_position()
    first = max(0, row - rows)
    if Vte.get_minor_version() < 72:
        text, _attrs = terminal.get_text_range(first, 0, row, column, None, None)
    else:
        text, _attrs = terminal.get_text_range_format(Vte.Format.TEXT, first, 0, row, column)
    return text or ""


def login_asking(terminal):
    """Whether a tab shows a question its login asks, from the text before the cursor on
    its row (#312)."""
    return afterlogin.asking(session_tail(terminal, rows=0))


# Keys VTE keeps for itself, scrolling the tab, rather than sending to the program: with
# Shift, and Up and Down with Ctrl and Shift. Not held while commands after login wait.
SCROLL_KEYS = frozenset(
    getattr(Gdk, "KEY_" + name)
    for name in (
        "Page_Up",
        "Page_Down",
        "Home",
        "End",
        "KP_Page_Up",
        "KP_Page_Down",
        "KP_Home",
        "KP_End",
    )
)
LINE_SCROLL_KEYS = frozenset((Gdk.KEY_Up, Gdk.KEY_Down, Gdk.KEY_KP_Up, Gdk.KEY_KP_Down))


def vte_keeps(event):
    """Whether VTE scrolls for a key rather than sending it to the program."""
    shift = Gdk.ModifierType.SHIFT_MASK
    control = Gdk.ModifierType.CONTROL_MASK
    if event.keyval in SCROLL_KEYS:
        return bool(event.state & shift)
    both = shift | control
    return event.keyval in LINE_SCROLL_KEYS and (event.state & both) == both


def local_command(host, template):
    """`template`, a command `host` runs on this computer, with the host's values filled
    in, each quoted for the shell (#238)."""
    return placeholders.fill(template, placeholders.host_values(host), quote=shlex.quote)


def run_in_background(command, exited):
    """Run `command` through sh, from the home directory, and call `exited` with its exit
    status once it ends. Not waited for. A command that cannot be started is reported
    here, and `exited` is not called.
    """
    try:
        pid, *_pipes = GLib.spawn_async(
            ["sh", "-c", command],
            working_directory=str(Path.home()),
            flags=GLib.SpawnFlags.SEARCH_PATH | GLib.SpawnFlags.DO_NOT_REAP_CHILD,
        )
    except GLib.Error as error:
        msgbox("{} {}: {}".format(_("Could not run"), command, error.message))
        return

    def watch(pid, status):
        GLib.spawn_close_pid(pid)
        exited(os.waitstatus_to_exitcode(status))

    GLib.child_watch_add(GLib.PRIORITY_DEFAULT, pid, watch)


def contrasting_foreground(rgba):
    """Black or white, whichever stays legible on `rgba`.

    Only used when no foreground has been configured. VTE has no getter for its default
    foreground, and guessing wrong is what makes text invisible.
    """
    if rgba is None:
        return "#FFFFFF"
    # Rec. 601 luma: good enough to pick a side, and it needs no colour science.
    luma = 0.299 * rgba.red + 0.587 * rgba.green + 0.114 * rgba.blue
    return "#000000" if luma > 0.5 else "#FFFFFF"


def terminal_colors(terminal):
    """(foreground, background) the buffer view should use to match its terminal.

    The background comes from VTE, which knows it even when GCM configured nothing --
    its default is black, which is why a viewer on the theme's light background hid
    light text. There is no foreground getter, so that comes from the same config the
    terminal was built from.
    """
    background_rgba = None
    if hasattr(terminal, "get_color_background_for_draw"):
        try:
            background_rgba = terminal.get_color_background_for_draw()
        except Exception:
            background_rgba = None
    background = background_rgba.to_string() if background_rgba is not None else "#000000"

    host = getattr(terminal, "host", None)
    foreground = (getattr(host, "font_color", "") or "") or (conf.FONT_COLOR or "")
    return foreground or contrasting_foreground(background_rgba), background


def _exported(result):
    """The text of a VTE export; older VTE returns (text, attributes)."""
    return (result[0] if isinstance(result, tuple) else result) or ""


def _buffer_range(terminal, fmt):
    """The rows VTE holds in one format, or None when they are blank or unreadable.

    VTE numbers rows from the start of the session and keeps counting once it drops the
    oldest, but the vertical adjustment runs from 0 to the number of rows held, counted
    down to the bottom of the screen. Read as row numbers, the adjustment asked for rows
    long gone and stopped short of the newest once the scrollback overflowed (#179). The
    cursor is reported in the numbering get_text_range_format takes: the rows held end
    within a screen below it, and start no earlier than it less the rows held. VTE
    answers a row it does not hold with an empty line, so that window is safe to ask
    for, and the empty lines at each end of the text say where the rows really are. The
    HTML is read over those.

    select_all() then get_text_selected_full() would find the rows too, but destroys
    whatever the user had selected; this leaves it untouched.
    """
    adjustment = terminal.get_vadjustment() if hasattr(terminal, "get_vadjustment") else None
    if adjustment is None:
        return None
    try:
        _column, cursor = terminal.get_cursor_position()
        held = int(adjustment.get_upper() - adjustment.get_lower())
        first, end = max(0, cursor + 1 - held), cursor + terminal.get_row_count()
        text = _exported(terminal.get_text_range_format(Vte.Format.TEXT, first, 0, end, 0))
        rows = text.lstrip("\n")
        if not rows.strip():
            return None
        if fmt == Vte.Format.TEXT:
            return rows
        first += len(text) - len(rows)
        end -= max(0, len(rows) - len(rows.rstrip("\n")) - 1)
        return _exported(terminal.get_text_range_format(fmt, first, 0, end, 0))
    except Exception:
        logger.debug("Range extraction failed, falling back to the visible screen")
        return None


def _buffer_screen(terminal, fmt):
    """The visible screen in one format -- all an alternate-screen application has."""
    try:
        result = terminal.get_text_format(fmt)
    except Exception:
        logger.debug("Screen extraction unavailable")
        return None
    return result[0] if isinstance(result, tuple) else result


def terminal_buffer_html(terminal):
    """The terminal's scrollback as VTE's HTML export, or None if unavailable.

    Same rows and same bounds as terminal_buffer_text, including its fall through to the
    visible screen, so the two agree on content and differ only in whether attributes
    come along. Without that fall through the viewer showed a full-screen application as
    a page of empty rows (#107). The range came back empty there because it was read by
    the adjustment's numbers, which miss every row of the alternate screen -- the fault
    #179 found in the scrollback. Read by the cursor's, the range holds that screen, and
    the fall through remains for a range with nothing readable in it. Blankness has to be
    judged on the text the export carries, not on its length -- the empty answer is 23
    bytes of markup wrapping 12 newlines.
    """
    html = _buffer_range(terminal, Vte.Format.HTML)
    if not vtehtml.plain_text(vtehtml.parse_vte_html(html)).strip():
        html = _buffer_screen(terminal, Vte.Format.HTML)
    return html or None


def terminal_buffer_text(terminal):
    """The terminal's scrollback as plain text."""
    text = _buffer_range(terminal, Vte.Format.TEXT)
    if text and text.strip():
        return text.rstrip()
    # Nothing readable in the range, so the visible screen is all there is.
    return (_buffer_screen(terminal, Vte.Format.TEXT) or "").rstrip()


def uri_to_terminal_text(uri):
    """One dropped URI as text safe to leave at a shell prompt.

    file:// URIs become local paths, because a path is what you want to type. Anything
    else is kept as a URI. Both are shell-quoted: a dropped name containing a space, or a
    query string full of & and ?, would otherwise land as several broken arguments.
    """
    uri = (uri or "").strip()
    if not uri:
        return ""
    if uri.startswith("file://"):
        try:
            path, _host = GLib.filename_from_uri(uri)
        except Exception:
            logger.debug("Undecodable file URI dropped on a terminal: %r", uri)
            path = uri
        return shlex.quote(path)
    return shlex.quote(uri)


def uris_to_terminal_text(uris):
    """Several dropped URIs as one space-separated argument list."""
    return " ".join(text for text in (uri_to_terminal_text(u) for u in (uris or [])) if text)


def session_file_for(terminal, suffix):
    """Path for one of a session's files, reading the log root from the config.

    Every file a session writes shares one number, chosen the first time it needs any
    of them and kept on the terminal. They are not opened together: the text log opens
    with the tab or when logging is switched on, the recording each time the session is
    spawned. Numbered one at a time, they drifted apart (#200). A reconnect keeps the
    number as well, so its recording carries on in the tab's file, as the text log does.

    Choosing the number creates the file asked for, empty, so that no other session can
    choose it before this one writes there (#202).

    The `conf.LOG_PATH` read lives here rather than in utils.logpaths so that nothing in
    that module has to know about configuration.
    """
    stem = getattr(terminal, "session_stem", None)
    if stem is None:
        stem = logpaths.session_stem_for(terminal, conf.LOG_PATH, suffix)
        if stem is None:
            return None
        terminal.session_stem = stem
    return stem + suffix


def read_config_option(cp, section, option, kind, default):
    """Read one option, degrading to `default` rather than aborting its neighbours.

    Options are read individually so that a single absent or malformed entry cannot
    discard every setting after it, which would then be written back over the user's
    file on the next save. The malformed entry itself comes back as a
    `configfile.Unread` beside the default, so the save can keep it too (#173).
    """
    value, unread = configfile.read_option(cp, section, option, kind, default)
    if unread:
        logger.error(
            "%s: [%s] %s: %s",
            _("Entrada invalida en archivo de configuracion"),
            section,
            option,
            unread.reason,
        )
    return value, unread


def msgbox(text: str, parent: Gtk.Window | None = None) -> None:
    """Show an error message dialog."""
    msgBox = Gtk.MessageDialog(
        parent=parent,
        modal=True,
        message_type=Gtk.MessageType.ERROR,
        buttons=Gtk.ButtonsType.OK,
        text=text,
    )
    msgBox.set_icon_from_file(ICON_PATH)
    msgBox.run()
    msgBox.destroy()


def msginfo(text: str, parent: Gtk.Window | None = None) -> None:
    """Show a message that something worked, or that there was nothing to do: drawn as
    information, where msgbox draws an error, its icon included."""
    msgBox = Gtk.MessageDialog(
        parent=parent,
        modal=True,
        message_type=Gtk.MessageType.INFO,
        buttons=Gtk.ButtonsType.OK,
        text=text,
    )
    msgBox.set_icon_from_file(ICON_PATH)
    msgBox.run()
    msgBox.destroy()


def msgconfirm(text: str) -> int:
    """Show a confirmation dialog and return the response."""
    msgBox = Gtk.MessageDialog(
        parent=wMain.window,
        modal=True,
        message_type=Gtk.MessageType.QUESTION,
        buttons=Gtk.ButtonsType.OK_CANCEL,
        text=text,
    )
    msgBox.set_icon_from_file(ICON_PATH)
    response = msgBox.run()
    msgBox.destroy()
    return int(response)


def inputbox(
    title: str,
    text: str,
    default: str = "",
    password: bool = False,
    parent: Gtk.Window | None = None,
) -> str | None:
    msgBox = EntryDialog(title, text, default, mask=password, parent=parent)
    msgBox.set_icon_from_file(ICON_PATH)
    response = msgBox.value if msgBox.run() == Gtk.ResponseType.OK else None
    msgBox.destroy()
    return response


# The response of the No Color button choose_tab_color adds. GTK's own are negative.
NO_COLOR = 1


def choose_tab_color(current: str, parent: Gtk.Window | None = None) -> str | None:
    """A colour for a folder's tabs as `#rrggbb`, "" for none, or None when cancelled (#350).

    GTK's colour chooser, with a No Color button, and starting at `current` where that is a
    colour.
    """
    dialog = Gtk.ColorChooserDialog(title=_("Tab Color"), transient_for=parent)
    dialog.set_icon_from_file(ICON_PATH)
    dialog.set_use_alpha(False)
    dialog.add_button(_("No Color"), NO_COLOR)
    color = tabcolors.color_of(current)
    if color:
        dialog.set_rgba(parse_color_rgba(color))
    response = dialog.run()
    chosen = color_to_hex(dialog.get_rgba())
    dialog.destroy()
    if response == Gtk.ResponseType.OK:
        return chosen
    if response == NO_COLOR:
        return ""
    return None


def paste_transform(text, single_line: bool = False) -> str:
    """Apply paste hygiene to clipboard text before it reaches the terminal.

    Pasted text that ends in a newline submits itself the moment it lands, which is how a
    prompt meant for review turns into a command that already ran. VTE delivers the
    clipboard verbatim -- bracketed paste wraps the text but still passes the newline
    through -- so the trailing terminator has to come off here.
    """
    if not text:
        return ""
    content: str = text
    if single_line:
        # Join every non-blank line so a multi-line paste lands as a single command.
        return " ".join(line.strip() for line in content.splitlines() if line.strip())
    if conf.PASTE_STRIP_TRAILING_NEWLINE:
        # Every trailing terminator, not just one. A VTE line selection reaches the
        # clipboard as "text\n\n", so dropping a single newline would still submit.
        # CRLF is covered too: Windows clipboards arrive that way under WSL.
        return content.rstrip("\r\n")
    return content


def paste_needs_confirmation(text: str) -> bool:
    """True when the paste is big enough to be worth a look before it is delivered."""
    lines = conf.PASTE_CONFIRM_LINES
    max_bytes = conf.PASTE_CONFIRM_BYTES
    if lines and len(text.splitlines()) > lines:
        return True
    return bool(max_bytes and len(text.encode("utf-8", "replace")) > max_bytes)


def paste_preview(text: str, max_lines: int = 10, max_width: int = 80) -> str:
    """Render the confirmation prompt: a size summary plus the head of the content."""
    lines = text.splitlines()
    summary: str = _("Pegar {lines} líneas ({bytes} bytes)?").format(
        lines=len(lines), bytes=len(text.encode("utf-8", "replace"))
    )
    shown = []
    for line in lines[:max_lines]:
        shown.append(line[:max_width] + "…" if len(line) > max_width else line)
    if len(lines) > max_lines:
        shown.append("…")
    return summary + "\n\n" + "\n".join(shown)


# What a window manager puts around a window: a title bar, and under client-side
# decorations a shadow either side of it. Measured at 89-97px tall under GNOME on
# both X11 and Wayland. It cannot be read back while a resize is in flight — the
# window manager's frame and GTK's own size settle on different clocks, and
# subtracting one from the other then yields nonsense — so allow for it instead.
# Erring large only costs a window some height it had no room for anyway.
WINDOW_FRAME_ALLOWANCE = 96

# What GTK reports as a position before the window manager has placed a window.
UNPLACED_WINDOW_COORD = -30000


def overlap_area(first, second):
    """Area two `(x, y, width, height)` rectangles share, or 0 when they do not meet."""
    first_x, first_y, first_width, first_height = first
    second_x, second_y, second_width, second_height = second
    width = min(first_x + first_width, second_x + second_width) - max(first_x, second_x)
    height = min(first_y + first_height, second_y + second_height) - max(first_y, second_y)
    return width * height if width > 0 and height > 0 else 0


def monitor_showing(display, window):
    """The monitor holding most of `window`, or None while it is nowhere yet.

    `Gdk.Display.get_monitor_at_window` cannot say "nowhere": when a window
    overlaps no monitor it answers with the *first* one. That is what an unplaced
    window looks like, and -- measured on a three-monitor WSLg display whose
    monitors start at y=3 -- it is also what the main window at (0, 0) looks like.
    The answer was a 2880x1920 screen at (606, 1083) that the application is not
    on, and with no primary monitor set nothing further down corrected it (#94).

    Working the overlap out here means "nowhere" is an answer the caller can have,
    and a window that really is on a monitor is matched by area rather than by
    whichever monitor happens to be first.
    """
    if window is None:
        return None
    if window.get_window() is None:
        return None
    # A window the manager has not placed sits at a large negative sentinel, which
    # overlaps no monitor -- so the arithmetic below already answers "nowhere" for
    # it, and a guard on the sentinel would only restate that.
    x, y = window.get_position()
    width, height = window.get_size()
    bounds = (x, y, width, height)
    best, best_area = None, 0
    for index in range(display.get_n_monitors()):
        monitor = display.get_monitor(index)
        geometry = monitor.get_geometry()
        area = overlap_area(bounds, (geometry.x, geometry.y, geometry.width, geometry.height))
        if area > best_area:
            best, best_area = monitor, area
    return best


def monitor_workarea(window=None):
    """Usable area of the monitor showing `window`, or of the primary one."""
    display = Gdk.Display.get_default()
    if display is None:
        return None
    monitor = monitor_showing(display, window)
    if monitor is None and window is not None:
        # A dialog measured on the idle after it is shown is often not placed yet.
        # It opens on its parent's monitor, and the parent is placed, so ask that
        # rather than let the guesses below pick an arbitrary screen.
        monitor = monitor_showing(display, window.get_transient_for())
    if monitor is None:
        monitor = display.get_primary_monitor()
    if monitor is None and display.get_n_monitors() > 0:
        monitor = display.get_monitor(0)
    if monitor is None:
        return None
    return monitor.get_workarea()


def clamp_to_workarea(width, height, workarea, allowance=0):
    """Shrink a requested size so it stays inside `workarea`, frame included."""
    if workarea is None:
        return width, height
    return (
        min(width, max(workarea.width - allowance, 1)),
        min(height, max(workarea.height - allowance, 1)),
    )


def scroll_notebook_page(notebook, page):
    """Put `page` inside a scroller, keeping its place and tab in `notebook`.

    The scroller propagates the child's natural size, so a dialog that already
    fits looks exactly as it did; only its *minimum* size drops.
    """
    if isinstance(page, Gtk.ScrolledWindow):
        return None
    scroller = Gtk.ScrolledWindow()
    scroller.set_policy(Gtk.PolicyType.AUTOMATIC, Gtk.PolicyType.AUTOMATIC)
    scroller.set_propagate_natural_width(True)
    scroller.set_propagate_natural_height(True)
    position = notebook.page_num(page)
    label = notebook.get_tab_label(page)
    notebook.remove_page(position)
    scroller.add(page)
    notebook.insert_page(scroller, label, position)
    scroller.show_all()
    return scroller


def scroll_oversized_content(window, workarea):
    """Make a window's content scrollable when it cannot fit on screen.

    Dialogs built from the glade file pack their notebook straight into the
    content area, so a page that grows at runtime — `tblGeneral` gains a row per
    option — pushes the OK/Cancel row off the bottom of the screen, where it can
    be neither seen nor resized back into view: the minimum size is the problem,
    not the natural one. Wrapping the pages rather than the notebook keeps the
    tabs pinned above the scrolled area.
    """
    if workarea is None or not isinstance(window, Gtk.Dialog):
        return False
    _, width = window.get_preferred_width()
    _, height = window.get_preferred_height()
    if (width, height) == clamp_to_workarea(width, height, workarea, WINDOW_FRAME_ALLOWANCE):
        return False
    wrapped = False
    for child in window.get_content_area().get_children():
        if not isinstance(child, Gtk.Notebook):
            continue
        # Wrapping a page means removing and reinserting it, and removing the selected
        # page moves the selection on. Doing that down the whole notebook walks it off
        # the first tab, and past the second, because each removal pushes it beyond the
        # page going back in -- Edit Host opened on Commands and Settings on Shortcuts,
        # never on the tab between (#89). Put the selection back where it was.
        selected = child.get_current_page()
        for page in list(child.get_children()):
            wrapped = scroll_notebook_page(child, page) is not None or wrapped
        if selected >= 0:
            child.set_current_page(selected)
    return wrapped


def onscreen_position(window, workarea, width, height):
    """Where a `width` x `height` `window` has to sit to stay inside `workarea`.

    None when it is already inside, or when the window manager has not placed it
    yet — GTK reports a large negative sentinel until it does, and it places the
    window once, later, at its final size, so there is nothing to correct.
    """
    if workarea is None:
        return None
    x, y = window.get_position()
    if x <= UNPLACED_WINDOW_COORD or y <= UNPLACED_WINDOW_COORD:
        return None
    room_x = workarea.x + workarea.width - width - WINDOW_FRAME_ALLOWANCE
    room_y = workarea.y + workarea.height - height - WINDOW_FRAME_ALLOWANCE
    placed = (
        min(max(x, workarea.x), max(room_x, workarea.x)),
        min(max(y, workarea.y), max(room_y, workarea.y)),
    )
    return placed if placed != (x, y) else None


def fit_window_to_monitor(window):
    """Keep `window` within the monitor work area, buttons included.

    A window that already fits keeps the size GTK would have given it. Placement
    is corrected when it does not: the dialogs are presented, and so placed, while
    still empty, then grow once new() has filled them in — which walks the bottom
    edge, and with it the OK/Cancel row, off the screen.
    """
    if not window.get_visible():
        # Closed again before the idle ran; there is nothing left to fit.
        return
    workarea = monitor_workarea(window)
    if workarea is None:
        return
    scroll_oversized_content(window, workarea)
    _, width = window.get_preferred_width()
    _, height = window.get_preferred_height()
    capped = clamp_to_workarea(width, height, workarea, WINDOW_FRAME_ALLOWANCE)
    if capped != (width, height):
        window.resize(*capped)
    # Nothing moves a window that grew after the window manager placed it, so
    # slide it back up itself. resize() is asynchronous, hence measuring against
    # the size just asked for rather than reading one back.
    placed = onscreen_position(window, workarea, *capped)
    if placed is not None:
        window.move(*placed)


def apply_font_to_widget(widget, font_desc):
    """Apply a Pango FontDescription to a widget using CSS"""
    css_provider = Gtk.CssProvider()
    family = font_desc.get_family()
    size = font_desc.get_size() / Pango.SCALE  # Convert from Pango units to points

    # Build CSS font specification
    css_parts = []

    # Font style (italic, oblique)
    style = font_desc.get_style()
    if style == Pango.Style.ITALIC:
        css_parts.append("font-style: italic;")
    elif style == Pango.Style.OBLIQUE:
        css_parts.append("font-style: oblique;")

    # Font weight
    weight = font_desc.get_weight()
    if weight != Pango.Weight.NORMAL:
        css_parts.append(f"font-weight: {int(weight)};")

    # Font family and size
    css_parts.append(f"font-family: '{family}';")
    css_parts.append(f"font-size: {size}pt;")

    css_data = "* {{ {} }}".format(" ".join(css_parts))
    css_provider.load_from_data(css_data.encode())
    context = widget.get_style_context()
    context.add_provider(css_provider, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION)


def show_font_dialog(parent, title, button):
    if not hasattr(parent, "dlgFont"):
        parent.dlgFont = None

    if parent.dlgFont is None:
        # Get the actual window widget for transient_for
        parent_window = parent.main_widget if hasattr(parent, "main_widget") else None
        parent.dlgFont = Gtk.FontChooserDialog(title=title, parent=parent_window)
    parent.dlgFont.set_font(button.selected_font.to_string())

    response = parent.dlgFont.run()

    if response == Gtk.ResponseType.OK:
        font_desc = parent.dlgFont.get_font_desc()
        button.selected_font = font_desc
        button.set_label(button.selected_font.to_string())
        # Apply font using CSS
        label = button.get_children()[0]
        apply_font_to_widget(label, font_desc)
    parent.dlgFont.hide()


def show_open_dialog(parent, title, action):
    dlg = Gtk.FileChooserDialog(title=title, parent=parent, action=action)
    dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)

    dlg.add_button(
        "document-save" if action == Gtk.FileChooserAction.SAVE else "document-open",
        Gtk.ResponseType.OK,
    )
    dlg.set_do_overwrite_confirmation(True)
    if not hasattr(parent, "lastPath"):
        parent.lastPath = USERHOME_DIR
    dlg.set_current_folder(parent.lastPath)

    if dlg.run() == Gtk.ResponseType.OK:
        filename = dlg.get_filename()
        parent.lastPath = str(Path(filename).parent)
    else:
        filename = None
    dlg.destroy()
    return filename


def parse_color_rgba(spec: str) -> Gdk.RGBA:
    """Parse a color specification string to Gdk.RGBA."""
    rgba = Gdk.RGBA()
    _success = rgba.parse(spec)
    return rgba


def parse_color(spec: str) -> Gdk.Color:
    """Parse a color specification string to Gdk.Color."""
    return parse_color_rgba(spec).to_color()


def color_to_hex(rgba: Gdk.RGBA, diff: int = 0) -> str:
    """Convert Gdk.RGBA to a #rrggbb string, with diff added to each component.

    Each component is rounded, held to 0-255 and written as two digits. Written with `:x`,
    one under 16 lost a digit and one under 0 became `-e`. GTK cannot read most strings
    written so, and a host's colour saved as one came back white (#259).
    """
    return "#" + "".join(
        f"{min(255, max(0, round(component * 255) + diff)):02x}"
        for component in (rgba.red, rgba.green, rgba.blue)
    )


def stripe_color(rgba: Gdk.RGBA) -> str:
    """The server tree's second stripe, from its background: 14 darker on each component,
    or 14 lighter when one is under 14 and cannot be darkened that far. On a black tree,
    darker would be black as well (#259)."""
    darkest = min(round(component * 255) for component in (rgba.red, rgba.green, rgba.blue))
    return color_to_hex(rgba, -14 if darkest >= 14 else 14)


def get_key_name(event):
    name = ""
    if event.state & Gdk.ModifierType.CONTROL_MASK:
        name = name + "CTRL+"
    if event.state & Gdk.ModifierType.SHIFT_MASK:
        name = name + "SHIFT+"
    if event.state & Gdk.ModifierType.MOD1_MASK:
        name = name + "ALT+"
    if event.state & Gdk.ModifierType.SUPER_MASK:
        name = name + "SUPER+"
    return name + Gdk.keyval_name(event.keyval).upper()


def get_username() -> str | None:
    """Get the current username from environment variables."""
    return os.getenv("USER") or os.getenv("LOGNAME") or os.getenv("USERNAME")


def get_password() -> str:
    """Get the encryption password from username and key."""
    return (get_username() or "") + enc_passwd


def load_encryption_key() -> None:
    """Load the encryption key from file."""
    global enc_passwd
    try:
        if Path(KEY_FILE).exists():
            with Path(KEY_FILE).open() as f:
                enc_passwd = f.read()
        else:
            enc_passwd = ""
    except (OSError, PermissionError) as e:
        msgbox(f"Error trying to open key_file: {e}")
        enc_passwd = ""


def initialise_encyption_key() -> None:
    """Initialize a new encryption key and save it to file."""
    global enc_passwd
    # secrets, not random. This key encrypts the host passwords saved in gcm.conf, and
    # random.random() is a Mersenne Twister seeded from the clock, so the key was
    # reproducible by anyone who could estimate when it was generated. Existing key files
    # are untouched -- this only changes how a new one is made (bandit B311).
    enc_passwd = secrets.token_hex(16)
    try:
        # See writeConfig: the directory is main()'s job, but this must not depend on
        # main() having run -- the failure below is a modal dialog (#118).
        configpaths.ensure(CONFIG_DIRECTORY.path)
        with os.fdopen(os.open(KEY_FILE, os.O_WRONLY | os.O_CREAT, 0o600), "w") as f:
            f.write(enc_passwd)
    except (OSError, PermissionError) as e:
        msgbox(f"Error initialising key_file: {e}")


def encrypt(passw: str, string: str) -> str:
    """Encrypt a string for storage. See utils.crypto for the format."""
    return crypto.encrypt(passw, string)


def decrypt(passw: str, string: str) -> str:
    """Decrypt a stored string, choosing the legacy path from the config version.

    The `conf.VERSION` read lives here rather than in utils.crypto so that nothing in
    that module has to know about configuration.
    """
    return crypto.decrypt(passw, string, legacy=conf.VERSION == 0)


def vte_feed(terminal, data):
    if TERMINAL_V048 or (Vte.MAJOR_VERSION, Vte.MINOR_VERSION) >= (0, 42):
        try:
            terminal.feed_child(data.encode("utf-8"))
        except TypeError:
            # https://bugs.launchpad.net/ubuntu/+source/ubuntu-release-upgrader/+bug/1780501
            # The doc does not say clearly at which version the feed_child* function has lost # the "len" parameter :(
            terminal.feed_child(data, len(data))
    else:
        terminal.feed_child(data, len(data))


def timing_path_for(raw_path):
    """Companion timing file for a recording: `session.raw` -> `session.timing`."""
    return str(Path(raw_path).with_suffix(".timing"))


def plain_argv(args, argv_zero):
    """`args` as an ordinary argv, undoing GLib's FILE_AND_ARGV_ZERO repeat.

    That flag means "args[0] is the file to run, args[1] is the child's argv[0]", which
    is why the ssh and telnet paths repeat the command. The relay execs the inner
    command itself, taking argv[0] from it the ordinary way, so the repeat has to come
    back out -- left in, it arrives as a real argument, and `ssh.expect` reads its own
    path where it expects the connection type.
    """
    if not argv_zero or len(args) < 2:
        return list(args)
    return [args[0], *args[2:]]


def relay_command(args, socket_path=None, raw_path=None):
    """Wrap a command so it runs under the relay.

    Only used when a feature needs it. With both preferences off the caller spawns
    `args` untouched, so the default path is exactly what it was before the relay
    existed. Each destination is passed only when its own feature is on, so the relay
    does no work nobody asked for.
    """
    command = [sys.executable, "-m", "gnome_connection_manager.relay"]
    if socket_path:
        command += ["--clipboard-socket", socket_path]
    if raw_path:
        # The timing file sits beside the recording; without it the stream cannot be
        # replayed frame by frame, only read end to end.
        command += ["--raw-log", raw_path, "--timing-log", timing_path_for(raw_path)]
    return [*command, "--", *args]


def note_child_pid(terminal, pid, error, _user_data=None):
    """Keep the pid of the process a terminal spawned, which a host's commands after
    login find its session's program from (#312)."""
    terminal.child_pid = pid if error is None and pid > 0 else None


def vte_run(terminal, command, arg=None, environment=None):
    terminal.child_pid = None
    term_type = (
        terminal.host.term
        if hasattr(terminal, "host") and terminal.host.term
        else conf.TERM or os.getenv("TERM") or DEFAULT_TERM_TYPE
    )
    # Set terminal environment variables so the child inherits them.
    # VTE does not automatically add these to spawned children; the host
    # app must provide them.  Programs use COLORTERM and VTE_VERSION to
    # detect terminal capabilities and choose appropriate characters.
    saved_env = {}
    for var, val in [
        ("TERM", term_type),
        ("COLORTERM", "truecolor"),
        (
            "VTE_VERSION",
            f"{Vte.MAJOR_VERSION * 10000 + Vte.MINOR_VERSION * 100 + Vte.MICRO_VERSION}",
        ),
    ]:
        saved_env[var] = os.environ.get(var)
        os.environ[var] = val
    args = []

    # Check if this is a local shell before modifying args
    is_local_shell = command == SHELL
    flag_spawn = GLib.SpawnFlags.DEFAULT if is_local_shell else GLib.SpawnFlags.FILE_AND_ARGV_ZERO

    # For local shells, unset VIRTUAL_ENV
    if is_local_shell:
        args.append("env")
        args.append("-u")
        args.append("VIRTUAL_ENV")
        args.append(command)
    else:
        args.append(command)

    if arg:
        args += arg
    # wMain the same way sync_shortcut_accels reaches it: the global is bound late, and
    # declaring it at module scope would retype it for every other user.
    controller = globals().get("wMain")
    socket_path = controller.clipboard_relay_path() if conf.OSC52_ENABLED and controller else None
    raw_path = session_file_for(terminal, ".raw") if conf.RAW_SESSION_LOG else None
    # Kept on the terminal so Save Transcript can find this session's recording; the
    # path is otherwise built here and forgotten.
    terminal.raw_path = raw_path
    if socket_path or raw_path:
        # Spawning is otherwise byte-for-byte what it was; the relay only enters the
        # path when a preference asks for it, so the default carries none of its risk.
        #
        # The relay's own argv is an ordinary one, so asking GLib for FILE_AND_ARGV_ZERO
        # here makes it swallow `-m` as the child's argv[0] and python then looks for a
        # script named after the module, in $HOME (#91). Hand the relay a plain argv and
        # let GLib take ours literally; the relay reproduces the same child argv when it
        # execs the inner command.
        args = relay_command(plain_argv(args, not is_local_shell), socket_path, raw_path)
        flag_spawn = GLib.SpawnFlags.DEFAULT

    # The command's own variables, such as a command host's password (#248). Given to
    # VTE, which adds them to what the child inherits, measured, directly and through
    # the relay, so that a password never enters GCM's own environment as TERM does.
    envv = [f"{name}={value}" for name, value in environment.items()] if environment else None
    if TERMINAL_V048:
        terminal.spawn_async(
            Vte.PtyFlags.DEFAULT,
            os.getenv("HOME"),
            args,
            envv,
            flag_spawn | GLib.SpawnFlags.SEARCH_PATH,
            None,
            None,
            -1,
            None,
            note_child_pid,
            None,
        )
    else:
        _spawned, pid = terminal.spawn_sync(
            Vte.PtyFlags.DEFAULT,
            os.getenv("HOME"),
            args,
            envv,
            flag_spawn | GLib.SpawnFlags.DO_NOT_REAP_CHILD | GLib.SpawnFlags.SEARCH_PATH,
            None,
            None,
            None,
        )
        note_child_pid(terminal, pid, None)
    # Restore environment so other spawns with different settings aren't affected
    for var, old_val in saved_env.items():
        if old_val is not None:
            os.environ[var] = old_val
        elif var in os.environ:
            del os.environ[var]


def connection_programs():
    """What a connection's command runs. Read at each spawn, so that a test which swaps
    SSH_COMMAND for a copy of the script is heard."""
    return connections.Programs(
        SSH_COMMAND, get_username(), SSH_BIN, TEL_BIN, rdp_client=conf.RDP_CLIENT
    )


def connection_command(host, desktop=None):
    """What a host's session spawns, as a terminal keeps it: (program, argv, environment).
    For an RDP desktop shown in its tab, given where FreeRDP draws and the tab's size now
    (#227)."""
    programs = connection_programs()
    if desktop is not None:
        programs = dataclasses.replace(programs, tab_window=desktop.tab_window())
    spawn = connections.for_host(host).command(host, programs)
    return (spawn.program, spawn.argv, spawn.environment)


def spawn_command(terminal):
    """Spawn the terminal's command, as addTab and Reconnect do. An RDP desktop shown in
    its tab has the command built again, for the tab's size now, and looks for FreeRDP's
    window once it runs (#227)."""
    desktop = getattr(terminal, "desktop", None)
    if desktop is not None:
        terminal.command = connection_command(terminal.host, desktop)
    program, argv, environment = terminal.command
    vte_run(terminal, program, argv, environment)
    if desktop is not None:
        desktop.started()
    while Gtk.events_pending():
        Gtk.main_iteration()


def keyboard_of(widget):
    """What takes the keyboard for a tab whose `widget` would: the RDP desktop shown in
    a terminal's place, rather than the terminal hidden behind it, whose keys would reach
    FreeRDP's terminal (#227). Anything else takes it itself."""
    desktop = getattr(widget, "desktop", None)
    return desktop if desktop is not None and desktop.get_visible() else widget


def page_terminal(page):
    """The terminal a console page holds, or None when the page holds something else.

    A page is what a notebook holds for a tab. addTab builds one around a terminal, and
    add_page opens any other kind (#223), so nothing may take a page's first child for a
    terminal without asking here.
    """
    children = page.get_children() if hasattr(page, "get_children") else []
    if children and isinstance(children[0], Vte.Terminal):
        return children[0]
    return None


def window_title(tab_text):
    """A window's title: GCM's, then the name of the tab the window shows, if it has one."""
    if tab_text:
        return f"{conf.APP_TITLE or app_name} - {tab_text.strip()}"
    return conf.APP_TITLE or app_name


# -- the open-console list, shared by the tab-strip dropdown and the menubar (#84) ------


class ConsoleEntry:
    """One row of the open-console list: what to render, and what to raise."""

    def __init__(self, notebook, page, label, position, accel=None, current=False):
        self.notebook = notebook
        self.page = page
        self.label = label
        self.position = position
        self.accel = accel
        self.current = current

    @property
    def text(self):
        """What the tab strip renders, not the tab's identity.

        get_text() deliberately returns the identity so a program-set title cannot
        decide what a clone connects to. Here the opposite is wanted: the title is
        the half that tells two sessions of the same program apart, which is the
        whole point of listing them.
        """
        if hasattr(self.label, "get_display_text"):
            return self.label.get_display_text().strip()
        if hasattr(self.label, "get_text"):
            return (self.label.get_text() or "").strip()
        return ""

    @property
    def path(self):
        """The tab's host's whole path, where it says more than the tab's name (#347)."""
        if hasattr(self.label, "get_path"):
            return self.label.get_path()
        return ""

    @property
    def active(self):
        """False once the session behind the tab has exited."""
        return bool(getattr(self.label, "is_active", True))

    @property
    def attention(self):
        """True while the tab is flagged for a bell the user has not looked at."""
        return bool(getattr(self.label, "needs_attention", False))


def console_shortcut_hints(bound=None):
    """The configured key for consoles 1-9, by position, or None where unbound.

    Read from the shortcuts table rather than hardcoded: a fixed Alt+N here would
    drift from whatever the user actually has bound, which is the shape of #3 and
    #15. The keys address a position inside one notebook, so the same nine repeat
    in every pane.
    """
    if bound is None:
        bound = {
            command[0]: key
            for key, command in shortcuts.items()
            if isinstance(command, list) and command
        }
    return [bound.get(f"console_{n}") for n in range(1, 10)]


def console_entries(notebook, focused_page=None, hints=None):
    """The consoles open in `notebook`, in tab order."""
    if hints is None:
        hints = console_shortcut_hints()
    entries = []
    for position in range(notebook.get_n_pages()):
        page = notebook.get_nth_page(position)
        entries.append(
            ConsoleEntry(
                notebook,
                page,
                notebook.get_tab_label(page),
                position,
                hints[position] if position < len(hints) else None,
                page is not None and page is focused_page,
            )
        )
    return entries


def console_item_markup(entry):
    """Pango markup for one console row.

    Mirrors what the tab strip already says: a finished session is struck through
    the way mark_tab_as_closed renders it, and the key is shown with the small blue
    prefix the custom-commands menu uses. The host's whole path goes under it (#347).
    """
    text = GLib.markup_escape_text(entry.text)
    if not entry.active:
        text = f"<span color='darkgray' strikethrough='true'>{text}</span>"
    elif entry.attention:
        text = f"<b>{text}</b>"
    if entry.accel:
        text = (
            "<span foreground='blue' size='x-small'>"
            f"[{GLib.markup_escape_text(entry.accel)}]</span> {text}"
        )
    return with_path(text, entry.path)


def with_path(markup, path):
    """`markup` over a host's whole path, smaller and fainter, on a line of its own, as the
    open-console list and the cluster window show a console (#347). `markup` alone where
    there is no path.

    A line of its own, measured: as a tooltip, a row's path showed half a second after the
    pointer stopped on that row, one row at a time, over the rows below, and beside the
    name it made the menu twice as wide. Fainter by alpha rather than a colour, so that it
    follows the theme's text, on a row the pointer is over too.
    """
    if not path:
        return markup
    return f"{markup}\n<span size='small' alpha='60%'>{GLib.markup_escape_text(path)}</span>"


class Wmain(GladeComponent):
    # new() gives each Wmain its own. These are for one built without it, as tests
    # build one: no console window, none in use, and no tab being dragged (#255), and no
    # host being mounted, and no application whose menus list the mounts (#267), and no
    # console open (#346), and no update check running (#369).
    console_windows: tuple = ()
    window_in_use: object = None
    dragged_tab: object = None
    mounting: frozenset = frozenset()
    application: object = None
    count: int = 0
    update_check: object = None

    def __init__(
        self, path="gnome-connection-manager.glade", root="wMain", domain=domain_name, **kwargs
    ):
        path = str(Path(glade_dir) / path)
        application = kwargs.get("application")
        super().__init__(path, root, domain, application=application)

        global wMain
        wMain = self

        load_encryption_key()

        self.initLeftPane()

        self.createMenu()
        self.window = self.get_widget("wMain")
        for menu in (self.popupMenu, self.popupMenuFolder, self.popupMenuTab):
            menu.attach_to_widget(self.window, None)
        self.window.connect("set-focus", self.on_window_set_focus)
        self.window.connect("key-press-event", self.on_window_key_press)

        self._current_fullscreen_state = False
        self._context_terminal = None
        self._context_tab_widget = None
        self._context_tree_path = None
        self._drag_source_path = None

        if conf.VERSION == 0:
            initialise_encyption_key()

        settings = Gtk.Settings.get_default()
        settings.set_property("gtk-menu-images", True)
        settings.set_property("gtk-button-images", True)
        settings.props.gtk_menu_bar_accel = None

        self.enable_window_transparency(self.window)
        self.window.connect("style-updated", self.enable_window_transparency)

        self.update_visual()
        self.get_widget("wMain").get_screen().connect("composited-changed", self.update_visual)

        if conf.WINDOW_WIDTH != -1 and conf.WINDOW_HEIGHT != -1:
            # The saved geometry may come from a larger monitor than this one.
            self.get_widget("wMain").resize(
                *clamp_to_workarea(conf.WINDOW_WIDTH, conf.WINDOW_HEIGHT, monitor_workarea())
            )
        else:
            self.get_widget("wMain").maximize()
        self.get_widget("wMain").show()
        # Just added children in glade to eliminate GTK warning, remove all children
        for x in self.nbConsole.get_children():
            self.nbConsole.remove(x)
        self.nbConsole.set_scrollable(True)
        self.install_console_button(self.nbConsole)
        self.nbConsole.set_group_name("11")
        self.nbConsole.connect("page_removed", self.on_page_removed)
        self.nbConsole.connect("page-added", self.on_page_added)
        self.nbConsole.add_events(Gdk.EventMask.SCROLL_MASK | Gdk.EventMask.SMOOTH_SCROLL_MASK)
        self.nbConsole.connect("scroll-event", self.on_tab_scroll)
        self.watch_tab_drags(self.nbConsole)

        self.hpMain.previous_position = 150

        if conf.LEFT_PANEL_WIDTH != 0:
            self.set_panel_visible(conf.SHOW_PANEL)
        self.fit_toolbar_items()
        self.set_toolbar_visible(conf.SHOW_TOOLBAR)

        # a veces no se posiciona correctamente con 400 ms, asi que se repite el llamado
        GLib.timeout_add(400, lambda: self.hpMain.set_position(conf.LEFT_PANEL_WIDTH))
        GLib.timeout_add(900, lambda: self.hpMain.set_position(conf.LEFT_PANEL_WIDTH))

        if conf.HIDE_DONATE:
            self.get_widget("btnDonate").hide()

        if conf.CHECK_UPDATES:
            GLib.timeout_add(2000, lambda: self.check_updates())

        # load style.css
        screen = Gdk.Screen.get_default()
        provider = Gtk.CssProvider()
        provider.load_from_path(BASE_PATH + "/style.css")
        Gtk.StyleContext.add_provider_for_screen(
            screen, provider, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION
        )

        self.get_widget("txtSearch").set_placeholder_text(_("buscar..."))

        if conf.STARTUP_LOCAL:
            self.addTab(self.nbConsole, "local")

    def open_cli_targets(self, args):
        for arg in args:
            i = arg.rfind("/")
            if i == -1:
                continue
            group = arg[:i]
            name = arg[i + 1 :]
            if not group or not name or group not in groups:
                continue
            for host in groups[group]:
                if host.name == name:
                    self.addTab(self.nbConsole, host)
                    break

    def update_visual(self):
        window = self.get_widget("wMain")
        screen = window.get_screen()
        visual = screen.get_rgba_visual()
        if visual and screen.is_composited():
            # NOTE: We should re-realize window when update window visual
            # Otherwise it may failed, when the gcm is started without compositor
            window.unrealize()
            window.set_visual(visual)
            window.transparency = True
            window.realize()
            if window.get_property("visible"):
                window.hide()
                window.show()
        else:
            sys.stderr.write("System doesn't support transparency\n")
            window.transparency = False
            window.set_visual(screen.get_system_visual())

    def enable_window_transparency(self, window):
        # hack to allow transparent widgets inside a opaque window
        # the key is to set the alpha channel of the window's background color to 0.9999, in that way the window is opaque but still allows transparent children

        # remove previously added css to get the background color from the current gtk theme
        if hasattr(window, "style_provider") and window.style_provider:
            Gtk.StyleContext.remove_provider_for_screen(
                Gdk.Screen.get_default(), window.style_provider
            )

        # get window background color
        context = window.get_style_context()
        color = context.get_property("background-color", Gtk.StateFlags.NORMAL)

        # set the background color to the same as the gtk theme, but with alpha 0.99999 (it looks opaque but allows to have transparent widgets)
        CSS = b"""
        window.background {
            background-color: rgba(%d, %d, %d, %f);
        }
        """ % (color.red * 255, color.green * 255, color.blue * 255, 0.999999)

        window.style_provider = Gtk.CssProvider()
        window.style_provider.load_from_data(CSS)

        context.add_provider_for_screen(
            window.get_screen(), window.style_provider, Gtk.STYLE_PROVIDER_PRIORITY_APPLICATION
        )

    # -- Wmain.new {
    def new(self):
        self.hpMain = self.get_widget("hpMain")
        self.wMainWindow = self.builder.get_object("wMain")
        self.nbConsole = self.get_widget("nbConsole")
        self.treeServers = self.get_widget("treeServers")
        # The server pane is a notebook: the tree's tab, Servers, which names the pane in
        # place of the tree's header, and beside it, while anything is mounted, a tab
        # listing the mounts (#269). It is no console pane, so the code that looks for
        # those looks right of it, in console_side.
        self.nbServers = self.get_widget("nbServers")
        self.treeMounts = self.get_widget("treeMounts")
        self.lblMountsTab = self.get_widget("lblMountsTab")
        # The host list is a nested widget menu rebuilt by updateTree, so it stays a
        # real Gtk.Menu rather than moving into the menu model.
        self.menuServers = Gtk.Menu()
        # Filled on the way open rather than kept live: see build_console_menu.
        self.menuConsoles = Gtk.Menu()
        self.menuConsoles.connect("show", self.build_console_menu)
        self.menubar = None
        self.install_menubar()
        # The main window's console notebook the keyboard was last in, whatever its tab
        # holds: where an action goes once the keyboard has left for the server tree or the
        # search box. It replaces the last terminal given the keyboard, which a click never
        # set and a tab without a terminal could not be (#223).
        self.last_notebook = None
        # The windows consoles were moved out to, and which window, one of those or the
        # main one, last had the keyboard: the tab in use is in that one (#255).
        self.console_windows = ()
        self.window_in_use = None
        # The tab a drag between notebooks carries, while it does (#255).
        self.dragged_tab = None
        # The folders sshfs is mounting a host at, until it exits (#267).
        self.mounting = frozenset()
        self.count = 0
        self.row_activated = False

    # -- Wmain.new }

    # -- Wmain custom methods {
    #   Write your own methods here

    def check_updates(self):
        """Ask this repository for its release tags, and say when one is newer than the
        running GCM (#295). In a process of its own: asked on a thread, a GCM quit during
        the request exited with the thread still inside it (#369)."""
        command = [
            sys.executable,
            "-m",
            "gnome_connection_manager.utils.updates",
            updates.TAGS_URL,
        ]
        try:
            self.update_check = Gio.Subprocess.new(
                command, Gio.SubprocessFlags.STDOUT_PIPE | Gio.SubprocessFlags.STDERR_SILENCE
            )
        except GLib.Error:
            return
        self.update_check.communicate_async(None, None, self.on_update_check_done)

    def on_update_check_done(self, process, result):
        self.update_check = None
        try:
            _done, answer, _errors = process.communicate_finish(result)
            if not process.get_successful():
                return
            tags = updates.tag_names(json.loads(answer.get_data()))
        except (GLib.Error, ValueError):
            # No network, a refused request, an answer that is not JSON: no notice.
            return
        release = updates.newer_release(tags, app_version)
        if release:
            self.show_newer_release(release)

    def show_newer_release(self, release):
        available = _("GCM {new} is available. You are running {current}.").format(
            new=release, current=app_version
        )
        install = _("How to install it: {url}").format(url=updates.INSTALL_PAGE)
        msginfo(f"{available}\n\n{install}", self.get_widget("wMain"))

    def on_terminal_click(self, widget, event, *args):
        if event.type == Gdk.EventType.BUTTON_PRESS and event.button == 3:
            # Ctrl+right-click opens the menu even while right-click pastes, which it does
            # by default. Nothing else opens this menu, so without it the menu could not be
            # reached at all, while the guide sent readers to it for actions (#171).
            if conf.PASTE_ON_RIGHT_CLICK and not event.get_state() & Gdk.ModifierType.CONTROL_MASK:
                self.terminal_paste(widget)
            else:
                self.set_context_terminal(widget)
                self.popupMenu.mnuCopy.set_sensitive(widget.get_has_selection())
                # A console window has no splits (#255).
                in_window = self.console_window_of(widget.get_parent().get_parent()) is not None
                self.popupMenu.mnuSplitH.set_visible(not in_window)
                self.popupMenu.mnuSplitV.set_visible(not in_window)
                self.popupMenu.terminal = widget
                # Use popup_at_rect with manual position calculation for proper placement
                if hasattr(self.popupMenu, "popup_at_rect"):
                    # Create a rectangle at the click position
                    rect = Gdk.Rectangle()
                    rect.x = int(event.x)
                    rect.y = int(event.y)
                    rect.width = 1
                    rect.height = 1

                    window = widget.get_window()

                    # Calculate position to determine if we need to flip
                    display = widget.get_display()
                    monitor = display.get_monitor_at_window(window)
                    workarea = monitor.get_workarea()
                    abs_x, abs_y = window.get_root_coords(rect.x, rect.y)

                    # Get menu size - use estimate since actual size isn't known until shown
                    menu_height = 250

                    # Determine gravity based on available space
                    margin = 50
                    if abs_y + menu_height + margin > workarea.y + workarea.height:
                        # Not enough space below - position menu above
                        rect_anchor = Gdk.Gravity.NORTH_WEST
                        menu_anchor = Gdk.Gravity.SOUTH_WEST
                    else:
                        # Enough space below - position menu below
                        rect_anchor = Gdk.Gravity.SOUTH_WEST
                        menu_anchor = Gdk.Gravity.NORTH_WEST

                    # Popup at rect with calculated gravity
                    self.popupMenu.popup_at_rect(window, rect, rect_anchor, menu_anchor, event)
                else:
                    # Fallback for older GTK
                    self.popupMenu.popup(None, None, None, None, event.button, event.time)

            # enable/disable split menu
            nb = widget.get_parent().get_parent()
            self.popupMenu.mnuSplitH.set_sensitive(nb.get_n_pages() > 1)
            self.popupMenu.mnuSplitV.set_sensitive(nb.get_n_pages() > 1)

            return True

        elif (
            event.type == Gdk.EventType.BUTTON_PRESS
            and event.button == 1
            and event.get_state() & Gdk.ModifierType.CONTROL_MASK
        ):
            url, tag = widget.match_check_event(event)
            if url and tag is not None and tag == getattr(widget, "tag_file", None):
                self.open_file_location(widget, url)
                return True
            if tag == widget.tag_url:
                url = f"http://{url}"
            elif tag == widget.tag_email and not url.lower().startswith("mailto:"):
                # Not mailto://, which a URI parser reads as a user at a host, leaving the
                # path, where mailto: keeps its addresses, empty (#232).
                url = f"mailto:{url}"
            url = url or widget.hyperlink_check_event(event)
            if url:
                # As a web host's page opens, and for the same reason: Gtk.show_uri raised
                # where GIO found no browser, and the link did nothing (#232).
                open_in_browser(url)

        # terminal does not emit the "focus" signal when there is more than one visible on the screen, so force the focus
        nb = widget.get_parent().get_parent()
        self.on_tab_focus(nb, nb.get_nth_page(nb.get_current_page()), nb.get_current_page())

    def on_terminal_keypress(self, widget, event, *args):
        # Any key but a modifier alone stops a countdown to reconnecting (#239).
        if getattr(widget, "reconnect_pending", None) is not None and (
            event.keyval not in MODIFIER_KEYS
        ):
            self.stop_reconnecting(widget)
            return True
        # Custom sequences are consulted after the built-in commands and skipped for any
        # key a shortcut claims, so a [keys] entry can never shadow copy, paste or find --
        # including when a shortcut is rebound onto one after the fact.
        key_name = get_key_name(event)
        if key_name not in shortcuts and key_name in custom_keys:
            widget.feed_child(custom_keys[key_name])
            return True
        # if shortcuts.has_key(get_key_name(event)):
        if get_key_name(event) in shortcuts:
            cmd = shortcuts[get_key_name(event)]
            if isinstance(cmd, list):
                # comandos predefinidos
                if cmd == _COPY:
                    self.terminal_copy(widget)
                elif cmd == _PASTE:
                    self.terminal_paste(widget)
                elif cmd == _COPY_ALL:
                    self.terminal_copy_all(widget)
                elif cmd == _SAVE:
                    self.show_save_buffer(widget)
                elif cmd == _FIND:
                    self.focus_search()
                elif cmd == _FIND_NEXT:
                    if hasattr(self, "search"):
                        self.find_word()
                elif cmd == _ZOOM_IN:
                    self.terminal_zoom_in(widget)
                elif cmd == _ZOOM_OUT:
                    self.terminal_zoom_out(widget)
                elif cmd == _ZOOM_RESET:
                    self.terminal_zoom_reset(widget)
                elif cmd == _VIEW_BUFFER:
                    self.show_buffer_viewer(widget)
                elif cmd == _SNIPPETS:
                    self.show_snippet_picker(widget)
                elif cmd == _CLEAR:
                    widget.reset(True, True)
                elif cmd == _FIND_BACK:
                    if hasattr(self, "search"):
                        self.find_word(backwards=True)
                elif cmd == _CLONE:
                    term = widget
                    ntbk = widget.get_parent().get_parent()
                    tab = ntbk.get_tab_label(term.get_parent())
                    if not hasattr(term, "host"):
                        self.addTab(ntbk, tab.get_text())
                    else:
                        host = term.host.clone()
                        # Deliberately keeping host.name: overwriting it with the tab
                        # label put presentation into the Host object and into log paths.
                        host.log = hasattr(term, "log_handler_id") and term.log_handler_id != 0
                        # The same host in a second session, not a second host, so its id
                        # too: its tab is named as the original's, and follows it (#346).
                        host.id = term.host.id
                        self.addTab(ntbk, host)
                elif cmd == _CONSOLE_PREV:
                    self.console_previous(widget.get_parent().get_parent())
                elif cmd == _CONSOLE_NEXT:
                    self.console_next(widget.get_parent().get_parent())
                elif cmd == _FULLSCREEN:
                    self.toggle_fullscreen()
                elif cmd == _CONSOLE_CLOSE:
                    wid = widget.get_parent()
                    page = widget.get_parent().get_parent().page_num(wid)
                    if page != -1:
                        widget.get_parent().get_parent().remove_page(page)
                        wid.destroy()
                elif cmd == _CONSOLE_WINDOW:
                    self.toggle_console_window(widget.get_parent())
                elif cmd == _CONSOLE_RECONNECT:
                    # Reconnect sends no commands after login, so nothing waits for them.
                    self.stop_commands(widget)
                    if not hasattr(widget, "command"):
                        # widget.fork_command(SHELL)
                        vte_run(widget, SHELL)
                    else:
                        spawn_command(widget)
                    widget.get_parent().get_parent().get_tab_label(
                        widget.get_parent()
                    ).mark_tab_as_active()
                    return True
                elif cmd == _CONNECT:
                    self.on_btnConnect_clicked(None)
                elif cmd[0][0:8] == "console_":
                    page = int(cmd[0][8:]) - 1
                    widget.get_parent().get_parent().set_current_page(page)
                elif cmd == _NEW_LOCAL:
                    self.on_btnLocal_clicked(None)
            else:
                # A snippet's key (#240).
                self.send_snippet(cmd, widget)

            return True
        return self.hold_key(widget, event)

    def install_menubar(self):
        """Render the application's menu model as a real widget.

        set_menubar() only reaches the screen through GtkApplicationWindow's
        show-menubar machinery, and wMain is a plain GtkWindow, so the model has to
        be turned into a GtkMenuBar by hand and packed into the layout.
        """
        application = Gtk.Application.get_default()
        model = application.get_menubar() if application is not None else None
        box = self.get_widget("mainBox")
        if model is None or box is None:
            return
        self.menubar = Gtk.MenuBar.new_from_model(model)
        hosts_item = Gtk.MenuItem(label=_("_Hosts"))
        hosts_item.set_use_underline(True)
        hosts_item.set_submenu(self.menuServers)
        # before Help, which the model appends last
        self.menubar.insert(hosts_item, max(len(self.menubar.get_children()) - 1, 0))
        self.install_console_menu()
        box.pack_start(self.menubar, False, False, 0)
        box.reorder_child(self.menubar, 0)
        self.menubar.show_all()

    def find_menubar_item(self, label):
        """The menu GTK built for the model's `label`, or None."""
        if self.menubar is None:
            return None
        for item in self.menubar.get_children():
            if hasattr(item, "get_label") and item.get_label() == label:
                return item
        return None

    def install_console_menu(self):
        """Hang the open-console list off the bottom of the Terminal menu.

        Appending a hand-built item to a menu GTK built from the model is what the
        Hosts entry already does, and model items keep their own positions, so this
        stays below Close Console however the model is edited later. It has to be a
        real Gtk.Menu rather than another model section: the rows carry markup for
        the struck-through and flagged states, which a menu model cannot express.
        """
        terminal_item = self.find_menubar_item(_("_Terminal"))
        submenu = terminal_item.get_submenu() if terminal_item is not None else None
        if submenu is None:
            return None
        separator = Gtk.SeparatorMenuItem()
        separator.show()
        submenu.append(separator)
        consoles_item = Gtk.MenuItem(label=_("Open Consoles"))
        consoles_item.set_submenu(self.menuConsoles)
        consoles_item.show()
        submenu.append(consoles_item)
        return consoles_item

    def refresh_menu_accels(self):
        """Re-render the accelerators shown in the hand-built context menus."""
        for name in ("popupMenu", "popupMenuTab", "popupMenuFolder"):
            apply_menu_accels(getattr(self, name, None))

    def collect_notebooks(self, widget, found=None):
        """Every console notebook under `widget`, in on-screen order.

        Splitting nests notebooks inside a Gtk.Paned, so a depth-first walk visits
        them the way they are laid out: left to right for a horizontal split, top to
        bottom for a vertical one. Terminals live inside notebooks, so a notebook
        ends the descent.
        """
        if found is None:
            found = []
        if isinstance(widget, Gtk.Notebook):
            found.append(widget)
            return found
        if hasattr(widget, "get_children"):
            for child in widget.get_children():
                self.collect_notebooks(child, found)
        return found

    def console_side(self):
        """The main window's consoles: right of the server pane, a console notebook or the
        panes a split made. Never the whole window, where the server pane's notebook, the
        tree and its Mounted tab, would count as a console pane (#269)."""
        return self.hpMain.get_child2()

    def console_notebooks(self):
        """Every console notebook: the main window's panes, then each console window's.

        A console window holds one notebook and no splits (#255). Those are listed in the
        order the windows opened.
        """
        notebooks = self.collect_notebooks(self.console_side())
        notebooks.extend(window.notebook for window in self.console_windows)
        return notebooks

    def console_window_of(self, notebook):
        """The console window holding `notebook`, or None for a pane of the main window."""
        for window in self.console_windows:
            if window.notebook is notebook:
                return window
        return None

    def window_of(self, notebook):
        """The window a console notebook is in: its console window, or the main window."""
        return self.console_window_of(notebook) or self.wMain

    def open_console_groups(self):
        """Every open console, grouped by the pane or console window it is in."""
        focused = self.page_in_use()
        hints = console_shortcut_hints()
        return [
            (notebook, console_entries(notebook, focused, hints))
            for notebook in self.console_notebooks()
        ]

    def apply_preferences_to_terminal(self, terminal):
        """Set on one terminal everything Preferences decides about a console (#181).

        addTab calls this for a new console, and apply_settings_to_open_consoles for each
        open one when Preferences closes with OK, so the two come out the same. A host's
        own colours win when it sets both. Without colours set_colors is still called,
        with None: that draws exactly what a new terminal draws, and undoes any colours
        and transparency given before -- both measured. set_font leaves a console's zoom
        alone, since VTE keeps the scale apart from the font.
        """
        host = getattr(terminal, "host", None)
        fcolor = getattr(host, "font_color", "") or ""
        bcolor = getattr(host, "back_color", "") or ""
        if not fcolor or not bcolor:
            fcolor, bcolor = conf.FONT_COLOR, conf.BACK_COLOR
        terminal.set_word_char_exceptions(conf.WORD_SEPARATORS)
        terminal.set_scrollback_lines(conf.BUFFER_LINES)
        if fcolor and bcolor:
            palette = [parse_color_rgba(colour) for colour in TERMINAL_PALETTE]
            terminal.set_colors(parse_color_rgba(fcolor), parse_color_rgba(bcolor), palette)
        else:
            terminal.set_colors(None, None, None)
        if conf.TRANSPARENCY > 0 and self.wMain.transparency:
            # set_opacity only works if the parent is transparent too, so the background
            # carries the alpha instead. After set_colors, which would reset it.
            background = parse_color_rgba(bcolor if bcolor else DEFAULT_BGCOLOR)
            background.alpha = 1 - (conf.TRANSPARENCY / 100)
            terminal.set_color_background(background)
        terminal.set_font(Pango.FontDescription(conf.FONT or "monospace"))
        terminal.set_audible_bell(bool(conf.BELL_AUDIBLE))

    def apply_settings_to_open_consoles(self):
        """Give the consoles already open the settings Preferences has just stored (#174).

        addTab sets the scrollback size when it makes a terminal, and a tab renders the
        program's title only when the title changes, so both reached only consoles opened
        afterwards. VTE drops the oldest rows at once when the size shrinks below what a
        session holds -- measured, and raising it again does not bring them back.
        """
        for _notebook, entries in self.open_console_groups():
            for entry in entries:
                terminal = page_terminal(entry.page)
                if terminal is not None:
                    self.apply_preferences_to_terminal(terminal)
                if hasattr(entry.label, "render_label"):
                    entry.label.render_label()

    def create_console_menu_item(self, entry):
        """One console's row, marked when it is the console holding the keyboard."""
        item = Gtk.CheckMenuItem(label="")
        item.set_draw_as_radio(True)
        # set_active() emits activate, so the state goes on before the handler does.
        item.set_active(entry.current)
        item.get_children()[0].set_markup(console_item_markup(entry))
        item.connect("activate", self.on_console_menu_item_activate, entry)
        item.show()
        return item

    def build_console_menu(self, menu):
        """Fill `menu` with one item per open console, grouped by pane and console window.

        Rebuilt from scratch on every open. Keeping it live instead would mean
        invalidating on eight signals, one of which is the window title an agent
        CLI rewrites continuously; the list is small enough that rebuilding is
        cheaper than tracking.
        """
        menu.foreach(menu.remove)
        pane_groups = self.open_console_groups()
        # Pane numbers only mean something once there is more than one pane.
        headings = sum(1 for _notebook, entries in pane_groups if entries) > 1
        listed = panes = windows = 0
        for notebook, entries in pane_groups:
            # The main window's panes come first, then the console windows (#255).
            if self.console_window_of(notebook) is None:
                panes += 1
                title = _("Pane {}").format(panes)
            else:
                windows += 1
                title = _("Window {}").format(windows)
            if not entries:
                continue
            if headings:
                if listed:
                    separator = Gtk.SeparatorMenuItem()
                    separator.show()
                    menu.append(separator)
                heading = Gtk.MenuItem(label=title)
                heading.set_sensitive(False)
                heading.show()
                menu.append(heading)
            for entry in entries:
                menu.append(self.create_console_menu_item(entry))
                listed += 1
        if not listed:
            empty = Gtk.MenuItem(label=_("No open consoles"))
            empty.set_sensitive(False)
            empty.show()
            menu.append(empty)
        return menu

    def on_console_menu_item_activate(self, _item, entry):
        self.focus_console(entry.notebook, entry.page)

    def focus_console(self, notebook, page):
        """Raise `page` and put the keyboard in it, whichever pane or window it is in.

        In its terminal, or on a page that holds something else, in the first thing there
        that takes the keyboard. Failing that, on the notebook's tabs, which is where
        clicking such a tab leaves it, measured (#223). A console in another window brings
        that window to the front (#255).
        """
        position = notebook.page_num(page) if page is not None else -1
        if position < 0:
            return False
        notebook.set_current_page(position)
        window = self.window_of(notebook)
        self.use_window(window)
        terminal = page_terminal(page)
        if terminal is not None:
            window.set_focus(keyboard_of(terminal))
            self.on_tab_focus(terminal)
            return True
        focus = window.get_focus()
        inside = focus is not None and (focus == page or focus.is_ancestor(page))
        if not inside and not page.child_focus(Gtk.DirectionType.TAB_FORWARD):
            notebook.grab_focus()
        self.on_tab_focus(notebook, page)
        return True

    def install_console_button(self, notebook):
        """Put the open-console dropdown at the end of a notebook's tab strip.

        GTK packs an END action widget outside the overflow arrows rather than among
        the tabs, so the button lands to the right of the arrows and never scrolls
        out of reach -- which is the point, since that is when a tab list is wanted.
        """
        if not hasattr(notebook, "set_action_widget"):
            return None
        if notebook.get_action_widget(Gtk.PackType.END) is not None:
            return None
        button = Gtk.Button()
        button.set_relief(Gtk.ReliefStyle.NONE)
        button.set_focus_on_click(False)
        button.add(Gtk.Image.new_from_icon_name("pan-down-symbolic", Gtk.IconSize.MENU))
        button.set_tooltip_text(_("List open consoles"))
        menu = Gtk.Menu()
        menu.attach_to_widget(self.window, None)
        # On the press, with the event in hand, the way every other menu here opens.
        # Opening from "clicked" runs on the release and leaves GTK to dig the event
        # out of Gtk.get_current_event(), which is not always there: GTK's own toolbar
        # overflow menu passes nothing and warns "no trigger event for menu popup",
        # and a popup mapped without one is unreliable under Wayland.
        button.connect("button-press-event", self.on_console_button_pressed, menu)
        # The press is consumed, so "clicked" only reaches here from the keyboard.
        button.connect("clicked", self.on_console_button_clicked, menu)
        notebook.set_action_widget(button, Gtk.PackType.END)
        button.show_all()
        return button

    def on_console_button_pressed(self, button, event, menu):
        if event.type != Gdk.EventType.BUTTON_PRESS or event.button != 1:
            return False
        self.show_console_menu(button, menu, event)
        return True

    def on_console_button_clicked(self, button, menu):
        self.show_console_menu(button, menu, Gtk.get_current_event())

    def show_console_menu(self, button, menu, event):
        self.build_console_menu(menu)
        if hasattr(menu, "popup_at_widget"):
            # East, not west: the button sits at the right end of the tab strip, so a
            # menu whose left edge starts there runs off the screen -- measured 800px
            # off with a full-width window. Anchoring the menu's right edge to the
            # button's makes it open leftwards, which is correct by construction rather
            # than relying on GTK sliding it back, which does not always happen.
            menu.popup_at_widget(button, Gdk.Gravity.SOUTH_EAST, Gdk.Gravity.NORTH_EAST, event)
        else:
            menu.popup(None, None, None, None, 0, Gtk.get_current_event_time())

    def search_box(self):
        """The search box of the window in use: the main window's, in its toolbar, or a
        console window's own (#255)."""
        if self.window_in_use in self.console_windows:
            return self.window_in_use.search_entry
        return self.get_widget("txtSearch")

    def focus_search(self):
        if self.window_in_use in self.console_windows:
            self.window_in_use.search_bar.set_search_mode(True)
            # The bar gives its entry the keyboard at once, and maps it only on the next
            # frame. Realized now, it can take the keys let go of meanwhile: unrealized,
            # each one was a GTK critical, measured.
            self.search_box().realize()
        self.search_box().select_region(0, -1)
        self.search_box().grab_focus()

    def console_previous(self, notebook=None):
        notebook = notebook or self.current_notebook()
        if notebook is None:
            return
        if notebook.get_current_page() == 0 and conf.CYCLE_TABS:
            notebook.set_current_page(len(notebook) - 1)
        else:
            notebook.prev_page()

    def console_next(self, notebook=None):
        notebook = notebook or self.current_notebook()
        if notebook is None:
            return
        if notebook.get_current_page() == len(notebook) - 1 and conf.CYCLE_TABS:
            notebook.set_current_page(0)
        else:
            notebook.next_page()

    def on_window_set_focus(self, _window, widget):
        """Follow the keyboard into the panes, by a click or a key, whatever a tab holds.

        The window reports every move of the keyboard, so the pane this keeps is the one
        the keyboard is in, or was last in. Only the notebooks laid out in the panes
        count: a notebook inside a page is passed over.
        """
        notebooks = self.collect_notebooks(self.console_side())
        while widget is not None and widget not in notebooks:
            widget = widget.get_parent()
        if widget is not None:
            self.last_notebook = widget

    def on_window_key_press(self, window, event):
        """Give a remote desktop that has the keyboard every key, GCM's shortcuts too (#234).

        GCM's shortcuts are accelerators, which GTK runs before the focused widget sees
        the key, and they take keys a desktop's programs need. Measured with real input,
        Ctrl+W closed a VNC tab and Ctrl+F never reached the desktop. So the desktop gets
        a key first, and GCM only one gtk-vnc leaves. With the keyboard anywhere else,
        GCM's shortcuts apply.
        """
        if GtkVnc is not None and isinstance(window.get_focus(), GtkVnc.Display):
            return window.propagate_key_event(event)
        return False

    def current_notebook(self):
        """The pane in use: in the window that last had the keyboard, the notebook the
        keyboard is in, or was last in (#223, #255).

        A console window has one notebook, so it is that one. In the main window, measured,
        choosing a tab whose page cannot take the keyboard leaves it on the notebook
        itself. This looked for a focused terminal, then for the last terminal given the
        keyboard, which a click never set, so an action went to a tab nobody was looking
        at.
        """
        if self.window_in_use in self.console_windows:
            return self.window_in_use.notebook
        return self.main_notebook()

    def main_notebook(self):
        """The main window's pane in use, where a console moved back goes (#255).

        The notebook the keyboard is in or was last in there, and the main pane failing
        that.
        """
        if self.last_notebook in self.collect_notebooks(self.console_side()):
            return self.last_notebook
        return self.nbConsole

    def use_window(self, window):
        """Make `window` the one in use, bringing it to the front if it was not (#255).

        The main window or a console window. Activating one makes it the window in use
        too, through on_window_active_changed; this is for GCM moving the keyboard there
        itself, so that it acts on the right tab before the activation arrives.
        """
        if window is not (self.window_in_use or self.wMain):
            self.window_in_use = window
            window.present()

    def page_in_use(self):
        """The tab in use, whatever it holds: the page showing in the pane in use."""
        notebook = self.current_notebook()
        position = notebook.get_current_page()
        return notebook.get_nth_page(position) if position >= 0 else None

    def toggle_fullscreen(self):
        if self.window_in_use in self.console_windows:
            # The console window's own, which has no toolbar or menu to hide (#255).
            window = self.window_in_use
            state = window.get_window().get_state() if window.get_window() else 0
            if state & Gdk.WindowState.FULLSCREEN:
                window.unfullscreen()
            else:
                window.fullscreen()
            return
        if self._current_fullscreen_state:
            Gtk.Window.unfullscreen(self.wMainWindow)
            self.wMainWindow.set_decorated(True)
            self.wMainWindow.set_has_resize_grip(True)
            self.get_widget("toolbar1").show()
            if self.menubar is not None:
                self.menubar.show()
            self._current_fullscreen_state = False
        else:
            self.wMainWindow.set_decorated(False)
            self.wMainWindow.set_has_resize_grip(False)
            Gtk.Window.fullscreen(self.wMainWindow)
            self.get_widget("toolbar1").hide()
            if self.menubar is not None:
                self.menubar.hide()
            self._current_fullscreen_state = True

    def on_terminal_selection(self, widget, *args):
        if conf.AUTO_COPY_SELECTION and widget.get_has_selection():
            self.terminal_copy(widget)
        return True

    def find_word(self, backwards=False):
        if not self.search:
            return

        if self.search["pcre2"]:
            if backwards:
                self.search["terminal"].search_find_previous()
            else:
                self.search["terminal"].search_find_next()
            return

        pos = -1
        if backwards:
            lst = list(range(0, self.search["index"]))
            lst.reverse()
            lst.extend(reversed(range(self.search["index"], len(self.search["lines"]))))
        else:
            lst = list(range(self.search["index"], len(self.search["lines"])))
            lst.extend(range(0, self.search["index"]))
        for i in lst:
            pos = self.search["lines"][i].find(self.search["word"])
            if pos != -1:
                self.search["index"] = i if backwards else i + 1
                # print('found at line %d column %d, index=%d, line: %s' % (i, pos, self.search['index'], self.search['lines'][i]))
                GLib.timeout_add(
                    0, lambda line=i: self.search["terminal"].get_vadjustment().set_value(line)
                )
                # self.search['terminal'].get_vadjustment().set_value(i)
                self.search["terminal"].queue_draw()
                break
        if pos == -1:
            self.search["index"] = len(self.search["lines"]) if backwards else 0

    def init_search(self):
        terminal = self.get_target_terminal()
        if (
            hasattr(self, "search")
            and self.search
            and self.search_box().get_text() == self.search["word"]
            and terminal == self.search["terminal"]
        ):
            return True

        if terminal is None:
            return False

        self.search = {}
        text = self.search_box().get_text()
        if text == "" or text == _("buscar..."):
            terminal.search_set_regex(None, 0)
            terminal.match_remove_all()
            return True

        self.search["terminal"] = terminal
        self.search["word"] = text

        r = re.escape(text)
        try:
            new_reg = Vte.Regex.new_for_search(r, len(r), 0)
            new_reg_m = Vte.Regex.new_for_match(r, len(r), 0)
            terminal.search_set_regex(new_reg, 0)
            terminal.search_set_wrap_around(True)
            terminal.match_add_regex(new_reg_m, 0)
            self.search["pcre2"] = True
            return True
        except Exception:
            logger.exception("PCRE search failed; using manual fallback")
            self.search["pcre2"] = False
            # no hay soporte para pcre2, usar busqueda artesanal

        cols = terminal.get_column_count()
        lines, b = terminal.get_text_range(
            0, 0, terminal.get_property("scrollback-lines"), cols, None, None
        )
        wrapped = []
        for x in lines.splitlines():
            if len(x) == 0:
                wrapped.append(x)
            else:
                wrapped += self.chunkstring(x, cols)
        self.search["lines"] = wrapped
        self.search["index"] = len(self.search["lines"])
        return True

    def chunkstring(self, string, length):
        return (string[0 + i : length + i] for i in range(0, len(string), length))

    def on_popupmenu(self, widget, item, *args):
        if item == "V":  # PASTE
            self.terminal_paste(self.popupMenu.terminal)
            return True
        elif item == "C":  # COPY
            self.terminal_copy(self.popupMenu.terminal)
            return True
        elif item == "CV":  # COPY and PASTE
            self.terminal_copy_paste(self.popupMenu.terminal)
            return True
        elif item == "A":  # SELECT ALL
            self.terminal_select_all(self.popupMenu.terminal)
            return True
        elif item == "CA":  # COPY ALL
            self.terminal_copy_all(self.popupMenu.terminal)
            return True
        elif item == "X":  # CLOSE CONSOLE, whatever the tab holds (#223)
            page = self.get_context_tab_widget()
            notebook = page.get_parent() if page is not None else None
            if notebook is not None:
                notebook.remove_page(notebook.page_num(page))
            return True
        elif item == "W":  # TO A WINDOW OF ITS OWN, OR BACK, whatever the tab holds (#255)
            self.toggle_console_window(self.get_context_tab_widget())
            return True
        elif item == "CP":  # CUSTOM COMMANDS
            vte_feed(self.popupMenu.terminal, args[0])
        elif item == "S":  # SAVE BUFFER
            self.show_save_buffer(self.popupMenu.terminal)
            return True
        elif item == "H":  # COPY HOST ADDRESS TO CLIPBOARD
            if self.treeServers.get_selection().get_selected()[
                1
            ] is not None and not self.is_folder_row(
                self.treeServers.get_selection().get_selected()[1]
            ):
                host = self.treeModel.get_value(
                    self.treeServers.get_selection().get_selected()[1], 1
                )
                cb = Gtk.Clipboard.get_default(Gdk.Display.get_default())
                cb.set_text(host.host, len(host.host))
                cb.store()
            return True
        elif item == "D":  # DUPLICATE HOST
            if self.treeServers.get_selection().get_selected()[
                1
            ] is not None and not self.is_folder_row(
                self.treeServers.get_selection().get_selected()[1]
            ):
                selected = self.treeServers.get_selection().get_selected()[1]
                group = self.get_group(selected)
                host = self.treeModel.get_value(selected, 1)
                newname = f"{host.name} (copy)"
                newhost = host.clone()
                for h in groups[group]:
                    if h.name == newname:
                        newname = f"{newname} (copy)"
                newhost.name = newname
                groups[group].append(newhost)
                self.updateTree()
                self.writeConfig()
            return True
        elif item == "R":  # RENAME TAB
            tab = self.get_context_tab_label()
            text = inputbox(
                _("Renombrar consola"),
                _("Ingrese nuevo nombre"),
                tab.get_text().strip(),
                parent=self.window,
            )
            if text is not None and text != "":
                tab.rename(text)
                nb = tab.get_parent()
                nb.emit(
                    "switch-page", nb.get_nth_page(nb.get_current_page()), nb.get_current_page()
                )
            return True
        elif item == "RS" or item == "RS2":  # RESET CONSOLE
            if item == "RS":
                term = page_terminal(self.get_context_tab_widget())
            else:
                term = self.popupMenu.terminal
            # None for a tab that holds no terminal, here and below (#223).
            if term is not None:
                term.reset(True, False)
            return True
        elif item == "RC" or item == "RC2":  # RESET AND CLEAR CONSOLE
            if item == "RC":
                term = page_terminal(self.get_context_tab_widget())
            else:
                term = self.popupMenu.terminal
            if term is not None:
                term.reset(True, True)
            return True
        elif item == "RO":  # REOPEN SESION
            tab = self.get_context_tab_label()
            term = page_terminal(tab.widget_)
            if term is None:
                return True
            self.stop_reconnecting(term, final=False)
            self.reconnect(term, tab)
            return True
        elif item == "CC" or item == "CC2":  # CLONE CONSOLE
            if item == "CC":
                tab = self.get_context_tab_label()
                term = page_terminal(tab.widget_)
                ntbk = tab.get_parent()
            else:
                term = self.popupMenu.terminal
                ntbk = term.get_parent().get_parent()
                tab = ntbk.get_tab_label(term.get_parent())
            if term is None:
                # A tab of another kind has nothing to clone yet; each kind defines its own.
                return True
            if not hasattr(term, "host"):
                self.addTab(ntbk, tab.get_text())
            else:
                host = term.host.clone()
                # See the keyboard clone path: the label is not the host's identity.
                host.log = hasattr(term, "log_handler_id") and term.log_handler_id != 0
                host.id = term.host.id
                self.addTab(ntbk, host)
            return True
        elif item == "L" or item == "L2":  # ENABLE/DISABLE LOG
            if item == "L":
                term = page_terminal(self.get_context_tab_widget())
            else:
                term = self.popupMenu.terminal
            if term is not None and not self.set_terminal_logger(term, widget.get_active()):
                widget.set_active(False)
            return True
        elif item == "SPH":
            self.on_btnHSplit_clicked(widget, args)
        elif item == "SPV":
            self.on_btnVSplit_clicked(widget, args)

