    def createMenuItem(self, shortcut, label):
        menuItem = Gtk.MenuItem(label="")
        text = f"[{shortcut}] {label}"
        attrs = Pango.parse_markup(
            f"<span foreground='blue'  size='x-small'>[{GLib.markup_escape_text(shortcut, -1)}]</span> {GLib.markup_escape_text(label, -1)}",
            -1,
            "0",
        )
        menuItem.get_children()[0].set_attributes(attrs[1])
        menuItem.get_children()[0].set_label(text)
        menuItem.show()
        return menuItem

    def populateCommandsMenu(self):
        self.popupMenu.mnuCommands.foreach(lambda x: self.popupMenu.mnuCommands.remove(x))
        application = Gtk.Application.get_default()
        commands_menu = getattr(application, "commands_menu", None)
        if commands_menu is not None:
            commands_menu.remove_all()
        find = Gtk.MenuItem(label=_("Find Snippet…"))
        find.set_action_name("app.find-snippet")
        find.show()
        self.popupMenu.mnuCommands.append(find)
        separator = Gtk.SeparatorMenuItem()
        separator.show()
        self.popupMenu.mnuCommands.append(separator)
        # The menubar is built from its model, so it follows the edits.
        self.fill_snippet_menus(
            snippetlib.tree(snippets), self.popupMenu.mnuCommands, commands_menu
        )

    def fill_snippet_menus(self, folder, menu, model, send=None):
        """List a folder of snippets by name in the terminal menu's `menu` and in the
        menubar's `model`, which may be None: each subfolder a submenu, then each snippet,
        with its key when it has one (#240).

        An item sends its snippet to the tab the menu is for, or, given `send`, calls it
        with the snippet instead, as the cluster window's menu does.
        """
        for child in folder.folders:
            submenu = Gtk.Menu()
            item = Gtk.MenuItem(label=child.name)
            item.set_submenu(submenu)
            item.show()
            menu.append(item)
            submodel = Gio.Menu() if model is not None else None
            self.fill_snippet_menus(child, submenu, submodel, send)
            if model is not None:
                model.append_submenu(menu_label(child.name), submodel)
        for snippet in folder.snippets:
            if snippet.key:
                item = self.createMenuItem(snippet.key, snippet.name)
            else:
                item = Gtk.MenuItem(label=snippet.name)
                item.show()
            if send is None:
                item.set_action_name("app.send-snippet")
                item.set_action_target_value(GLib.Variant("s", snippet.id))
            else:
                item.connect("activate", lambda _item, chosen=snippet: send(chosen))
            menu.append(item)
            if model is not None:
                label = f"[{snippet.key}] {snippet.name}" if snippet.key else snippet.name
                entry = Gio.MenuItem.new(menu_label(label), None)
                entry.set_action_and_target_value("app.send-snippet", GLib.Variant("s", snippet.id))
                model.append_item(entry)

    def _copy_selection(self, terminal):
        # With an empty selection VTE still takes clipboard ownership and serves an
        # empty string, so an unguarded copy destroys whatever was on the clipboard.
        if not terminal.get_has_selection():
            return False
        terminal.copy_clipboard_format(Vte.Format.TEXT)
        return True

    def terminal_copy(self, terminal):
        if self._copy_selection(terminal):
            return
        if conf.COPY_SCREEN_IF_NO_SELECTION:
            self._copy_screen(terminal)

    def terminal_paste(self, terminal, single_line: bool = False):
        text = self._clipboard_text()
        if text is None:
            # Nothing text-shaped on the clipboard. Hand back to VTE rather than
            # swallowing the paste, so any format it understands still lands.
            terminal.paste_clipboard()
            return
        text = paste_transform(text, single_line=single_line)
        if not text:
            return
        if (
            paste_needs_confirmation(text)
            and msgconfirm(paste_preview(text)) != Gtk.ResponseType.OK
        ):
            return
        # paste_text() keeps VTE's bracketed-paste wrapping, so applications that opt in
        # still see the content framed as a paste rather than as typing.
        terminal.paste_text(text)

    def terminal_copy_paste(self, terminal):
        # Deliberately no copy-screen fallback: pasting a whole screen back into the
        # terminal is never what "Copy and Paste" is asking for.
        self._copy_selection(terminal)
        self.terminal_paste(terminal)

    def _clipboard_text(self):
        return Gtk.Clipboard.get_default(Gdk.Display.get_default()).wait_for_text()

    def terminal_zoom(self, terminal, factor):
        """Scale one terminal's font. Zoom is per-terminal: set_font_scale() is a widget
        property, and a wide log in one tab should not shrink the shell in the next."""
        scale = clamp_font_scale(terminal.get_font_scale() * factor)
        terminal.set_font_scale(scale)
        return scale

    def terminal_zoom_in(self, terminal):
        return self.terminal_zoom(terminal, FONT_SCALE_STEP)

    def terminal_zoom_out(self, terminal):
        return self.terminal_zoom(terminal, 1 / FONT_SCALE_STEP)

    def terminal_zoom_reset(self, terminal):
        terminal.set_font_scale(1.0)
        return 1.0

    def open_file_location(self, terminal, match):
        """Open a clicked path:line in an editor.

        Local sessions only: a path printed by a remote host does not exist here, so
        opening it locally would open the wrong file or nothing.
        """
        parsed = parse_file_location(match)
        if parsed is None:
            return False
        path, line, col = parsed
        if not terminal_is_local(terminal):
            logger.debug("Not opening %r: terminal is not a local session", path)
            return False
        target = Path(path).expanduser()
        if not target.is_absolute():
            cwd = terminal_working_directory(terminal)
            if cwd is None:
                logger.debug("Not opening %r: no working directory for the terminal", path)
                return False
            target = Path(cwd) / target
        if not target.is_file():
            logger.debug("Not opening %r: no such file", target)
            return False
        command = build_editor_command(str(target), line, col)
        try:
            subprocess.Popen(command)
        except OSError:
            logger.exception("Could not run the editor command %r", command)
            msgbox("{}\n{}".format(_("No se puede abrir el editor"), " ".join(command)))
            return False
        return True

    def on_terminal_drag_data_received(self, widget, context, x, y, data, info, drop_time):
        """Insert dropped paths at the prompt.

        No trailing newline: the text is left for the user to review and run, the same
        reasoning as the paste policy.
        """
        uris = data.get_uris() if hasattr(data, "get_uris") else None
        # A URI drop carries a usable path. A plain-text drop is text, not a path, so it
        # goes in exactly as it came -- quoting dragged prose would be wrong.
        text = uris_to_terminal_text(uris) if uris else (data.get_text() or "")
        if text:
            vte_feed(widget, text)
        Gtk.drag_finish(context, bool(text), False, drop_time)
        return True

    def on_terminal_child_exited(self, terminal, tab, status):
        """A session ending is the last chance to write the line it ended on.

        It is also worth telling a user who was not watching (#208). That comes after
        `mark_tab_as_closed`, which may close the tab: a closed tab's page has left its
        notebook, so `request_attention` finds no tab to mark. A tab the user closes is
        not marked either. VTE emits child-exited as `close_tab` destroys the terminal,
        and by then `close_tab` has taken the page out of its notebook.

        `status` is the wait status VTE reports with the signal, which Close console
        needs to tell a clean exit from a failed one (#210).
        """
        self.stop_commands(terminal)
        desktop = getattr(terminal, "desktop", None)
        if desktop is not None:
            desktop.ended()
        then = getattr(terminal, "before_then", None)
        if then is not None:
            # The host's command before connecting has ended (#238).
            terminal.before_then = None
            if status == 0 and tab.widget_.get_parent() is not None:
                # After this emission rather than inside it: `then` spawns in this terminal.
                GLib.idle_add(self.continue_after_before_command, terminal, tab, then)
                return
        self.session_ended(terminal)
        self.flush_terminal_log(terminal)
        if self.reconnect_if_dropped(terminal, tab, status):
            # Shown as ended while it counts down, but Close console and the marks wait.
            tab.is_active = False
            tab.render_label()
            return
        self.session_over(terminal, tab, status)

    def session_over(self, terminal, tab, status):
        """The end of a terminal's session, once it is final: Close console decides on
        the tab, and one that ended out of sight is marked."""
        tab.mark_tab_as_closed(status)
        # The end is its own trigger; the output just before it is not work finishing.
        watch = getattr(terminal, "quiet_watch", None)
        if watch is not None:
            watch.reset()
        if conf.ENDED_MARK_TAB:
            self.request_attention(terminal)

    def reconnect_if_dropped(self, terminal, tab, status):
        """Whether the session that just ended is to be reconnected, starting the countdown
        to it if so (#239).

        Only a connection that was up and was lost starts the attempts, which the type
        tells from its status and last lines. While they run, one that fails to connect
        uses one up, one refused for a login or a host key ends them, and one that stays
        up for RECONNECT_ESTABLISHED seconds before it drops starts the count over.
        """
        attempts = conf.RECONNECT_ATTEMPTS
        left = getattr(terminal, "reconnects_left", None)
        terminal.reconnects_left = None
        if attempts <= 0 or not hasattr(terminal, "host"):
            return False
        kind = connections.for_host(terminal.host)
        tail = session_tail(terminal)
        # VTE reports the wait status, measured: 65280 for a program that exits 255.
        code = os.waitstatus_to_exitcode(status)
        if kind.refused(code, tail):
            return False
        lasted = time.monotonic() - getattr(terminal, "session_started", 0)
        if left is None or lasted >= RECONNECT_ESTABLISHED:
            # It was up. Lost, it starts the attempts over; otherwise it ended.
            if not kind.dropped(code, tail):
                return False
            left = attempts
        elif code == 0:
            return False  # it ended, rather than failed to connect
        if left <= 0:
            return False
        terminal.reconnects_left = left - 1
        self.count_down_to_reconnect(terminal, tab, status, attempts - left + 1, attempts)
        return True

    def count_down_to_reconnect(self, terminal, tab, status, attempt, attempts):
        """Count down in the tab, then reconnect as Reconnect does. A key stops it."""
        remaining = [RECONNECT_DELAY]

        def show():
            text = _(
                "Reconnecting in {seconds} s, attempt {attempt} of {attempts}. Press a key to stop."
            ).format(seconds=remaining[0], attempt=attempt, attempts=attempts)
            terminal.feed(f"\r\x1b[K{text}".encode())

        def tick():
            if tab.widget_.get_parent() is None:
                # The tab closed: nothing is waited for any more (#175).
                terminal.reconnect_pending = None
                return False
            remaining[0] -= 1
            if remaining[0] > 0:
                show()
                return True
            terminal.reconnect_pending = None
            terminal.feed(b"\r\n")
            self.reconnect(terminal, tab)
            return False

        terminal.feed(b"\r\n")
        show()
        terminal.reconnect_pending = (GLib.timeout_add(1000, tick), tab, status)

    def stop_reconnecting(self, terminal, final=True):
        """Stop a countdown to reconnecting, if one is running, and say whether one was.

        `final` makes the session's end final, as when the attempts run out. Reconnect
        passes False: it reconnects itself.
        """
        terminal.reconnects_left = None
        pending = getattr(terminal, "reconnect_pending", None)
        if pending is None:
            return False
        terminal.reconnect_pending = None
        source, tab, status = pending
        GLib.source_remove(source)
        if final:
            terminal.feed(("\r\n" + _("Reconnecting stopped.") + "\r\n").encode())
            self.session_over(terminal, tab, status)
        return True

    def reconnect(self, terminal, tab):
        """What Reconnect does: the host's command before connecting again, then the same
        session, without the commands after login (#238)."""
        self.run_before_command(terminal, lambda: self.start_session(terminal, commands=False))
        tab.mark_tab_as_active()

    def on_terminal_title_changed(self, terminal, *args):
        """Show what the running program advertises, without letting it become identity."""
        label = self.get_tab_label_for_terminal(terminal)
        if label is not None and hasattr(label, "set_terminal_title"):
            label.set_terminal_title(terminal.get_window_title())

    def get_tab_label_for_terminal(self, terminal):
        pane = terminal.get_parent()
        notebook = pane.get_parent() if pane is not None else None
        if notebook is None or not hasattr(notebook, "get_tab_label"):
            return None
        return notebook.get_tab_label(pane)

    def on_terminal_scroll(self, widget, event, *args):
        """Ctrl+scroll zooms. VTE 0.76 does not do this itself -- measured: neither
        Ctrl+scroll nor Ctrl+plus emits increase-font-size -- so the wheel is ours to
        handle, and the event has to be swallowed or the buffer scrolls as well."""
        if not event.state & Gdk.ModifierType.CONTROL_MASK:
            return False
        direction = event.direction
        if direction == Gdk.ScrollDirection.UP:
            self.terminal_zoom_in(widget)
        elif direction == Gdk.ScrollDirection.DOWN:
            self.terminal_zoom_out(widget)
        elif direction == Gdk.ScrollDirection.SMOOTH:
            ok, _dx, dy = event.get_scroll_deltas()
            if not ok or not dy:
                return False
            # Smooth scroll reports upward movement as a negative delta.
            self.terminal_zoom_out(widget) if dy > 0 else self.terminal_zoom_in(widget)
        else:
            return False
        return True

    def terminal_select_all(self, terminal):
        terminal.select_all()

    def terminal_copy_all(self, terminal):
        terminal.select_all()
        self._copy_selection(terminal)
        terminal.unselect_all()

    def _copy_screen(self, terminal):
        # The visible screen is all that is reachable while an application holds the
        # alternate screen, which has no scrollback of its own. Copy All already covers
        # this case; this exists so the no-selection fallback does not have to run
        # select_all(), which would flash and discard any selection the user had.
        if Vte.get_minor_version() < 72:
            text, attrs = terminal.get_text(None, None)
        else:
            text = terminal.get_text_format(Vte.Format.TEXT)
        text = (text or "").rstrip()
        if not text:
            return
        Gtk.Clipboard.get_default(Gdk.Display.get_default()).set_text(text, -1)

    def on_contents_changed(self, terminal):
        col, row = terminal.get_cursor_position()
        if terminal.last_logged_row != row:
            if Vte.get_minor_version() < 72:
                text, b = terminal.get_text_range(
                    terminal.last_logged_row, terminal.last_logged_col, row, col, None, None
                )
            else:
                text, b = terminal.get_text_range_format(
                    Vte.Format.TEXT, terminal.last_logged_row, terminal.last_logged_col, row, col
                )
            terminal.last_logged_row = row
            terminal.last_logged_col = col
            # The whole range, not text[:-1]. VTE returns the grid text as it stands, so
            # dropping the last character removed the newline when the range ended at a
            # row boundary and a real character when it ended mid-line.
            terminal.log.write(text or "")

    def flush_terminal_log(self, terminal):
        """Write whatever is still pending on the line the cursor is on.

        on_contents_changed only writes once the cursor leaves a row, which is what stops
        a typed prompt logging once per keystroke. The cost is that a line the session
        ends on is never written at all; this closes that hole without touching the guard.
        """
        log = getattr(terminal, "log", None)
        if log is None or not hasattr(terminal, "last_logged_row"):
            return False
        col, row = terminal.get_cursor_position()
        if (row, col) == (terminal.last_logged_row, terminal.last_logged_col):
            return False
        if Vte.get_minor_version() < 72:
            text, _attrs = terminal.get_text_range(
                terminal.last_logged_row, terminal.last_logged_col, row, col, None, None
            )
        else:
            text, _attrs = terminal.get_text_range_format(
                Vte.Format.TEXT, terminal.last_logged_row, terminal.last_logged_col, row, col
            )
        terminal.last_logged_row = row
        terminal.last_logged_col = col
        if not text:
            return False
        log.write(text)
        log.flush()
        return True

    def set_terminal_logger(self, terminal, enable_logging=True):
        if enable_logging:
            terminal.last_logged_col, terminal.last_logged_row = terminal.get_cursor_position()
            if hasattr(terminal, "log_handler_id"):
                if terminal.log_handler_id == 0:
                    terminal.log_handler_id = terminal.connect(
                        "contents-changed", self.on_contents_changed
                    )
                return True
            terminal.log_handler_id = terminal.connect("contents-changed", self.on_contents_changed)
            # The host entry, not the tab label: a label is presentation, it can be
            # renamed, and once #18 makes it track window-title-changed it stops being
            # stable at all. terminal.host is set in addTab before any branching.
            host = getattr(terminal, "host", None)
            title = sanitize_log_name(getattr(host, "name", "") or "")
            log_dir = Path(conf.LOG_PATH).expanduser()
            # Through session_file_for, as the recording is, so the two share a number.
            filename = session_file_for(terminal, ".log")
            if filename is None:
                logger.error("Refusing to write a log outside %s for host %r", log_dir, title)
                msgbox("{}\n{}".format(_("Ruta de log invalida"), log_dir))
                terminal.disconnect(terminal.log_handler_id)
                del terminal.log_handler_id
                return False
            try:
                prepend = ""
                # Not whether it exists: when the log is what chose the number, choosing
                # created it, empty, to reserve it (#202). When the recording chose, there is
                # no log yet. Only a log with something in it is an earlier session's.
                if Path(filename).exists() and Path(filename).stat().st_size:
                    msgbox("{}\n{}".format(_("Anexar el archivo de log existente"), filename))
                    prepend = "\n\n===== {} =====\n\n".format(
                        _("Fin del registro de sesión anterior")
                    )
                # Deliberately not a context manager: the handle lives as long as the
                # terminal and is closed when the session ends.
                terminal.log = Path(filename).open("a", 1)  # noqa: SIM115
                terminal.log.write(
                    "{}Session '{}' opened at {}\n{}\n".format(
                        prepend,
                        describe_log_session(host),
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        "-" * 80,
                    )
                )
            except Exception:
                logger.exception("Unable to open log file")
                msgbox(
                    "{}\n{}".format(
                        _("No se puede abrir el archivo de log para escritura"), filename
                    )
                )
                terminal.disconnect(terminal.log_handler_id)
                del terminal.log_handler_id
                return False
        else:
            if hasattr(terminal, "log_handler_id") and terminal.log_handler_id != 0:
                # Before disconnecting, or the current line is lost.
                self.flush_terminal_log(terminal)
                terminal.disconnect(terminal.log_handler_id)
                terminal.log_handler_id = 0
        return True

    def registerUrlRegexes(self, terminal):
        terminal.tag_direct = self.registerUrlRegex(terminal, urlregex.DIRECT)
        terminal.tag_url = self.registerUrlRegex(terminal, urlregex.URL)
        terminal.tag_email = self.registerUrlRegex(terminal, urlregex.EMAIL)
        terminal.tag_file = self.registerUrlRegex(terminal, urlregex.FILE_LINE)

    def registerUrlRegex(self, terminal, regex):
        try:
            new_reg_m = Vte.Regex.new_for_match(regex, len(regex), urlregex.PCRE2_FLAGS)
            tag = terminal.match_add_regex(new_reg_m, 0)
            terminal.match_set_cursor_name(tag, "pointer")
            return tag
        except Exception:
            # Swallowing this is how a pattern that never compiled went unnoticed: the
            # links simply stopped existing, with nothing to say why (#55).
            logger.exception("Link pattern failed to compile, matches disabled: %.60s", regex)
            return None

    def add_page(self, notebook, page, title, host=None):
        """Open `page` as a tab of `notebook`, showing it, and return the tab's label.

        Whatever the page holds (#223): the tab gets the label with its close button and
        menu, and can be reordered and dragged into another pane. addTab opens a terminal
        through this, and a page of any other kind goes through it too, so that it is a
        tab like the rest. page_terminal is how the rest of GCM tells them apart. `host`
        is the host the tab is opened for, which name_tabs names it after (#346), whose
        whole path it shows where there is room (#347), and whose colour it is marked with
        (#350).
        """
        tab = NotebookTabLabel(f"  {title}  ", notebook, page, self.popupMenuTab)
        tab.host = host
        if host is not None:
            tab.set_name(title, host_path(host))
            tab.set_color(host_tab_color(host))
        page.show_all()
        notebook.append_page(page, tab_label=tab)
        notebook.set_current_page(notebook.page_num(page))
        notebook.set_tab_reorderable(page, True)
        notebook.set_tab_detachable(page, True)
        return tab

    def open_type_page(self, notebook, host, page_type):
        """Open `host` in a tab drawn by `page_type`, its type's page in TYPE_PAGES (#234).

        The tab ends as a terminal's does: it is shown as ended, Close console decides
        whether it closes, and one that ends out of sight is marked for attention. The
        mark comes after the close, as in on_terminal_child_exited.
        """

        def ended(status):
            self.session_ended(page)
            tab.mark_tab_as_closed(status)
            if conf.ENDED_MARK_TAB:
                self.request_attention(page.keyboard)

        page = page_type(host, ended)
        page.session_host = host
        # Closing the tab, or the window, ends the session with no signal from the page.
        page.connect("destroy", lambda _page: self.session_ended(page))
        tab = self.add_page(notebook, page, host_tab_name(host), host)
        self.wMain.set_focus(page.keyboard)
        GLib.timeout_add(200, self.focus_again, page, page.keyboard)
        page.open()

    def focus_again(self, page, widget):
        """Give a new tab's `widget` the keyboard again, 200 ms after the tab opened.

        Something can take the keyboard as a tab opens, such as the server tree on a double
        click, so a new tab takes it twice. The second time is only while the tab is still
        the one in use: one opened in the meantime, or a pane the keyboard was moved into,
        keeps it. Measured, a shell tab's timer moved the keyboard into the shell, hidden
        behind a desktop opened 1 ms after it, for 15 ms (#264).
        """
        if self.page_in_use() is page:
            self.wMain.set_focus(keyboard_of(widget))
        return False

    def addTab(self, notebook, host):
        try:
            if isinstance(host, str):
                host = Host("", host)
                # Note: log enablement defaults to host.log except for 'local'
                # sessions that do not have a saved session to seed the host
                # configuration, but rather use a global GCM config toggle
                if host.name == "local":
                    # print ("D: Local session logging set to: %s\n" % (conf.LOG_LOCAL))
                    host.log = conf.LOG_LOCAL

            kind = connections.for_host(host)
            page_type = TYPE_PAGES.get(kind.id)
            if page_type is not None:
                self.run_before_in_background(
                    host, lambda: self.open_type_page(notebook, host, page_type)
                )
                return

            problem = connections.named(host.type).missing(connection_programs())
            if problem:
                msgbox(_(problem))
                return

            if not kind.opens_tab:
                self.run_before_in_background(host, lambda: open_in_browser(kind.url(host)))
                return

            # Only once it is known to be needed: VTE 0.76 reports GLib criticals as a
            # terminal that never joined a window is dropped, as one made for a web host was.
            v = Vte.Terminal()
            if (Vte.MAJOR_VERSION, Vte.MINOR_VERSION) >= (0, 50):
                v.set_allow_hyperlink(True)
            self.registerUrlRegexes(v)

            # Before anything reads it. set_terminal_logger builds the log path from
            # terminal.host, so assigning this later -- as it used to be -- silently sent
            # every text log to <logs>/session/session-*.log instead of the host's own
            # directory. Keep this the first thing done with the new terminal.
            v.host = host

            self.apply_preferences_to_terminal(v)

            scrollPane = Gtk.Box(orientation=Gtk.Orientation.HORIZONTAL, spacing=0)
            scrollbar = Gtk.Scrollbar().new(Gtk.Orientation.VERTICAL, v.get_vadjustment())
            scrollPane.pack_start(v, True, True, 0)
            scrollPane.pack_start(scrollbar, False, False, 0)
            # An RDP desktop shown in its tab, in the terminal's place once it appears (#227).
            elsewhere = None
            if isinstance(kind, connections.Rdp):
                elsewhere = kind.window_instead(host, connection_programs(), can_show_desktops())
                if kind.in_tab(host, connection_programs()) and elsewhere is None:
                    v.desktop = RdpDesktop(v, scrollbar)
                    scrollPane.pack_start(v.desktop, True, True, 0)

            v.connect("bell", self.on_terminal_bell)
            v.connect("contents-changed", self.on_terminal_contents_changed)
            v.connect("focus", self.on_tab_focus)
            v.connect("button_press_event", self.on_terminal_click)
            v.connect("key_press_event", self.on_terminal_keypress)
            v.connect("selection-changed", self.on_terminal_selection)
            v.connect("scroll-event", self.on_terminal_scroll)
            v.connect("window-title-changed", self.on_terminal_title_changed)
            # VTE registers no drag targets of its own, so a drop does nothing until now.
            v.drag_dest_set(Gtk.DestDefaults.ALL, [], Gdk.DragAction.COPY)
            v.drag_dest_add_uri_targets()
            v.drag_dest_add_text_targets()
            v.connect("drag-data-received", self.on_terminal_drag_data_received)
            # VTE never raises these on its own in 0.76, but they are the documented
            # way to ask for a zoom, so honour them if anything ever does.
            v.connect("increase-font-size", self.terminal_zoom_in)
            v.connect("decrease-font-size", self.terminal_zoom_out)

            v.set_backspace_binding(host.backspace_key)
            v.set_delete_binding(host.delete_key)

            tab = self.add_page(notebook, scrollPane, host_tab_name(host), host)
            v.connect(
                "child-exited",
                lambda _terminal, status: self.on_terminal_child_exited(v, tab, status),
            )
            self.wMain.set_focus(v)
            self.on_tab_focus(v)
            self.set_terminal_logger(v, host.log)
            if elsewhere:
                v.feed((_(elsewhere) + "\r\n").encode())

            GLib.timeout_add(200, self.focus_again, scrollPane, v)

            # Dar tiempo a la interfaz para que muestre el terminal
            while Gtk.events_pending():
                Gtk.main_iteration()

            if kind.remote:
                # Before the command before connecting runs, so that Reconnect has it
                # even when that command failed and nothing was spawned.
                v.command = connection_command(host, getattr(v, "desktop", None))
            self.run_before_command(v, lambda: self.start_session(v))
        except Exception:
            logger.exception("Error connecting to host")
            msgbox("{}: {}".format(_("Error al conectar con servidor"), sys.exc_info()[1]))

    def start_session(self, terminal, commands=True):
        """Spawn the terminal's session: its command, or a local shell for a host without.

        addTab starts it, and Reconnect again, once the host's command before connecting
        has succeeded, when it has one (#238). Reconnect passes `commands` False: it has
        never sent the commands after login a second time.
        """
        host = terminal.host
        terminal.session_host = host
        terminal.session_started = time.monotonic()
        # Whatever waited for the last session's commands after login waits no longer.
        self.stop_commands(terminal)
        if not hasattr(terminal, "command"):
            vte_run(terminal, SHELL)
        else:
            spawn_command(terminal)

        if commands and host_sends_commands(host):
            groups = afterlogin.command_groups(host.commands)
            program = connections.for_host(host).session_program
            if program and groups:
                self.wait_for_session(terminal, program, groups)
            else:
                # A program GCM cannot follow, or a local shell: after a fixed wait.
                basetime = 700 if len(host.host) == 0 else 3000
                for delay, text in groups:
                    GLib.timeout_add(basetime + delay, self.send_data, terminal, text)
        terminal.queue_draw()

    def wait_for_session(self, terminal, program, groups):
        """Type `groups`, a host's commands after login, once the session `program` runs
        has started, and hold what is typed into the tab meanwhile for after them (#312)."""
        terminal.commands_gate = afterlogin.Gate(program, groups, time.monotonic())
        terminal.commands_timer = GLib.timeout_add(SESSION_POLL_MS, self.check_session, terminal)

    def check_session(self, terminal):
        """Type the commands after login once they are due, which ends the timer. A
        session that ends first stops it, as does closing its tab: VTE reports the end
        as the tab's terminal is destroyed."""
        gate = terminal.commands_gate
        if not gate.due(
            self.session_state(terminal, gate), login_asking(terminal), time.monotonic()
        ):
            return True
        terminal.commands_timer = None
        self.send_commands(terminal, gate)
        return False

    def session_state(self, terminal, gate):
        """The state of the terminal the session's program reads, or None while that
        program is not found among the tab's processes."""
        state = afterlogin.terminal_state(gate.pid) if gate.pid else None
        if state is None:
            # Not found yet, or gone: ssh is not there until the tab's process starts it.
            root = getattr(terminal, "child_pid", None)
            gate.pid = afterlogin.find_program(root, gate.program) if root else None
            state = afterlogin.terminal_state(gate.pid) if gate.pid else None
        return state

    def send_commands(self, terminal, gate):
        """Type the commands after login, each group after its wait, then the keys held
        while they waited."""
        gate.sending = True

        def send(index):
            if getattr(terminal, "commands_gate", None) is not gate:
                return False  # the session ended meanwhile
            self.send_data(terminal, gate.commands[index][1])
            if index + 1 < len(gate.commands):
                wait = gate.commands[index + 1][0] - gate.commands[index][0]
                GLib.timeout_add(wait, send, index + 1)
                return False
            terminal.commands_gate = None
            self.replay_keys(terminal, gate.held)
            return False

        GLib.timeout_add(gate.commands[0][0], send, 0)

    def hold_key(self, terminal, event):
        """Whether a key typed while the commands after login wait is held for after
        them, as it is unless it answers the login (#312)."""
        gate = getattr(terminal, "commands_gate", None)
        if gate is None or event.keyval in MODIFIER_KEYS or vte_keeps(event):
            return False
        control = bool(event.state & Gdk.ModifierType.CONTROL_MASK)
        state = self.session_state(terminal, gate)
        if gate.key(state, login_asking(terminal), control) == afterlogin.PASS:
            return False
        gate.held.append(event.copy())
        return True

    def replay_keys(self, terminal, held):
        """Type keys held as if pressed now: VTE sends for each what it would have then,
        measured byte for byte, and to a tab that is not the one in use too. Nothing waits
        for the session any more, so none is held again."""
        for event in held:
            terminal.event(event)

    def stop_commands(self, terminal):
        """Stop waiting to type the commands after login, if anything waits: the session
        they were for has ended, or another is starting. The keys held go with them."""
        terminal.commands_gate = None
        timer = getattr(terminal, "commands_timer", None)
        terminal.commands_timer = None
        if timer is not None:
            GLib.source_remove(timer)

    def run_before_command(self, terminal, then):
        """Run the host's command before connecting in `terminal`, then `then` (#238).

        In the tab's own terminal, so that its output shows there and Ctrl+C reaches it.
        on_terminal_child_exited calls `then` once it exits 0. Any other status ends the
        tab with that status, and nothing connects. A host without one goes straight on.
        """
        command = terminal.host.before_command
        if not command:
            then()
            return
        terminal.before_then = then
        vte_run(terminal, "sh", ["sh", "-c", local_command(terminal.host, command)])

    def continue_after_before_command(self, terminal, tab, then):
        # Unless the tab was closed in the meantime.
        if tab.widget_.get_parent() is not None:
            try:
                then()
            except Exception:
                logger.exception("Error connecting to host")
                msgbox("{}: {}".format(_("Error al conectar con servidor"), sys.exc_info()[1]))
        return False

    def run_before_in_background(self, host, then):
        """For a host whose tab is not a terminal, or which opens none: its command before
        connecting runs out of sight, and `then` opens it once that exits 0 (#238)."""
        if not host.before_command:
            then()
            return

        def exited(code):
            if code != 0:
                msgbox(
                    "{} {} {} {}".format(
                        _("The command before connecting to"),
                        host.name,
                        _("exited with status"),
                        code,
                    )
                )
                return
            try:
                then()
            except Exception:
                logger.exception("Error connecting to host")
                msgbox("{}: {}".format(_("Error al conectar con servidor"), sys.exc_info()[1]))

        run_in_background(local_command(host, host.before_command), exited)

    def session_ended(self, owner):
        """Run the host's command after disconnecting, once, for a session that started.

        `owner` is the terminal or the page that held it (#238). Not waited for.
        """
        host = getattr(owner, "session_host", None)
        if host is None:
            return
        owner.session_host = None
        if not host.after_command:
            return

        def exited(code):
            if code != 0:
                msgbox(
                    "{} {} {} {}".format(
                        _("The command after disconnecting from"),
                        host.name,
                        _("exited with status"),
                        code,
                    )
                )

        run_in_background(local_command(host, host.after_command), exited)

    def end_sessions(self):
        """Run the command after disconnecting for each session still open (#238).

        Measured, quitting by Ctrl+Q ends GCM with no session's end reported, while
        closing the window reports each, with status 9. session_ended runs a host's
        command once, whichever comes first. Every window's, console windows' too (#255).
        """
        for notebook in self.console_notebooks():
            for index in range(notebook.get_n_pages()):
                page = notebook.get_nth_page(index)
                self.session_ended(page_terminal(page) or page)

    def send_data(self, terminal, data):
        vte_feed(terminal, f"{data}\r")
        return False

    def initLeftPane(self):
        global groups

        # name, host (None on a folder row), stock icon, background, folder id ("" on a host),
        # where the host is mounted with sshfs ("" where it is not, and on a folder row) (#267)
        self.treeModel = Gtk.TreeStore(
            GObject.TYPE_STRING, GObject.TYPE_PYOBJECT, str, str, str, str
        )
        self.treeServers.set_model(self.treeModel)

        self.treeServers.set_level_indentation(5)
        # self.treeServers.set_grid_lines(Gtk.TreeViewGridLines.HORIZONTAL)

        column = Gtk.TreeViewColumn()
        column.set_title("Servers")
        self.treeServers.append_column(column)

        renderer = Gtk.CellRendererPixbuf()
        column.pack_start(renderer, expand=False)
        column.add_attribute(renderer, "stock_id", 2)
        column.add_attribute(renderer, "cell-background", 3)

        renderer = Gtk.CellRendererText()
        column.pack_start(renderer, expand=True)
        column.add_attribute(renderer, "text", 0)
        column.add_attribute(renderer, "cell-background", 3)
        column.set_cell_data_func(renderer, draw_name)

        self.treeServers.set_has_tooltip(True)
        self.treeServers.connect("query-tooltip", self.on_treeServers_tooltip)
        self.treeServers.connect("key-press-event", self.on_treeServers_key_press)

        # GtkTreeView's model drag, with a target of our own so it never moves a row
        # itself: the handlers refile the host or folder and redraw. Measured with real
        # pointer input under Xvfb -- a drop arrives with the row and position it landed
        # on, and a drag-motion that refuses a spot makes the drop fail outright.
        target = [Gtk.TargetEntry.new("GCM_TREE_ROW", Gtk.TargetFlags.SAME_WIDGET, 0)]
        self.treeServers.enable_model_drag_source(
            Gdk.ModifierType.BUTTON1_MASK, target, Gdk.DragAction.MOVE
        )
        self.treeServers.enable_model_drag_dest(target, Gdk.DragAction.MOVE)
        self.treeServers.connect("drag-data-get", self.on_treeServers_drag_data_get)
        self.treeServers.connect("drag-motion", self.on_treeServers_drag_motion)
        self.treeServers.connect("drag-data-received", self.on_treeServers_drag_data_received)
        self.wMain.connect("notify::is-active", self.on_window_active_changed)
        self.init_mounts_page()
        self.loadConfig()
        self.updateTree()
        self.watch_mounts()

    def init_mounts_page(self):
        """The server pane's Mounted tab (#269): a row for each mount, by the name
        list_mounts gives it, with its folder and what is mounted there as its tooltip,
        and a menu of what can be done with it."""
        # name, folder, tooltip (markup)
        self.treeMounts.set_model(Gtk.ListStore(str, str, str))
        column = Gtk.TreeViewColumn()
        renderer = Gtk.CellRendererText()
        column.pack_start(renderer, True)
        column.add_attribute(renderer, "text", 0)
        self.treeMounts.append_column(column)
        self.treeMounts.set_tooltip_column(2)
        # The folder whose menu is open.
        self.mount_menu_folder = None
        menu = self.popupMenuMounts = Gtk.Menu()
        for name, label, act in (
            ("mnuOpenFolder", _("Open Folder"), self.open_mounted_folder),
            ("mnuOpenSftp", _("Open over SFTP"), self.open_mounted_over_sftp),
            ("mnuUnmount", _("Unmount"), self.unmount_folder),
        ):
            item = Gtk.MenuItem(label=label)
            item.connect("activate", lambda _item, act=act: act(self.mount_menu_folder))
            setattr(menu, name, item)
            menu.append(item)
        menu.append(Gtk.SeparatorMenuItem())
        menu.mnuUnmountAll = item = Gtk.MenuItem(label=_("Unmount All"))
        item.connect("activate", lambda _item: self.unmount_all_files())
        menu.append(item)
        menu.show_all()

    def on_treeServers_key_press(self, widget, event, *args):
        if event.keyval == Gdk.KEY_Delete:
            self.on_btnDel_clicked(None)
            return True
        if event.keyval == Gdk.KEY_F2:
            self.rename_selected_folder()
            return True
        return False

    def on_treeServers_tooltip(self, widget, x, y, _keyboard, tooltip):
        x, y = widget.convert_widget_to_bin_window_coords(x, y)
        pos = widget.get_path_at_pos(x, y)
        if pos:
            row = list(widget.get_model()[pos[0]])
            host, folder = row[1], row[5]
            if host:
                mounted = (
                    GLib.markup_escape_text(_("Mounted at {}").format(folder), -1) + "\n"
                    if folder
                    else ""
                )
                text = f"<span><b>{host.name}</b>\n{host.type}:{host.user}@{host.host}\n{mounted}</span><span size='smaller'>{host.description}</span>"
                tooltip.set_markup(text)
                return True
        return False

    def add_shortcut(self, cp, scuts, command, name, default):
        try:
            scuts[cp.get("shortcuts", command)] = name
        except (configparser.NoSectionError, configparser.NoOptionError):
            scuts[default] = name

    def report_unread_options(self):
        """Say which [options] values in gcm.conf could not be read (#173).

        Each of those settings is at its default, and the log line that said so reached
        nobody who had not started GCM from a terminal. Run from an idle once the window is
        up, hence the False.
        """
        if not unread_options:
            return False
        kinds = {(section, option): kind for _attr, section, option, kind in CONFIG_OPTIONS}
        expects = {bool: _("expects true or false"), int: _("expects a whole number")}
        lines = [
            f"{unread.option} = {unread.text}  ({expects[kinds[unread.section, unread.option]]})"
            for unread in unread_options
        ]
        dialog = Gtk.MessageDialog(
            parent=self.wMain,
            modal=True,
            message_type=Gtk.MessageType.WARNING,
            buttons=Gtk.ButtonsType.OK,
            text=_("Some settings in gcm.conf could not be read, so each is at its default."),
        )
        dialog.format_secondary_text(
            "{}\n\n{}".format(
                "\n".join(lines),
                _(
                    "GCM leaves these lines as they are until you change the setting in Preferences. To correct one in the file instead, edit it with GCM closed."
                ),
            )
        )
        dialog.run()
        dialog.destroy()
        return False

    def report_renamed_hosts(self, renamed):
        """Say which hosts were renamed for repeating a name in their folder (#351).

        `renamed` is what HostUtils.ensure_unique_names returned, when it renamed any. The
        rename is there to show the repeat, where two rows and two tabs reading the same
        hid it, so it is not left to the tree to tell. Run from an idle once the window is
        up, hence the False.
        """
        lines = [
            "{}  →  {}".format("/".join(part for part in (host.group, old) if part), host.name)
            for host, old in renamed
        ]
        dialog = Gtk.MessageDialog(
            parent=self.wMain,
            modal=True,
            message_type=Gtk.MessageType.WARNING,
            buttons=Gtk.ButtonsType.OK,
            text=_("Some hosts had the name of another host in their folder, so GCM renamed them."),
        )
        dialog.format_secondary_text(
            "{}\n\n{}".format(
                "\n".join(lines),
                _(
                    "A renamed host's session logs go in a folder of its new name from now on. To give it another name, edit the host."
                ),
            )
        )
        dialog.run()
        dialog.destroy()
        return False

    def loadConfig(self):
        global groups, folders, unread_options, renamed_hosts

        # main() has already refused a file that cannot be read at all (#161). What is
        # left to handle is what a hand merge leaves behind, which reads without loss.
        reading = configfile.load(Path(CONFIG_FILE))
        cp = reading.config
        if reading.kept_apart or reading.dropped:
            logger.warning(
                "gcm.conf repeats %d section(s): %d kept as entries of their own, "
                "%d dropped as verbatim copies",
                reading.kept_apart + reading.dropped,
                reading.kept_apart,
                reading.dropped,
            )

        # Leer configuracion general
        unread_options = []
        for attr, section, option, kind in CONFIG_OPTIONS:
            value, unread = read_config_option(cp, section, option, kind, getattr(conf, attr))
            setattr(conf, attr, value)
            # Only [options] holds settings someone chose. [window] is GCM's own record of
            # the window, and a save writes what the window is now.
            if unread and section == "options":
                unread_options.append(unread)
        conf.APP_TITLE = conf.APP_TITLE or app_name

        # setup shortcuts
        scuts: dict = {}
        for command, name, default in SHORTCUT_DEFAULTS:
            self.add_shortcut(cp, scuts, command, name, default)

        # shortcuts para cambiar consola1-consola9
        for x in range(1, 10):
            try:
                scuts[cp.get("shortcuts", f"console_{x}")] = globals()[f"_CONSOLE_{x}"]
            except (configparser.NoSectionError, configparser.NoOptionError):
                scuts[f"ALT+{x}"] = globals()[f"_CONSOLE_{x}"]
        # Custom commands are snippets now, taken from [shortcuts] once (#240).
        global snippets
        snippets = snippetlib.load(cp)
        snippets += snippetlib.migrate(cp, snippets)
        snippetlib.drop_repeated_keys(snippets)
        bind_snippet_keys(scuts, snippets)
        global shortcuts
        shortcuts = scuts

        global custom_keys
        try:
            entries = dict(cp.items("keys"))
        except configparser.NoSectionError:
            entries = {}
        custom_keys = parse_custom_keys(entries, set(scuts) | set(RESERVED_ACCELERATORS))

        # Leer lista de hosts
        groups = {}
        read = []
        for section in cp.sections():
            if not section.startswith("host "):
                continue
            host = cp.options(section)
            try:
                host = HostUtils.load_host_from_ini(
                    cp, section, get_password(), legacy=conf.VERSION == 0
                )

                if host.group not in groups:
                    groups[host.group] = []

                groups[host.group].append(host)
                read.append(host)
            except (configparser.Error, ValueError, AttributeError) as e:
                logger.error("%s: %s", _("Entrada invalida en archivo de configuracion"), e)

        # Only now is the whole list known, so only now can a repeated id be seen. A
        # record with no id of its own already has one by this point -- Host mints it.
        reassigned = HostUtils.ensure_unique_ids(h for hs in groups.values() for h in hs)
        if reassigned:
            # A count rather than which entries: a Host carries the stored password, and
            # CodeQL taints every attribute read off one, naming included.
            logger.warning("Reassigned %d duplicate host id(s)", len(reassigned))

        refile_ambiguous_hosts(groups, reading.ambiguous_folders)
        # A config written before ADR-0002 has no folder sections: the tree starts empty
        # and sync_folders builds it from the hosts' group paths.
        folders, fixes = FolderTree.load(cp)
        if fixes:
            logger.warning("Repaired %d problem(s) in the folder tree", len(fixes))
        sync_folders()
        # Once every host is filed, so that the hosts of two folders repair merged are
        # compared together, and in the file's order, whose first keeps its name: `groups`
        # is keyed by the group read, which bind can overrule with the folder id (#351).
        renamed_hosts = HostUtils.ensure_unique_names(read)
        if renamed_hosts:
            logger.warning(
                "Renamed %d host(s) that repeated a name in their folder", len(renamed_hosts)
            )

    def is_node_collapsed(self, model, path, iter, nodes):
        if self.treeModel.get_value(iter, 1) is None and not self.treeServers.row_expanded(path):
            nodes.append(self.treeModel.get_string_from_iter(iter))

    def get_collapsed_nodes(self):
        nodes: list = []
        self.treeModel.foreach(self.is_node_collapsed, nodes)
        return nodes

    def get_collapsed_folder_ids(self):
        ids: list = []

        def visit(model, path, iter_):
            if self.is_folder_row(iter_) and not self.treeServers.row_expanded(path):
                ids.append(self.folder_id_at(iter_))

        self.treeModel.foreach(visit)
        return ids

    def set_collapsed_nodes(self):
        self.treeServers.expand_all()
        if not self.treeModel.get_iter_first():
            return
        if conf.COLLAPSED_FOLDER_IDS is None:
            # First start after upgrading: the only record is row positions.
            for node in (conf.COLLAPSED_FOLDERS or "").split(","):
                if node != "":
                    self.treeServers.collapse_row(Gtk.TreePath.new_from_string(node))
            return
        wanted = set(filter(None, conf.COLLAPSED_FOLDER_IDS.split(",")))
        paths: list = []

        def visit(model, path, iter_):
            if self.is_folder_row(iter_) and self.folder_id_at(iter_) in wanted:
                paths.append(path.copy())

        self.treeModel.foreach(visit)
        for path in paths:
            self.treeServers.collapse_row(path)

    def servers_background_color(self):
        self.color_index += 1
        unevenColor = self.color_back1 if conf.DISABLE_HOSTS_STRIPES else self.color_back2
        return self.color_back1 if self.color_index % 2 else unevenColor

    def updateTree(self):
        contents = sync_folders()

        if conf.COLLAPSED_FOLDERS is None:
            # Not the first render: keep whatever the user has collapsed since.
            conf.COLLAPSED_FOLDER_IDS = ",".join(self.get_collapsed_folder_ids())

        self.menuServers.foreach(self.menuServers.remove)
        self.treeModel.clear()

        # The servers menu is for connecting, so it leaves out folders with no host below.
        occupied = {
            folder_id
            for host_folder in {host.folder for hosts in groups.values() for host in hosts}
            for folder_id in folders.folders
            if folders.is_ancestor(folder_id, host_folder)
        }
        # Read again with the hosts, as a host renamed or deleted changes which mount is whose.
        mounts, found = self.find_mounts()
        # The Hosts menu's item for each host, which show_mounts marks as the tree's row.
        self.host_items = {}
        # Its items with a colour's mark, which a change of theme marks again (#358).
        self.colored_items = {}
        self.add_folder_rows(ROOT_FOLDER, None, self.menuServers, contents, occupied, found)
        self.list_mounts(mounts, found)

        self.set_collapsed_nodes()
        conf.COLLAPSED_FOLDERS = None
        self.update_row_color()
        self.name_tabs()

    def name_tabs(self):
        """Name each open tab again, as the hosts and Preferences' Tab name now are (#346,
        #348). Preferences' OK redraws the tree, which runs this.

        A second host of a tab's host's name puts the folder in front of the tab's name,
        and it goes again once that host is renamed, moved or deleted. A tab follows its
        own host too, through the host dialog, as tab_namer says. A tab renamed by hand
        keeps its name, and takes its host's path, as every tab does (#347). The titles of
        the windows that name a tab, and an open cluster window's list, follow it.

        Each tab takes its host's colour again too, so a colour given to a host or to a
        folder, and a host moved to another folder, reach the open tabs (#350).
        """
        if not self.count:
            return
        name = tab_namer()
        for notebook in self.console_notebooks():
            for position in range(notebook.get_n_pages()):
                tab = notebook.get_tab_label(notebook.get_nth_page(position))
                # A plain label has no host, as the glade's placeholder pages' do (#41).
                host = getattr(tab, "host", None)
                if host is not None:
                    tab.set_name(name(host), host_path(host))
                    tab.set_color(host_tab_color(host))
        self.title_windows()
        self.name_cluster_consoles()

    def add_folder_rows(self, parent_id, parent_row, parent_menu, contents, occupied, found):
        """A folder's children in their order, subfolders drawn with their own. Until
        someone arranges a folder that is subfolders, then hosts, each by name -- the
        order the tree kept when it was drawn from path strings. Each host mounted is
        marked, from `found`, {host: where}, in the tree and in the Hosts menu, and each
        host and folder with a colour, as its tabs take it and as a folder gives it (#358)."""
        for child in contents.get(parent_id, []):
            if isinstance(child, Host):
                folder = mounted_at(child, found)
                self.treeModel.append(
                    parent_row, [child.name, child, "gtk-network", "#fff", "", folder]
                )
                mnuItem = Gtk.MenuItem(label="")
                color = tabcolors.tab_color(child, folders)
                self.label_menu_item(mnuItem, marked_name(child.name, folder), color)
                self.host_items[child] = mnuItem
                mnuItem.show()
                mnuItem.connect(
                    "activate", lambda arg, nb, h: self.addTab(nb, h), self.nbConsole, child
                )
                parent_menu.append(mnuItem)
                continue
            row = self.treeModel.append(
                parent_row, [child.name, None, "gtk-directory", "#fff", child.id, ""]
            )
            submenu = parent_menu
            if child.id in occupied:
                item = Gtk.MenuItem(label="")
                self.label_menu_item(item, child.name, tabcolors.folder_color(folders, child.id))
                submenu = Gtk.Menu()
                item.set_submenu(submenu)
                item.show()
                parent_menu.append(item)
            self.add_folder_rows(child.id, row, submenu, contents, occupied, found)

    def label_menu_item(self, item, text, color):
        """Label a Hosts menu item `text`, after the square of `color`, as the tree draws
        it, on a patch of the menu's own background, which shows on a hovered item alone
        (#358). Measured in Adwaita, an item hovered is #3584e4, the colour the host dialog
        starts with. An item without a colour is labelled as before.

        An item's colour lasts as long as the item: every change to a colour rebuilds the
        menu, through updateTree. `color` is one tabcolors read, or ""."""
        if not color:
            item.set_label(text)
            return
        background = self.menuServers.get_style_context().get_property(
            "background-color", Gtk.StateFlags.NORMAL
        )
        self.colored_items[item] = (text, color)
        item.get_child().set_markup(marked_markup(text, color, color_to_hex(background)))

    def is_folder_row(self, iter_):
        """Folder rows carry no host. This used to be asked as iter_has_child, which
        mistakes an empty folder -- possible now -- for a host."""
        return self.treeModel.get_value(iter_, 1) is None

    def folder_id_at(self, iter_):
        return self.treeModel.get_value(iter_, 4)

    def update_row_color(self, node=None):
        # custom method to get alternating row colors in treeview, as that is not possible with gtk3
        if not node:
            self.color_index = 0
            rgba = self.treeServers.get_style_context().get_property(
                "background-color", Gtk.StateFlags.NORMAL
            )
            self.color_back1 = color_to_hex(rgba)
            self.color_back2 = stripe_color(rgba)
            i = self.treeModel.get_iter_first()
        else:
            i = self.treeModel.iter_children(node)

        if i:
            self.treeModel[i][3] = self.servers_background_color()
            if (
                self.treeModel[i][1] is None
                and self.treeServers.row_expanded(self.treeModel.get_path(i))
                and self.treeModel.iter_has_child(i)
            ):
                self.update_row_color(i)

        i = self.treeModel.iter_next(i) if i else None
        while i:
            self.treeModel[i][3] = self.servers_background_color()
            self.update_row_color(i)
            i = self.treeModel.iter_next(i)

    def writeConfig(self):
        global groups, unread_options

        # Start from the file being replaced, less what this save writes, so a section GCM
        # never writes survives -- [keys] (#163). Never from gcm.conf.tmp: that is this
        # save's own output, and one left by an interrupted save made every later save fail.
        cp = carried_config()

        cp.add_section("options")
        cp.set("options", "word-separators", conf.WORD_SEPARATORS)
        cp.set("options", "buffer-lines", conf.BUFFER_LINES)
        cp.set("options", "startup-local", conf.STARTUP_LOCAL)
        cp.set("options", "log-local", conf.LOG_LOCAL)
        cp.set("options", "confirm-exit", conf.CONFIRM_ON_EXIT)
        cp.set("options", "font-color", conf.FONT_COLOR)
        cp.set("options", "back-color", conf.BACK_COLOR)
        cp.set("options", "term", conf.TERM)
        cp.set("options", "transparency", conf.TRANSPARENCY)
        cp.set("options", "paste-right-click", conf.PASTE_ON_RIGHT_CLICK)
        cp.set("options", "confirm-close-tab", conf.CONFIRM_ON_CLOSE_TAB)
        cp.set("options", "confirm-close-tab-middle", conf.CONFIRM_ON_CLOSE_TAB_MIDDLE)
        cp.set("options", "check-updates", conf.CHECK_UPDATES)
        cp.set("options", "font", conf.FONT)
        cp.set("options", "donate", conf.HIDE_DONATE)
        cp.set("options", "disable-hosts-stripes", conf.DISABLE_HOSTS_STRIPES)
        cp.set("options", "auto-copy-selection", conf.AUTO_COPY_SELECTION)
        cp.set("options", "bell-mark-tab", conf.BELL_MARK_TAB)
        cp.set("options", "bell-notify", conf.BELL_NOTIFY)
        cp.set("options", "bell-audible", conf.BELL_AUDIBLE)
        cp.set("options", "quiet-mark-seconds", conf.QUIET_MARK_SECONDS)
        cp.set("options", "ended-mark-tab", conf.ENDED_MARK_TAB)
        cp.set("options", "reconnect-attempts", conf.RECONNECT_ATTEMPTS)
        cp.set("options", "copy-screen-if-no-selection", conf.COPY_SCREEN_IF_NO_SELECTION)
        cp.set("options", "paste-strip-trailing-newline", conf.PASTE_STRIP_TRAILING_NEWLINE)
        cp.set("options", "paste-confirm-lines", conf.PASTE_CONFIRM_LINES)
        cp.set("options", "paste-confirm-bytes", conf.PASTE_CONFIRM_BYTES)
        cp.set("options", "log-path", conf.LOG_PATH)
        cp.set("options", "version", app_fileversion)
        cp.set("options", "auto-close-tab", conf.AUTO_CLOSE_TAB)
        cp.set("options", "cycle-tabs", conf.CYCLE_TABS)
        cp.set("options", "update-title", conf.UPDATE_TITLE)
        cp.set("options", "tab-title-from-terminal", conf.TAB_TITLE_FROM_TERMINAL)
        cp.set("options", "tab-name", conf.TAB_NAME)
        cp.set("options", "editor-command", conf.EDITOR_COMMAND)
        cp.set("options", "osc52-clipboard", conf.OSC52_ENABLED)
        cp.set("options", "raw-session-log", conf.RAW_SESSION_LOG)
        cp.set("options", "app-title", conf.APP_TITLE or app_name)
        cp.set("options", "rdp-client", conf.RDP_CLIENT)
        # A value that could not be read stays as written while its setting still holds
        # the default used in its place, rather than the default replacing it (#173).
        current = {
            (section, option): getattr(conf, attr)
            for attr, section, option, _kind in CONFIG_OPTIONS
        }
        unread_options = configfile.put_back_unread(cp, unread_options, current)

        collapsed_folders = ",".join(self.get_collapsed_nodes())
        cp.add_section("window")
        cp.set("window", "collapsed-folders", collapsed_folders)
        cp.set("window", "collapsed-folder-ids", ",".join(self.get_collapsed_folder_ids()))
        cp.set("window", "left-panel-width", self.hpMain.get_position())
        cp.set("window", "window-width", -1 if self.wMain.is_maximized() else conf.WINDOW_WIDTH)
        cp.set("window", "window-height", -1 if self.wMain.is_maximized() else conf.WINDOW_HEIGHT)
        cp.set("window", "show-panel", conf.SHOW_PANEL)
        cp.set("window", "show-toolbar", conf.SHOW_TOOLBAR)

        # So no host is written with a group that disagrees with its folder.
        sync_folders()
        folders.save(cp)
        i = 1
        for grupo in groups:
            for host in groups[grupo]:
                section = "host " + str(i)
                cp.add_section(section)
                HostUtils.save_host_to_ini(cp, section, host, get_password())
                i += 1

        cp.add_section("shortcuts")
        i = 1
        for s in shortcuts:
            if isinstance(shortcuts[s], list):
                cp.set("shortcuts", shortcuts[s][0], s)
            else:
                # A snippet with a key, written as the custom command it was as well, for
                # an older GCM to read. migrate() knows the copy by its key (#240).
                cp.set("shortcuts", f"shortcut{i}", s)
                cp.set("shortcuts", f"command{i}", snippetlib.legacy_encode(shortcuts[s].text))
                i = i + 1
        snippetlib.save(cp, snippets)

        # main() has made it already; this is for every other way in. A write into a
        # directory that is not there fails, and each of these failures ends at a modal
        # dialog nobody may be there to click (#118).
        configpaths.ensure(CONFIG_DIRECTORY.path)
        with Path(CONFIG_FILE + ".tmp").open("w") as f:
            cp.write(f)
        Path(CONFIG_FILE + ".tmp").rename(CONFIG_FILE)

    def on_tab_scroll(self, notebook, event):
        # According to https://sourcecodequery.com/example-method/Gdk.Event.get_scroll_deltas
        # the deltas below should only be usable for direction == Gdk.ScrollDirection.SMOOTH
        # Note: https://api.gtkd.org/gdk.Event.Event.getScrollDirection.html
        # documents his as a function returning a bool (whether the event
        # delivered a scroll direction) and an argument where to store that
        # data as an value from enum GdkScrollDirection. Code in the example
        # above uses a different syntax, and code below yet another with tuple.
        gsdir = event.get_scroll_direction()

        # Note: https://api.gtkd.org/gdk.Event.Event.getScrollDeltas.html
        # documents this as a function returning a bool (whether the event
        # contains smooth-scroll info) and having two args where to store
        # the X/Y deltas of that scroll; the code below uses another syntax
        # that returns a tuple of that bool and X/Y deltas:
        gsdelta = event.get_scroll_deltas()
        # sys.stderr.write("[D] on_tab_scroll: event.get_scroll_direction(): [%s] [%s]\n" % (gsdir[0], gsdir[1]) )
        # sys.stderr.write("[D] on_tab_scroll: event.get_scroll_deltas(): [%s] [%s] [%s]\n" % (gsdelta[0], gsdelta[1], gsdelta[2]) )

        scrollPrev = False
        if gsdelta[0]:
            if gsdelta[2] < 0:
                scrollPrev = True
        else:
            if gsdir[1] == Gdk.ScrollDirection.UP:
                scrollPrev = True
            elif gsdir[1] == Gdk.ScrollDirection.DOWN:
                scrollPrev = False
            else:
                # raise ValueError("Unrecognized scroll direction")
                sys.stderr.write(
                    "[D] on_tab_scroll: event.get_scroll_direction(): Unrecognized scroll direction\n"
                )

        if scrollPrev:
            if notebook.get_current_page() == 0 and conf.CYCLE_TABS:
                notebook.set_current_page(notebook.get_n_pages() - 1)
            else:
                notebook.prev_page()
        else:
            if notebook.get_current_page() == notebook.get_n_pages() - 1 and conf.CYCLE_TABS:
                notebook.set_current_page(0)
            else:
                notebook.next_page()

    def tab_label_for(self, page):
        """The NotebookTabLabel owning `page`, or None if it has no notebook yet."""
        notebook = page.get_parent() if page is not None else None
        if notebook is None or not hasattr(notebook, "get_tab_label"):
            return notebook, None
        return notebook, notebook.get_tab_label(page)

    def on_terminal_bell(self, terminal):
        """A terminal rang the bell: get the user's attention without stealing focus."""
        self.request_attention(terminal, mark=conf.BELL_MARK_TAB)

    def request_attention(self, terminal, mark=True):
        """Draw the user's eye to a console they are not watching, without stealing focus.

        The bell, output stopping out of sight and a session ending all come here (#208),
        so each is shown the same way: an orange tab until it is looked at, the taskbar
        flag while the window holding the tab is not the active one, and a desktop
        notification if one is wanted. Only the bell can ask for the notification without
        the mark: its two preferences predate the other triggers, which have one each.
        The window is the main window or the console window the tab is in (#255).
        """
        notebook, label = self.tab_label_for(terminal.get_parent())
        # nbConsole carries placeholder pages from the glade whose tab labels are plain
        # Gtk.Labels, so a tab label is not necessarily a NotebookTabLabel.
        if not hasattr(label, "set_attention"):
            return
        window = self.window_of(notebook)
        window_active = window.is_active()
        showing = notebook.get_current_page() == notebook.page_num(terminal.get_parent())
        if window_active and showing:
            # Already being watched; marking it would only need clearing again.
            return
        if mark:
            label.set_attention(True)
            if not window_active:
                window.set_urgency_hint(True)
        if conf.BELL_NOTIFY and not window_active:
            self.notify_attention(label)

    def notify_attention(self, label):
        """Raise a desktop notification. Silently does nothing without a notification service."""
        application = self.wMain.get_application()
        if application is None:
            return
        notification = Gio.Notification.new(_("La sesion requiere atencion"))
        notification.set_body(label.get_text().strip())
        # One id for every trigger, so a newer notification replaces an older one.
        application.send_notification("gcm-bell", notification)

    def is_watched(self, terminal):
        """True while the user can see this console: its window active, its tab current in
        its pane."""
        notebook, _ = self.tab_label_for(terminal.get_parent())
        if notebook is None or not hasattr(notebook, "get_current_page"):
            return False
        if not self.window_of(notebook).is_active():
            return False
        return notebook.get_current_page() == notebook.page_num(terminal.get_parent())

    def on_terminal_contents_changed(self, terminal):
        """Follow a console's output while it is out of sight, to mark it once it stops (#208).

        This runs on every screen update, so it only notes the time. The decision is made
        by `check_quiet`, on a timer that exists only while a console is waiting to be
        declared quiet.

        The commands after login wait for the session's output to pause too (#312).
        """
        gate = getattr(terminal, "commands_gate", None)
        if gate is not None:
            gate.output(time.monotonic())
        if conf.QUIET_MARK_SECONDS <= 0:
            return
        watch = getattr(terminal, "quiet_watch", None)
        if watch is None:
            watch = terminal.quiet_watch = activity.QuietWatch()
        watch.output(time.monotonic(), self.is_watched(terminal))
        if watch.waiting and getattr(terminal, "quiet_timer", None) is None:
            terminal.quiet_timer = GLib.timeout_add(QUIET_POLL_MS, self.check_quiet, terminal)

    def check_quiet(self, terminal):
        """Mark the tab once its output has stopped for long enough.

        The timer ends as soon as there is nothing left to wait for: the run is settled,
        the user has looked, or the tab is gone. An idle console costs nothing.
        """
        watch = terminal.quiet_watch
        if terminal.get_parent() is None:
            # Closing a tab emits child-exited, which settles the watch. This catches a
            # close where that handler stopped short of it.
            watch.reset()
        elif watch.settled(time.monotonic(), conf.QUIET_MARK_SECONDS):
            self.request_attention(terminal)
        if watch.waiting:
            return True
        terminal.quiet_timer = None
        return False

    def clear_tab_attention(self, page):
        _notebook, label = self.tab_label_for(page)
        if hasattr(label, "set_attention"):
            label.set_attention(False)
        # Looking at the tab settles whatever it was doing out of sight (#208).
        for child in page.get_children() if hasattr(page, "get_children") else ():
            watch = getattr(child, "quiet_watch", None)
            if watch is not None:
                watch.reset()

    def on_window_active_changed(self, window, _param):
        """The main window or a console window took the keyboard, or lost it.

        The last of them to take it is the window in use, whose tab an action goes to
        (#255). Measured under X11 with no window manager, presenting a window sets this
        as the keyboard arrives, and a shortcut there runs with it already set.
        """
        if window.is_active():
            window.set_urgency_hint(False)
            self.window_in_use = window

    def on_tab_focus(self, widget, tab=None, *args):
        notebook = widget
        if isinstance(widget, Vte.Terminal):
            self.clear_tab_attention(widget.get_parent())
            page = widget.get_parent()
            notebook = page.get_parent() if page is not None else None
        elif tab is not None:
            self.clear_tab_attention(tab)
        # The main window's title follows its tab only with Dynamic title on. A console
        # window's always does: it has nothing else to say (#255).
        window = self.console_window_of(notebook)
        if window is None and conf.UPDATE_TITLE:
            window = self.wMain
        if window is not None and widget is not None:
            if isinstance(widget, Vte.Terminal):
                tab_text = (
                    widget.get_parent().get_parent().get_tab_label(widget.get_parent()).get_text()
                )
            elif tab is not None:  # notebook page switched
                tab_text = widget.get_tab_label(tab).get_text() if widget.get_tab_label(tab) else ""
            else:
                tab_text = ""
            window.set_title(window_title(tab_text))

    def title_windows(self):
        """Title each window that names its tab after the tab it shows, once more (#346).

        As on_tab_focus titles them: a console window always, and the main window with
        Dynamic title on, after its pane in use. Not through on_tab_focus, which clears the
        tab's mark too, and the tab's name changing is no sign anyone has looked at it.
        """
        windows = [(window, window.notebook) for window in self.console_windows]
        if conf.UPDATE_TITLE:
            windows.append((self.wMain, self.main_notebook()))
        for window, notebook in windows:
            position = notebook.get_current_page()
            tab = notebook.get_tab_label(notebook.get_nth_page(position)) if position >= 0 else None
            window.set_title(window_title(tab.get_text() if tab is not None else ""))

    def move_page(self, page, notebook):
        """Move a console to the end of another notebook, taking its tab label along.

        The label holds more than its text: the title the program set, a rename, whether
        the session has ended, and the marks the bell and the cluster window leave on it.
        Split and Unsplit used to build a fresh label from get_text(), and a tab lost all
        of that on the way to its new pane (#180).
        """
        label = page.get_parent().get_tab_label(page)
        page.get_parent().remove(page)
        notebook.append_page(page, label)
        notebook.set_tab_reorderable(page, True)
        notebook.set_tab_detachable(page, True)

    def open_console_window(self, width, height):
        """A new console window, `width` by `height`, empty until a tab moves in (#255)."""
        window = ConsoleWindow(self, width, height)
        self.console_windows = (*self.console_windows, window)
        return window

    def toggle_console_window(self, page):
        """Move the console on `page` to a window of its own, or back from one (#255).

        One command does both, so one shortcut moves a console out and back, as RustConn's
        does.
        """
        notebook = page.get_parent() if page is not None else None
        if notebook is None:
            return
        if self.console_window_of(notebook) is None:
            self.move_to_new_window(page)
        else:
            self.move_to_main_window(page)

    def move_to_new_window(self, page):
        """Move the console on `page` to a new console window, the size of its pane."""
        allocation = page.get_parent().get_allocation()
        window = self.open_console_window(allocation.width, allocation.height)
        self.move_page(page, window.notebook)
        window.show()
        self.focus_console(window.notebook, page)
        return window

    def move_to_main_window(self, page):
        """Move the console on `page` back into the main window's pane in use (#255)."""
        notebook = self.main_notebook()
        self.move_page(page, notebook)
        self.focus_console(notebook, page)

    def on_notebook_create_window(self, notebook, page, x, y):
        """A tab dropped outside every notebook opens in a console window there (#255).

        GTK asks for the notebook to put it in, and moves it there itself. Measured with a
        real pointer drag under X11, dropped on the bare root window: it asks with the
        pointer's position, and the tab takes its label along, as between panes.
        """
        allocation = notebook.get_allocation()
        window = self.open_console_window(allocation.width, allocation.height)
        window.move(x, y)
        window.show()

        def focus():
            # Once GTK has moved the tab in, which it does after this returns.
            self.focus_console(window.notebook, page)
            return False

        GLib.idle_add(focus)
        return window.notebook

    def watch_tab_drags(self, notebook):
        """Move a tab dropped outside every notebook to a window of its own (#255)."""
        notebook.connect("create-window", self.on_notebook_create_window)
        notebook.connect("drag-begin", self.on_notebook_drag_begin)
        notebook.connect("drag-failed", self.on_notebook_drag_failed)
        notebook.connect("drag-end", self.on_notebook_drag_end)

    def on_notebook_drag_begin(self, notebook, _context):
        # GTK shows a tab as it is pressed, so the one showing as a drag begins is the
        # one dragged: measured on sway, dragging a tab that was not showing.
        self.dragged_tab = notebook.get_nth_page(notebook.get_current_page())

    def on_notebook_drag_end(self, _notebook, _context):
        self.dragged_tab = None

    def on_notebook_drag_failed(self, notebook, _context, result):
        """A tab dropped outside every notebook under Wayland, which GTK puts back (#255).

        GTK asks for a window for a tab dropped on the bare root window, or one whose drag
        failed for want of a target. Measured with real pointer input under X11, that is
        a drop anywhere else but a tab strip, a terminal or the server tree, while Escape
        cancels the drag. Measured on sway with a virtual pointer, Wayland reports a drop
        on the bare desktop or on a terminal as an error instead, and GTK put the tab
        back. So there GCM moves it out itself, as Move to New Window does, once GTK has.
        """
        page = self.dragged_tab
        wayland = notebook.get_display().__gtype__.name == "GdkWaylandDisplay"
        if result == Gtk.DragResult.ERROR and wayland and page is not None:
            GLib.idle_add(self.move_out_after_drag, page)
        return False

    def move_out_after_drag(self, page):
        if page.get_parent() is not None:
            self.move_to_new_window(page)
        return False

    def on_console_window_delete(self, window, _event):
        """Closing a console window moves its consoles back into the main window (#255).

        It ends none of them. Ending each, as closing its tab does, would have asked
        nothing with Confirm on close console off, which asks once a tab. They go into the
        main window's pane in use, in their order, and the one showing here shows there.
        """
        notebook = self.main_notebook()
        showing = window.notebook.get_nth_page(window.notebook.get_current_page())
        while window.notebook.get_n_pages():
            self.move_page(window.notebook.get_nth_page(0), notebook)
        if showing is not None:
            self.focus_console(notebook, showing)
        return False

    def on_console_window_destroy(self, window):
        self.console_windows = tuple(other for other in self.console_windows if other is not window)
        if self.window_in_use is window:
            self.window_in_use = None

    def on_console_window_page_removed(self, notebook, _page, _number):
        """Close a console window once its last tab has left it, however it left (#255).

        From an idle, after GTK has finished moving the tab: a drag still ends in the
        notebook the tab left. One dropped back in meanwhile keeps the window open.
        """
        if notebook.get_n_pages() == 0:
            GLib.idle_add(self.close_empty_console_window, self.console_window_of(notebook))

    def close_empty_console_window(self, window):
        if window in self.console_windows and window.notebook.get_n_pages() == 0:
            window.destroy()
        return False

    def new_console_notebook(self):
        """A notebook for consoles, for a split or a console window (#255).

        Wired as the main pane is, in the panes' group, so tabs drag between them all.
        """
        nb = Gtk.Notebook()
        nb.set_group_name("11")
        nb.add_events(Gdk.EventMask.SCROLL_MASK | Gdk.EventMask.SMOOTH_SCROLL_MASK)
        nb.connect("button_press_event", self.on_double_click, None)
        nb.connect("page_removed", self.on_page_removed)
        nb.connect("page-added", self.on_page_added)
        nb.connect("switch-page", self.on_tab_focus)
        nb.connect("scroll-event", self.on_tab_scroll)
        self.watch_tab_drags(nb)

        nb.set_property("scrollable", True)
        self.install_console_button(nb)
        return nb

    def split_notebook(self, direction):
        # The tab whose menu is open, else the tab in use: whatever it holds (#223).
        csp = self.get_context_tab_widget()
        cnb = csp.get_parent() if csp is not None else None

        # Separar solo si hay mas de 2 tabs en el notebook actual. A console window has
        # no splits (#255).
        if cnb is not None and cnb.get_n_pages() > 1 and self.console_window_of(cnb) is None:
            # Crear un hpaned, en el hijo 0 dejar el notebook y en el hijo 1 el nuevo notebook
            # El nuevo hpaned dejarlo como hijo del actual parent
            hp = Gtk.HPaned() if direction == HSPLIT else Gtk.VPaned()
            nb = self.new_console_notebook()
            cp = cnb.get_parent()

            if direction == HSPLIT:
                p = cnb.get_allocated_width() / 2
            else:
                p = cnb.get_allocated_height() / 2
            hp.set_position(p)
            hp.set_wide_handle(True)

            cp.remove(cnb)
            cp.add(hp)
            hp.add1(cnb)

            self.move_page(csp, nb)

            hp.add2(nb)
            nb.show()
            hp.show()
            hp.queue_draw()
            self.on_tab_focus(cnb, cnb.get_nth_page(cnb.get_current_page()))

    def find_notebook(self, widget, exclude=None):
        if widget != exclude and isinstance(widget, Gtk.Notebook):
            return widget
        else:
            if not hasattr(widget, "get_children"):
                return None
            for w in widget.get_children():
                wid = self.find_notebook(w, exclude)
                if wid != exclude and isinstance(wid, Gtk.Notebook):
                    return wid
            return None

    def check_notebook_pages(self, widget):
        if widget.get_n_pages() == 0:
            # eliminar el notebook solo si queda otro notebook y no quedan tabs en el actual
            paned = widget.get_parent()
            if paned is None or paned == self.hpMain:
                return
            if self.console_window_of(widget) is not None:
                # Not a pane: it sits in a console window's box, beside the search bar,
                # and the window closes itself once its last tab has left (#255).
                return
            container = paned.get_parent()
            save = paned.get_child2() if paned.get_child1() == widget else paned.get_child1()
            container.remove(paned)
            paned.remove(save)
            container.add(save)
            if widget == self.nbConsole:
                if isinstance(save, Gtk.Notebook):
                    self.nbConsole = save
                else:
                    self.nbConsole = self.find_notebook(save)
            p = self.nbConsole.get_current_page()
            self.on_tab_focus(self.nbConsole, self.nbConsole.get_nth_page(p), p)

    def on_page_removed(self, widget, *args):
        self.count -= 1
        if widget.get_current_page() == -1:
            self.on_tab_focus(widget, None)

        if hasattr(widget, "is_closed") and widget.is_closed:
            # tab has been closed
            self.check_notebook_pages(widget)
        else:
            # tab has been moved to another notebook
            # save a reference to this notebook, on_page_added check if the notebook must be removed
            self.check_notebook = widget

    def on_page_added(self, widget, *args):
        self.count += 1
        if hasattr(self, "check_notebook"):
            self.check_notebook_pages(self.check_notebook)
            delattr(self, "check_notebook")

    def show_save_buffer(self, terminal):
        """Save Buffer is the same operation as the viewer's Save As, minus the window."""
        return self.save_text_to_file(terminal_buffer_text(terminal))

    def clipboard_relay_path(self):
        """Path of the socket relays report clipboard writes to, created on first use."""
        existing = getattr(self, "_clipboard_socket_path", None)
        if existing:
            return existing
        directory = tempfile.mkdtemp(prefix="gcm-clip-")
        path = str(Path(directory) / "clipboard.sock")
        try:
            server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            server.bind(path)
            server.listen(8)
            server.setblocking(False)
        except OSError:
            logger.exception("Could not open the OSC 52 relay socket")
            return None
        self._clipboard_socket = server
        self._clipboard_socket_path = path
        GLib.io_add_watch(server.fileno(), GLib.IO_IN, self._on_clipboard_connection)
        return path

    def _on_clipboard_connection(self, _source, _condition):
        try:
            connection, _ = self._clipboard_socket.accept()
        except OSError:
            return True
        connection.setblocking(False)
        buffer = bytearray()
        GLib.io_add_watch(
            connection.fileno(),
            GLib.IO_IN | GLib.IO_HUP,
            lambda _source, condition: self._on_clipboard_data(connection, buffer, condition),
        )
        return True

    def _on_clipboard_data(self, connection, buffer, condition):
        try:
            chunk = connection.recv(65536)
        except OSError:
            chunk = b""
        if not chunk:
            connection.close()
            return False
        buffer.extend(chunk)
        while b"\n" in buffer:
            line, _, rest = bytes(buffer).partition(b"\n")
            buffer.clear()
            buffer.extend(rest)
            self._apply_clipboard_message(line)
        return not (condition & GLib.IO_HUP)

    def _apply_clipboard_message(self, line):
        """Put a relayed OSC 52 payload on the clipboard.

        Re-checks the preference: a session started while it was on must stop being
        able to write here the moment it is turned off.
        """
        if not conf.OSC52_ENABLED:
            return False
        try:
            message = json.loads(line.decode("utf-8"))
            data = base64.b64decode(message["data"], validate=True)
        except (ValueError, KeyError, TypeError, AttributeError, binascii.Error):
            logger.debug("Discarding a malformed clipboard message from a relay")
            return False
        text = data.decode("utf-8", "replace")
        if not text:
            return False
        Gtk.Clipboard.get_default(Gdk.Display.get_default()).set_text(text, -1)
        return True

    def save_text_to_file(self, text, parent=None, name=None, folder=None):
        """Ask for a filename and write text to it. Shared by Save Buffer and the viewer."""
        dlg = Gtk.FileChooserDialog(
            title=_("Guardar como"),
            parent=parent or self.wMain,
            action=Gtk.FileChooserAction.SAVE,
        )
        dlg.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        dlg.add_button("document-save", Gtk.ResponseType.OK)
        dlg.set_do_overwrite_confirmation(True)
        dlg.set_current_name(
            name or Path("gcm-buffer-{}.txt".format(time.strftime("%Y%m%d%H%M%S"))).name
        )
        if not hasattr(self, "lastPath"):
            self.lastPath = USERHOME_DIR
        dlg.set_current_folder(folder or self.lastPath)
        saved = False
        if dlg.run() == Gtk.ResponseType.OK:
            filename = dlg.get_filename()
            self.lastPath = str(Path(filename).parent)
            try:
                with Path(filename).open("w") as handle:
                    handle.write(text)
                saved = True
            except (OSError, PermissionError) as e:
                dlg.destroy()
                msgbox(f"{_('No se puede abrir archivo para escritura')}: {filename} - {e}")
                return False
        dlg.destroy()
        return saved

    def save_session_transcript(self, terminal):
        """Rebuild a readable transcript of this session's recording and save it.

        Only sessions recorded with `raw-session-log` have anything to rebuild from --
        the text log is already linear, and a session that was never recorded has no
        record of the frames a full-screen application drew.

        Replay is shown as it runs rather than done behind a spinner, because it is not
        instant: the alternate screen has to go through the terminal one frame at a
        time, at VTE's own ~60Hz parsing tick, so a long session takes a while and the
        user needs to be able to stop.
        """
        if terminal is None:
            return None
        raw_path = getattr(terminal, "raw_path", None)
        if not raw_path or not Path(raw_path).exists():
            # Recording is off by default, and a recording is opened when the session
            # spawns -- so turning it on does nothing for sessions already running. Say
            # where to turn it on and that it takes a new session, or the message reads
            # as a failure rather than as something the reader can act on. Where is the
            # checkbox in Preferences, named by its label. This once said gcm.conf, and
            # an edit there while GCM runs never takes effect: the running GCM does not
            # read it again, and its next save writes the old value back (#166).
            # One string literal, not two joined: the i18n guard matches a single
            # quoted argument, so a concatenated msgid silently escapes the check.
            msgbox(
                _(
                    "Esta sesión no tiene grabación. Active «Grabar la sesión en crudo» en Preferencias y abra una sesión nueva."
                ),
                self.wMain,
            )
            return None
        dialog = Gtk.Dialog(title=_("Reconstruyendo transcripción"), parent=self.wMain, modal=True)
        dialog.set_icon_from_file(ICON_PATH)
        dialog.add_button("_Cancel", Gtk.ResponseType.CANCEL)
        bar = Gtk.ProgressBar()
        bar.set_show_text(True)
        bar.set_margin_start(12)
        bar.set_margin_end(12)
        bar.set_margin_top(12)
        bar.set_margin_bottom(6)
        dialog.get_content_area().pack_start(bar, True, True, 0)
        dialog.show_all()

        def on_progress(done, total):
            bar.set_fraction(done / total if total else 1.0)
            bar.set_text(f"{done} / {total}")

        def on_finished(text):
            dialog.destroy()
            if not text:
                # Closing the dialog and doing nothing else reads as the feature being
                # broken. A recording with nothing in it yet is the ordinary case right
                # after a session starts.
                msgbox(_("Esta grabación todavía no contiene texto"), self.wMain)
                return
            self.save_text_to_file(
                text,
                self.wMain,
                name=Path(raw_path).with_suffix(".txt").name,
                folder=str(Path(raw_path).parent),
            )

        replayer = TranscriptReplayer(
            raw_path,
            timing_path_for(raw_path),
            terminal.get_column_count(),
            terminal.get_row_count(),
            on_finished,
            on_progress,
        )
        # The dialog is the only way to stop a long replay, so any response -- the
        # button or the window manager's close -- has to reach the replayer.
        dialog.connect("response", lambda *_args: replayer.cancel())
        dialog.connect("delete-event", lambda *_args: replayer.cancel())
        replayer.start()
        return replayer

    def show_snippet_picker(self, terminal):
        """Find a snippet by name or text, and send it to `terminal` (#240)."""
        if terminal is None:
            return None
        picker = SnippetPicker(self, terminal)
        picker.show_all()
        return picker

    def show_buffer_viewer(self, terminal):
        """Open the scrollback in a text window where the keyboard works."""
        if terminal is None:
            return None
        label = self.get_tab_label_for_terminal(terminal)
        name = label.get_text().strip() if label is not None and hasattr(label, "get_text") else ""
        viewer = BufferViewer(self, terminal, "{} - {}".format(_("Buffer"), name or _("Consola")))
        viewer.show_all()
        return viewer

    def set_panel_visible(self, visibility):
        if visibility:
            GLib.timeout_add(
                200,
                lambda: self.hpMain.set_position(
                    self.hpMain.previous_position if self.hpMain.previous_position > 10 else 150
                ),
            )
        else:
            self.hpMain.previous_position = self.hpMain.get_position()
            GLib.timeout_add(200, lambda: self.hpMain.set_position(0))
        conf.SHOW_PANEL = visibility
        self._update_toggle_action("toggle-panel", visibility)

    def fit_toolbar_items(self):
        """Let each toolbar item ask for its own width instead of the widest one's.

        GtkToolItems are homogeneous by default, so every item is padded out to match
        the widest -- Connect, at 183px. That inflates a toolbar whose items need
        1,503px into a 2,333px request, wider than a 1920px screen, and GtkToolbar
        moves whatever no longer fits into its overflow menu.

        That menu is not a usable fallback (#86). GTK anchors its left edge to the
        arrow at the right end of the toolbar, so it opens off the screen, and the
        search box and Donate button have no proxy menu item, so they do not appear in
        it at all -- they just vanish. Keeping the items on the toolbar avoids all of
        it, and stops five buttons being padded to four times the width they need.
        """
        toolbar = self.get_widget("toolbar1")
        if toolbar is None:
            return
        for index in range(toolbar.get_n_items()):
            item = toolbar.get_nth_item(index)
            if item is not None:
                item.set_homogeneous(False)

    def set_toolbar_visible(self, visibility):
        # self.get_widget("toolbar1").set_visible(visibility)
        if visibility:
            self.get_widget("toolbar1").show()
        else:
            self.get_widget("toolbar1").hide()
        conf.SHOW_TOOLBAR = visibility
        self._update_toggle_action("toggle-toolbar", visibility)

    def _update_toggle_action(self, action_name, state):
        window = self.get_widget("wMain")
        application = window.get_application() if isinstance(window, Gtk.Window) else None
        if application is None:
            return
        action = application.lookup_action(action_name)
        if action is None:
            return
        current_state = action.get_state()
        current_value = current_state.get_boolean() if current_state is not None else None
        if current_value != state:
            action.set_state(GLib.Variant("b", state))

    def sync_console_log_action(self, terminal):
        window = self.get_widget("wMain")
        application = window.get_application() if isinstance(window, Gtk.Window) else None
        if application is None:
            return
        action = application.lookup_action("console-log")
        if action is None:
            return
        enabled = hasattr(terminal, "log_handler_id") and terminal.log_handler_id != 0
        action.set_state(GLib.Variant("b", enabled))

    def set_context_terminal(self, terminal):
        self._context_terminal = terminal
        if isinstance(terminal, Vte.Terminal):
            self.sync_console_log_action(terminal)

    def clear_context_terminal(self, *args):
        self._context_terminal = None

    def get_target_terminal(self):
        """The terminal an action acts on: the one whose menu is open, else the tab's.

        The tab is the one whose menu is open, else the tab in use. None when that tab
        holds no terminal, so a terminal action does nothing there. It fell back to the
        last terminal given the keyboard, on a tab nobody was looking at (#223).
        """
        if self._context_terminal is not None:
            return self._context_terminal
        return page_terminal(self.get_context_tab_widget())

    def set_context_tab_widget(self, widget):
        self._context_tab_widget = widget
        terminal = page_terminal(widget)
        if terminal is not None:
            self.set_context_terminal(terminal)
        else:
            self.clear_context_terminal()

    def clear_context_tab_widget(self, *args):
        self._context_tab_widget = None

    def on_context_menu_hide(self, _menu):
        """Forget what a terminal's or a tab's menu was opened for, once its item has run.

        GTK hides a menu before the chosen item's action runs, measured, and that action
        reads this context, so it goes from an idle callback rather than from here (#219).
        The terminal's menu cleared its terminal here, and each item then acted on the
        terminal with the keyboard, in the other pane after a split (#221). The tab menu
        cleared its tab alone, and at once: the terminal stayed the target of the next
        shortcut, so a paste or a Ctrl+W went to a tab nobody was looking at (#219).
        """
        GLib.idle_add(self.forget_menu_context)

    def forget_menu_context(self):
        self.clear_context_tab_widget()
        self.clear_context_terminal()
        return False

    def get_context_tab_widget(self):
        """The tab an action acts on: the one whose menu is open, else the tab in use.

        A terminal's menu names its tab through the terminal. Its Reset, Reset and clear
        and Clone come here, and acted on the tab in use instead (#221). The tab in use
        is the one showing in the pane the keyboard is in, or was last in. This read the
        main pane, whichever pane the keyboard was in after a split (#219).
        """
        if self._context_tab_widget is not None:
            return self._context_tab_widget
        page = self._context_terminal.get_parent() if self._context_terminal is not None else None
        if page is not None and page.get_parent() is not None:
            return page
        return self.page_in_use()

    def get_context_tab_label(self):
        widget = self.get_context_tab_widget()
        if widget is None:
            return None
        notebook = widget.get_parent()
        return notebook.get_tab_label(widget)

    def set_context_tree_path(self, path):
        self._context_tree_path = path

    def clear_context_tree_path(self, *args):
        self._context_tree_path = None

    def get_context_tree_iter(self):
        if self._context_tree_path is not None:
            try:
                return self.treeModel.get_iter(self._context_tree_path)
            except (TypeError, ValueError):
                return None
        selection = self.treeServers.get_selection()
        model, iter_ = selection.get_selected()
        return iter_

    def get_selected_host(self):
        iter_ = self.get_context_tree_iter()
        if iter_ is None or self.is_folder_row(iter_):
            return None
        return self.treeModel.get_value(iter_, 1)

    def copy_selected_address(self):
        host = self.get_selected_host()
        if host is None:
            return
        cb = Gtk.Clipboard.get_default(Gdk.Display.get_default())
        cb.set_text(host.host, len(host.host))
        cb.store()

    # A host's files, outside its console (#267).

    def prepare_files_items(self, host):
        """Offer a host's files in the tree's menu only for a type that opens them over
        SFTP, with Unmount SSHFS in place of Mount with SSHFS while it is mounted."""
        menu = self.popupMenuFolder
        offered = host is not None and connections.for_host(host).sftp
        mounted = offered and self.files_mount(host) is not None
        menu.mnuOpenFiles.set_visible(offered)
        menu.mnuMount.set_visible(offered and not mounted)
        menu.mnuUnmount.set_visible(mounted)

    def files_user(self, host):
        """Who a host's files are opened as: its user, or the local one, as its console
        connects when it names none."""
        return host.user or get_username()

    def files_folder(self, host):
        """Where Mount with SSHFS puts a host: ~/mnt/<its name>."""
        return remotefiles.mount_folder(Path.home(), host.name)

    def files_source(self, host):
        """What sshfs mounts of a host, which the mount table names its mount by."""
        return remotefiles.sshfs_source(host.host, self.files_user(host))

    def find_mounts(self, host=None):
        """The sshfs mounts in ~/mnt but one still being made, {folder: what is mounted
        there}, in the mount table's order, and where each host is mounted, {host: folder}:
        each of the tree's hosts whose files open over SFTP, and `host`."""
        root = remotefiles.mount_root(Path.home())
        # Measured, a mount made through a link is listed at the folder the link leads to.
        listed = remotefiles.sshfs_mounts(read_mount_table(), root.resolve())
        mounts = {
            root / folder.name: source
            for folder, source in listed.items()
            if root / folder.name not in self.mounting
        }
        hosts = [
            each for filed in groups.values() for each in filed if connections.for_host(each).sftp
        ]
        if host is not None and all(each is not host for each in hosts):
            hosts.append(host)
        found = remotefiles.find_mounts(
            [(each.name, self.files_source(each)) for each in hosts], mounts, root
        )
        return mounts, {
            each: folder for each, folder in zip(hosts, found, strict=True) if folder is not None
        }

    def files_mount(self, host):
        """The folder in ~/mnt `host` is mounted at by sshfs, or None: where its name puts
        it, or, for a host renamed since, where its old name did."""
        return self.find_mounts(host)[1].get(host)

    def watch_mounts(self):
        """Follow the mount table, so that the tree, Servers ▸ Mounted and the Mounted tab
        show what is mounted however it was mounted or unmounted, by GCM or not."""
        self.mount_monitor = Gio.UnixMountMonitor.get()
        self.mount_monitor.connect("mounts-changed", lambda _monitor: self.show_mounts())

    def show_mounts(self):
        """Mark each host mounted in the tree and the Hosts menu, and list each mount in
        Servers ▸ Mounted and the Mounted tab, as the mount table has them now."""
        mounts, found = self.find_mounts()
        items = getattr(self, "host_items", {})

        def mark(model, _path, iter_):
            host = model.get_value(iter_, 1)
            if host is None:
                return False
            folder = mounted_at(host, found)
            # Only a host whose mount changed, as each change redraws its row.
            if model.get_value(iter_, 5) != folder:
                model.set_value(iter_, 5, folder)
                if host in items:
                    text = marked_name(host.name, folder)
                    self.label_menu_item(items[host], text, tabcolors.tab_color(host, folders))
            return False

        self.treeModel.foreach(mark)
        self.list_mounts(mounts, found)

    def list_mounts(self, mounts, found):
        """Each mount in ~/mnt, by its host's name, or by what is mounted where no host is
        found for it: in the server pane's Mounted tab (#269), and in Servers ▸ Mounted, to
        unmount, with Unmount All while there is one."""
        listed = [
            (folder, name, "~/" + str(folder.relative_to(Path.home())))
            for folder, name in mount_names(mounts, found).items()
        ]
        # Unchanged, it is left alone, as the mount table changes for any mount at all.
        if listed == getattr(self, "listed_mounts", None):
            return
        self.listed_mounts = listed
        self.fill_mounts_page(listed, mounts)
        application = self.application
        section = getattr(application, "mounts_section", None)
        if section is None:
            return
        section.remove_all()
        for folder, name, shown in listed:
            item = Gio.MenuItem.new(menu_label(_("Unmount {} from {}").format(name, shown)), None)
            item.set_action_and_target_value("app.unmount-folder", GLib.Variant("s", str(folder)))
            section.append_item(item)
        if not listed:
            # Given Unmount All, disabled now, so that GTK draws it greyed: measured, an
            # item with no action is drawn as one to choose.
            section.append(_("Nothing is mounted"), "app.unmount-all")
        application.lookup_action("unmount-all").set_enabled(bool(listed))

    def fill_mounts_page(self, listed, mounts):
        """The Mounted tab's rows, from `listed`, and the tab itself, shown only while
        something is mounted. Back to the tree as it goes, so that the pane is never left
        on a tab no longer shown."""
        notebook = getattr(self, "nbServers", None)
        if notebook is None:
            return
        store = self.treeMounts.get_model()
        store.clear()
        for folder, name, shown in listed:
            tooltip = GLib.markup_escape_text(f"{shown}\n{mounts[folder]}", -1)
            store.append([name, str(folder), tooltip])
        page = notebook.get_nth_page(1)
        if listed:
            self.lblMountsTab.set_text(_("Mounted ({})").format(len(listed)))
            page.show()
        else:
            notebook.set_current_page(0)
            page.hide()

    def mounted_host(self, folder):
        """The host whose mount the Mounted tab lists at `folder`, or None for a mount that
        is no host's. Read again, as a host edited since was made anew."""
        _mounts, found = self.find_mounts()
        return next((host for host, at in found.items() if at == folder), None)

    def open_mounted_folder(self, folder):
        """Open Folder: the mount itself, its folder in ~/mnt, in the file manager."""
        open_in_file_manager(Gio.File.new_for_path(str(folder)).get_uri())

    def open_mounted_over_sftp(self, folder):
        """Open over SFTP: the host mounted at `folder`, as Open in File Manager opens it
        from the tree. Offered only for a host's mount, as the mount table names no port."""
        host = self.mounted_host(folder)
        if host is not None:
            open_in_file_manager(
                remotefiles.sftp_address(host.host, self.files_user(host), host.port)
            )

    def on_treeMounts_button_press_event(self, widget, event, *args):
        """The Mounted tab's menu, for the row clicked: Open over SFTP greyed for a mount
        that is no host's, and below the rows, all but Unmount All."""
        if event.type != Gdk.EventType.BUTTON_PRESS or event.button != 3:
            return False
        hit = widget.get_path_at_pos(int(event.x), int(event.y))
        folder = None
        if hit is not None:
            widget.get_selection().select_path(hit[0])
            store = widget.get_model()
            folder = Path(store.get_value(store.get_iter(hit[0]), 1))
        self.mount_menu_folder = folder
        menu = self.popupMenuMounts
        menu.mnuOpenFolder.set_sensitive(folder is not None)
        menu.mnuOpenSftp.set_sensitive(folder is not None and self.mounted_host(folder) is not None)
        menu.mnuUnmount.set_sensitive(folder is not None)
        menu.mnuUnmountAll.set_sensitive(bool(getattr(self, "listed_mounts", None)))
        menu.popup_at_pointer(event)
        return True

    def on_treeMounts_row_activated(self, widget, path, _column):
        """A double-click opens the row's folder, as Open Folder does."""
        store = widget.get_model()
        self.open_mounted_folder(Path(store.get_value(store.get_iter(path), 1)))

    def selected_files_host(self):
        """The host the tree's menu was opened on, when its files open over SFTP."""
        host = self.get_selected_host()
        return host if host is not None and connections.for_host(host).sftp else None

    def open_selected_files(self):
        """Open in File Manager: the host's sftp:// address, which holds no password."""
        host = self.selected_files_host()
        if host is not None:
            open_in_file_manager(
                remotefiles.sftp_address(host.host, self.files_user(host), host.port)
            )

    def mount_selected_files(self):
        """Mount with SSHFS: the host at ~/mnt/<its name>, where nothing is mounted yet.

        Two actions, Mount and Unmount, and not one that does either: the Servers menu
        names each, and a menubar's label cannot follow the host selected."""
        host = self.selected_files_host()
        if host is None:
            return
        folder = self.files_folder(host)
        if folder in self.mounting:
            return
        mounted = self.files_mount(host)
        # The folder as the mount table names it, as find_mounts reads it.
        other = remotefiles.mount_at(read_mount_table(), folder.parent.resolve() / folder.name)
        if mounted is not None:
            msginfo(_("{} is mounted at {} already.").format(host.name, mounted))
        elif other is not None:
            msgbox(_("Something else is mounted at {}: {}").format(folder, other[1]))
        else:
            self.mount_files(host, folder)

    def unmount_selected_files(self):
        """Unmount SSHFS: the host, from where it is mounted, and nothing else."""
        host = self.selected_files_host()
        if host is None:
            return
        mounted = self.files_mount(host)
        if mounted is not None:
            self.unmount_files(host.name, mounted)
        else:
            msginfo(_("{} is not mounted at {}.").format(host.name, self.files_folder(host)))

    def unmount_folder(self, folder):
        """Servers ▸ Mounted, and the Mounted tab's Unmount: unmount the sshfs mount at
        `folder` they list, while it is there."""
        names = mount_names(*self.find_mounts())
        if folder in names:
            self.unmount_files(names[folder], folder)
        else:
            msginfo(_("{} is not mounted at {}.").format(folder.name, folder))

    def unmount_all_files(self):
        """Unmount All, in Servers ▸ Mounted and the Mounted tab: each sshfs mount in ~/mnt,
        said once for all."""
        names = mount_names(*self.find_mounts())
        if not names:
            return
        program = fusermount()
        if program is None:
            msgbox(_("Unmounting needs fusermount, which is not installed."))
            return
        said, failed = {}, set()

        def done(folder, reason):
            if reason is None:
                said[folder] = _("Unmounted {} from {}.").format(names[folder], folder)
            else:
                said[folder] = _("Could not unmount {}: {}").format(folder, reason)
                failed.add(folder)
            if len(said) == len(names):
                (msgbox if failed else msginfo)("\n".join(said[each] for each in names))

        for folder in names:
            self.run_unmount(program, folder, lambda reason, folder=folder: done(folder, reason))

    def mount_files(self, host, folder):
        """Mount a host's login folder at `folder` with sshfs, as a daemon in a session of
        its own, so that it lasts until it is unmounted, GCM or its terminal closing or not.

        A daemon, since one exits 0 once connected, measured, and the mount, made before
        connecting, says nothing. ssh's messages go to a log beside the runtime files, as
        a daemon drops them, and a reconnect opens it again, so it stays. A mount that
        fails removes `folder` again, while it is empty.
        """
        if folder in self.mounting:
            return
        if remotefiles.read_as_option(host.host, self.files_user(host)):
            msgbox(
                _("Could not mount {} at {}: {}").format(
                    host.name,
                    folder,
                    _("its user begins with -, which ssh would read as an option."),
                )
            )
            return
        sshfs = shutil.which("sshfs")
        if sshfs is None:
            msgbox(_("Mounting a host needs sshfs, which is not installed."))
            return
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError as error:
            msgbox(_("Could not mount {} at {}: {}").format(host.name, folder, error.strerror))
            return
        # In the runtime folder, which is the user's alone, and nowhere shared such as
        # /tmp, where another user could put a link where the log goes, for this to empty
        # the file it names. Without it, sshfs's own words have to do.
        log = remotefiles.ssh_log([Path(GLib.get_user_runtime_dir(), "gcm")], folder.name)
        if log is not None:
            try:
                log.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                log.write_text("")  # this attempt's messages only
            except OSError:
                log = None
        argv = remotefiles.sshfs_command(
            sshfs, host.host, self.files_user(host), host.port, host.private_key, folder, log
        )
        # The password reaches ssh through the askpass helper, in the environment, which
        # only its owner can read, never on a command line.
        environment = dict(os.environ, SSH_ASKPASS=ASKPASS_COMMAND, SSH_ASKPASS_REQUIRE="force")
        environment.pop(placeholders.PASSWORD_VARIABLE, None)
        if host.password:
            environment[placeholders.PASSWORD_VARIABLE] = host.password
        try:
            pid, _stdin, _stdout, stderr = GLib.spawn_async(
                argv,
                envp=[f"{name}={value}" for name, value in environment.items()],
                flags=GLib.SpawnFlags.DO_NOT_REAP_CHILD
                | GLib.SpawnFlags.STDIN_FROM_DEV_NULL
                | GLib.SpawnFlags.STDOUT_TO_DEV_NULL,
                child_setup=os.setsid,
                standard_error=True,
            )
        except GLib.Error as error:
            remove_mount_folder(folder)
            msgbox(_("Could not mount {} at {}: {}").format(host.name, folder, error.message))
            return
        self.mounting = self.mounting | {folder}

        def exited(pid, status):
            GLib.spawn_close_pid(pid)
            self.mounting = self.mounting - {folder}
            # Mounted once sshfs has connected, which find_mounts leaves out until it has.
            self.show_mounts()
            output = read_finished(stderr)
            code = os.waitstatus_to_exitcode(status)
            if code == 0:
                msginfo(_("Mounted {} at {}.").format(host.name, folder))
                return
            try:
                ssh_log = log.read_text(errors="replace") if log is not None else ""
            except OSError:
                ssh_log = ""
            reason = remotefiles.failure_reason(ssh_log, output)
            # Measured, a failed sshfs has unmounted by the time it exits.
            remove_mount_folder(folder)
            msgbox(
                _("Could not mount {} at {}: {}").format(
                    host.name, folder, reason or "sshfs {} {}".format(_("exited with status"), code)
                )
            )

        GLib.child_watch_add(GLib.PRIORITY_DEFAULT, pid, exited)

    def unmount_files(self, name, folder):
        """Unmount what sshfs mounted at `folder`, remove the folder, and say so, calling
        the host `name`, as mounting does. The sshfs daemon and its ssh end with the
        mount."""
        program = fusermount()
        if program is None:
            msgbox(_("Unmounting needs fusermount, which is not installed."))
            return

        def done(reason):
            if reason is None:
                msginfo(_("Unmounted {} from {}.").format(name, folder))
            else:
                msgbox(_("Could not unmount {}: {}").format(folder, reason))

        self.run_unmount(program, folder, done)

    def run_unmount(self, program, folder, done):
        """Unmount `folder` with `program`, a fusermount, then remove the folder and call
        `done` with None, or, where it could not, with why."""
        try:
            pid, _stdin, _stdout, stderr = GLib.spawn_async(
                [program, "-u", str(folder)],
                flags=GLib.SpawnFlags.DO_NOT_REAP_CHILD
                | GLib.SpawnFlags.STDIN_FROM_DEV_NULL
                | GLib.SpawnFlags.STDOUT_TO_DEV_NULL,
                standard_error=True,
            )
        except GLib.Error as error:
            done(error.message)
            return

        def exited(pid, status):
            GLib.spawn_close_pid(pid)
            output = read_finished(stderr)
            code = os.waitstatus_to_exitcode(status)
            if code == 0:
                remove_mount_folder(folder)
                self.show_mounts()
                done(None)
                return
            reason = remotefiles.failure_reason("", output)
            done(reason or "{} {} {}".format(Path(program).name, _("exited with status"), code))

        GLib.child_watch_add(GLib.PRIORITY_DEFAULT, pid, exited)

    def duplicate_selected_host(self):
        host = self.get_selected_host()
        if host is None:
            return
        iter_ = self.get_context_tree_iter()
        if iter_ is None:
            return
        group = self.get_group(iter_)
        newhost = host.clone()
        newhost.name = copy_name(host.name, {h.name for h in groups.get(group, [])})
        groups.setdefault(group, []).append(newhost)
        place_copy(host, newhost)
        self.updateTree()
        self.writeConfig()

    def selected_tree_folder(self):
        """The folder the selection is in: a folder row's own, a host row's folder, or
        the top level when nothing is selected."""
        iter_ = self.treeServers.get_selection().get_selected()[1]
        if iter_ is None:
            return ROOT_FOLDER
        if self.is_folder_row(iter_):
            return self.folder_id_at(iter_)
        return self.treeModel.get_value(iter_, 1).folder

    def folder_error_text(self, error, parent, name):
        if error.reason == NAME_HAS_SEPARATOR:
            return _("A folder name cannot contain /")
        if error.reason == NAME_TAKEN:
            return "{} [{}] {} [{}]".format(
                _("El nombre"), name.strip(), _("ya existe para el grupo"), folders.path_for(parent)
            )
        return None

    def apply_folder_edit(self, edit, parent, name):
        """Run one folder edit; say why when the tree refuses it. True if it happened."""
        try:
            edit()
        except FolderError as error:
            text = self.folder_error_text(error, parent, name)
            if text is None:
                logger.error("Folder edit refused: %s", error.reason)
            else:
                msgbox(text)
            return False
        self.updateTree()
        self.writeConfig()
        return True

    def new_folder(self):
        parent = self.selected_tree_folder()
        name = inputbox(_("New Folder"), _("Ingrese nuevo nombre"), parent=self.window)
        if not name or not name.strip():
            return
        created: list = []
        if self.apply_folder_edit(lambda: created.append(folders.add(parent, name)), parent, name):
            self.select_folder_row(created[0].id)

    def rename_selected_folder(self):
        iter_ = self.treeServers.get_selection().get_selected()[1]
        if iter_ is None or not self.is_folder_row(iter_):
            return
        folder = folders.folders[self.folder_id_at(iter_)]
        name = inputbox(
            _("Rename Folder"), _("Ingrese nuevo nombre"), folder.name, parent=self.window
        )
        if not name or not name.strip() or name.strip() == folder.name:
            return
        if self.apply_folder_edit(lambda: folders.rename(folder.id, name), folder.parent, name):
            self.select_folder_row(folder.id)

    def color_selected_folder(self):
        """Choose the colour of the selected folder's tabs, or none (#350): those of every
        host below it without a colour of its own, or a nearer folder's."""
        iter_ = self.treeServers.get_selection().get_selected()[1]
        if iter_ is None or not self.is_folder_row(iter_):
            return
        folder = folders.folders[self.folder_id_at(iter_)]
        color = choose_tab_color(folder.tab_color, parent=self.window)
        if color is None or color == folder.tab_color:
            return
        folder.tab_color = color
        self.updateTree()
        self.writeConfig()
        self.select_folder_row(folder.id)

    def sort_selected_folder(self):
        """Put the selected folder back in name order, and keep it there as hosts are
        added. Only that folder: its subfolders keep whatever order they were given."""
        order = folder_contents().get(self.selected_tree_folder(), [])
        if all(child.position is None for child in order):
            return
        for child in order:
            child.position = None
        self.updateTree()
        self.writeConfig()

    def select_folder_row(self, folder_id):
        """Show a folder after a redraw, opening whatever it sits in."""
        found: list = []

        def visit(model, path, iter_):
            if self.is_folder_row(iter_) and self.folder_id_at(iter_) == folder_id:
                found.append(path.copy())
                return True
            return False

        self.treeModel.foreach(visit)
        if found:
            self.treeServers.expand_to_path(found[0])
            self.treeServers.set_cursor(found[0], None, False)

    def dragged_tree_item(self):
        """("host", Host) or ("folder", id) for the row being dragged: the one under the
        press that started it. Not the selection -- measured with real pointer input, a
        press on a folder's expander arrow starts a drag without selecting the folder,
        and the selection would then carry whatever row was selected before."""
        if self._drag_source_path is None:
            return None
        try:
            iter_ = self.treeModel.get_iter(self._drag_source_path)
        except ValueError:
            return None
        if self.is_folder_row(iter_):
            return ("folder", self.folder_id_at(iter_))
        return ("host", self.treeModel.get_value(iter_, 1))

    def drop_target(self, x, y):
        """Where a drop at (x, y) lands, as `(folder_id, beside, after)`.

        On the edge of a row -- the line GTK draws between rows -- it lands in that row's
        folder, next to that row: `beside` is the row's host or folder record, and
        `after` says which side. On the middle of a folder row it goes into that folder,
        and on the middle of a host row into the host's folder, with no place asked for.
        Below every row it goes to the top level."""
        dest = self.treeServers.get_dest_row_at_pos(x, y)
        if dest is None:
            return ROOT_FOLDER, None, False
        path, position = dest
        iter_ = self.treeModel.get_iter(path)
        edge = position in (Gtk.TreeViewDropPosition.BEFORE, Gtk.TreeViewDropPosition.AFTER)
        after = position == Gtk.TreeViewDropPosition.AFTER
        if not self.is_folder_row(iter_):
            host = self.treeModel.get_value(iter_, 1)
            return (host.folder, host, after) if edge else (host.folder, None, False)
        folder = folders.folders[self.folder_id_at(iter_)]
        return (folder.parent, folder, after) if edge else (folder.id, None, False)

    def drop_refusal(self, item, target):
        """None when `item` may land at `target`, otherwise the reason it may not."""
        kind, subject = item
        folder_id, beside, after = target
        record = subject if kind == "host" else folders.folders[subject]
        if folder_id == (subject.folder if kind == "host" else record.parent):
            if beside is None or beside is record:
                return "already there"
            order = folder_contents()[folder_id]
            if arranged(order, record, beside, after=after) == order:
                return "already there"
            return None
        if kind == "host":
            if folder_id == ROOT_FOLDER:
                return "hosts live in folders"
            if any(
                h.name == subject.name and h.folder == folder_id
                for hs in groups.values()
                for h in hs
            ):
                return NAME_TAKEN
            return None
        try:
            folders.check_move(subject, folder_id)
        except FolderError as error:
            return error.reason
        return None

    def on_treeServers_drag_data_get(self, widget, context, data, info, time):
        item = self.dragged_tree_item()
        if item is not None:
            kind, subject = item
            key = subject.id if kind == "host" else subject
            data.set(data.get_target(), 8, f"{kind}:{key}".encode())

    def on_treeServers_drag_motion(self, widget, context, x, y, time):
        item = self.dragged_tree_item()
        if item is None or self.drop_refusal(item, self.drop_target(x, y)) is not None:
            # Returning True keeps GtkTreeView from accepting the spot itself.
            Gdk.drag_status(context, 0, time)
            widget.set_drag_dest_row(None, Gtk.TreeViewDropPosition.BEFORE)
            return True
        return False  # GtkTreeView highlights the row, and opens a folder hovered over

    def decode_dragged_item(self, raw):
        kind, _sep, key = (raw or b"").decode(errors="replace").partition(":")
        if kind == "folder" and key in folders.folders:
            return ("folder", key)
        if kind == "host":
            for group_hosts in groups.values():
                for host in group_hosts:
                    if host.id == key:
                        return ("host", host)
        return None

    def on_treeServers_drag_data_received(self, widget, context, x, y, data, info, time):
        # The row is ours to move; GtkTreeView's own handler would try to insert one.
        widget.stop_emission_by_name("drag-data-received")
        item = self.decode_dragged_item(data.get_data())
        target = self.drop_target(x, y)
        accepted = item is not None and self.drop_refusal(item, target) is None
        if accepted:
            kind, subject = item
            folder_id, beside, after = target
            # The destination as it was drawn, before the item leaves or arrives.
            order = folder_contents().get(folder_id, [])
            if kind == "host":
                record = subject
                subject.folder = folder_id
            else:
                record = folders.folders[subject]
                folders.move(subject, folder_id)
            place(order, record, beside, after=after)
            self.updateTree()
            self.writeConfig()
        Gtk.drag_finish(context, accepted, False, time)

    def expand_all_groups(self):
        self.treeServers.expand_all()

    def collapse_all_groups(self):
        self.treeServers.collapse_all()

    def send_snippet_by_id(self, snippet_id):
        """Send the snippet a menu names to the terminal the menu is for (#240)."""
        snippet = next((each for each in snippets if each.id == snippet_id), None)
        terminal = self.get_target_terminal()
        if snippet is not None and terminal is not None:
            self.send_snippet(snippet, terminal)

    def send_snippet(self, snippet, terminal):
        """Type `snippet` into `terminal`, with the values of the terminal's host (#240).
        Say whether it was sent."""
        return self.send_snippet_to(snippet, [terminal])

    def send_snippet_to(self, snippet, terminals, parent=None):
        """Type `snippet` into each of `terminals`, each with its own host's values (#240).

        Each `{?Label}` is asked for first, over `parent` or else the main window: once
        for them all, however often it appears. Cancelling one sends nothing, and with no
        terminal nothing is asked. Say whether it was sent.
        """
        if not terminals:
            return False
        answers = {}
        for label in placeholders.asked(snippet.text):
            answer = inputbox(snippet.name, label.strip(), parent=parent or self.wMain)
            if answer is None:
                return False
            answers[label] = answer
        for terminal in terminals:
            host = getattr(terminal, "host", None)
            values = placeholders.host_values(host) if host is not None else None
            vte_feed(terminal, placeholders.fill_snippet(snippet.text, values, answers))
        return True

    def trigger_popup_action(self, terminal_code, tab_code=None, *args):
        try:
            if tab_code is not None:
                # The tab whose menu was opened, or else the tab in use. Not the label an
                # earlier right-click left behind, which Clone and Reset by key once read:
                # it acted on that tab, and raised before any tab's menu had opened (#219).
                widget = self.get_context_tab_widget()
                if widget is not None:
                    self.set_context_tab_widget(widget)
                    self.on_popupmenu(None, tab_code, *args)
            else:
                terminal = self.get_target_terminal()
                if terminal is not None:
                    self.popupMenu.terminal = terminal
                    self.on_popupmenu(None, terminal_code, *args)
        finally:
            # Even when the action raises. A context left behind sent the next key to its
            # tab, which could be a page already closed (#223).
            self.clear_context_terminal()
            self.clear_context_tab_widget()

    def request_quit(self):
        (conf.WINDOW_WIDTH, conf.WINDOW_HEIGHT) = self.get_widget("wMain").get_size()
        self.writeConfig()
        self.end_sessions()
        self.quit_application()

    def quit_application(self):
        """Quit through GtkApplication when available (fallback to Gtk.main_quit)."""
        # An update check still asking ends with GCM, rather than outlive it (#369).
        if self.update_check is not None:
            self.update_check.force_exit()
        window = self.get_widget("wMain")
        application = window.get_application() if isinstance(window, Gtk.Window) else None
        if application is not None:
            application.quit()
        else:
            Gtk.main_quit()

