    # -- Wmain.on_importar_servidores1_activate {
    def on_importar_servidores1_activate(self, widget, *args):
        filename = show_open_dialog(
            parent=self.wMain, title=_("Abrir"), action=Gtk.FileChooserAction.OPEN
        )
        if filename is not None:
            password = inputbox(
                _("Importar Servidores"), _("Ingrese clave: "), password=True, parent=self.window
            )
            if password is None:
                return

            # abrir archivo con lista de servers y cargarlos en el arbol
            try:
                reading = configfile.load(Path(filename))
                cp = reading.config

                # validar el pass
                s = decrypt(password, cp.get("gcm", "gcm"))
                if s != password[::-1]:
                    msgbox(_("Clave invalida"))
                    return

                if (
                    msgconfirm(_("Se sobreescribirá la lista de servidores, continuar?"))
                    != Gtk.ResponseType.OK
                ):
                    return

                grupos: dict = {}
                imported = []
                for section in cp.sections():
                    if not section.startswith("host "):
                        continue
                    host = HostUtils.load_host_from_ini(
                        cp, section, password, legacy=conf.VERSION == 0
                    )

                    if host.group not in grupos:
                        grupos[host.group] = []

                    grupos[host.group].append(host)
                    imported.append(host)
                refile_ambiguous_hosts(grupos, reading.ambiguous_folders)
                imported_folders, fixes = FolderTree.load(cp)
                if fixes:
                    logger.warning("Repaired %d problem(s) in the folder tree", len(fixes))
            except (
                configfile.UnreadableError,
                configparser.Error,
                ValueError,
                AttributeError,
            ) as e:
                msgbox(f"{_('Archivo invalido')}: {e}")
                return

            # The import replaces the whole list, so these ids only need to be unique
            # among themselves. Host mints one for any record that predates ADR-0001, so
            # what is left is an exported file hand-edited or merged into a repeat.
            HostUtils.ensure_unique_ids(h for hs in grupos.values() for h in hs)
            # sobreescribir lista de hosts
            global groups, folders
            groups = grupos
            folders = imported_folders

            self.updateTree()
            # Once updateTree has filed them, and in the file's order, as loadConfig
            # renames them (#351).
            renamed = HostUtils.ensure_unique_names(imported)
            if renamed:
                self.updateTree()
                self.report_renamed_hosts(renamed)

    # -- Wmain.on_importar_servidores1_activate }

    # -- Wmain.on_exportar_servidores1_activate {
    def on_exportar_servidores1_activate(self, widget, *args):
        filename = show_open_dialog(
            parent=self.wMain, title=_("Guardar como"), action=Gtk.FileChooserAction.SAVE
        )
        if filename is not None:
            password = inputbox(
                _("Exportar Servidores"), _("Ingrese clave: "), password=True, parent=self.window
            )
            if password is None:
                return

            try:
                cp = configparser.RawConfigParser()
                cp.read(filename + ".tmp")
                i = 1
                cp.add_section("gcm")
                cp.set("gcm", "gcm", encrypt(password, password[::-1]))
                global groups
                sync_folders()
                folders.save(cp)
                for grupo in groups:
                    for host in groups[grupo]:
                        section = "host " + str(i)
                        cp.add_section(section)
                        HostUtils.save_host_to_ini(cp, section, host, password)
                        i += 1
                with Path(filename + ".tmp").open("w") as f:
                    cp.write(f)
                Path(filename + ".tmp").rename(filename)
            except (OSError, PermissionError) as e:
                msgbox(f"{_('Archivo invalido')}: {e}")

    # -- Wmain.on_exportar_servidores1_activate }

