    # -- Whost.new }

    # -- Whost custom methods {
    @staticmethod
    def list_folders_in(combo):
        """Every folder's path, empty ones included -- filing a host in one is the point."""
        combo.remove_all()
        for path in sorted(folders.path_for(folder_id) for folder_id in folders.folders):
            combo.append_text(path)

    def build_type_pages(self):
        """A page for each type with settings of its own (#228), drawn as Properties is,
        and placed after Port forwarding, since only the chosen type's page is shown. A
        page keeps what was typed on it while another type is chosen."""
        self.type_pages = {}
        notebook = self.get_widget("nbHost")
        position = notebook.page_num(self.get_widget("tunnelGrid")) + 1
        for kind in connections.CONNECTION_TYPES:
            if not kind.settings:
                continue
            # The rows at the top, at their own height. A grid given the whole page shared
            # its height out among them, and drew a command line's entry half a page tall
            # (#248).
            page = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=6)
            grid = Gtk.Grid(row_homogeneous=True)
            page.pack_start(grid, False, False, 0)
            controls = {}
            for row, setting in enumerate(kind.settings):
                # At its default, which is what a new host starts with; init() fills in
                # what a stored one has.
                if setting.is_flag:
                    control = Gtk.CheckButton(active=setting.default)
                elif setting.is_choice:
                    control = Gtk.ComboBoxText(hexpand=True)
                    for value, label in setting.choices:
                        control.append(value, _(label))
                    control.set_active_id(setting.default)
                else:
                    control = Gtk.Entry(text=setting.default, hexpand=True)
                control.set_margin_start(10)
                grid.attach(Gtk.Label(label=_(setting.label), halign=Gtk.Align.START), 0, row, 1, 1)
                grid.attach(control, 1, row, 1, 1)
                controls[setting.key] = control
            if kind.settings_hint:
                # Drawn as the line of help under the Commands tab's commands is.
                hint = Gtk.Label(halign=Gtk.Align.START, wrap=True, max_width_chars=60, xalign=0)
                text = GLib.markup_escape_text(_(kind.settings_hint))
                hint.set_markup(f"<span size='smaller'>{text}</span>")
                page.pack_start(hint, False, False, 0)
            page.show_all()
            notebook.insert_page(page, Gtk.Label(label=_(kind.settings_title)), position)
            position += 1
            self.type_pages[kind.id] = (page, controls)
        self.show_type_page(connections.named(self.cmbType.get_active_text()))

    def show_type_page(self, kind, ignored=frozenset()):
        """The page of `kind` alone, with the settings in `ignored` greyed (#285)."""
        for type_id, (page, controls) in self.type_pages.items():
            page.set_visible(type_id == kind.id)
            if type_id == kind.id:
                for key, control in controls.items():
                    control.set_sensitive(key not in ignored)

    def fill_type_pages(self, host):
        """Each type's page from what `host` stored, or the defaults."""
        for type_id, (_page, controls) in self.type_pages.items():
            kind = connections.named(type_id)
            values = kind.settings_of(host)
            for setting in kind.settings:
                value, control = values[setting.key], controls[setting.key]
                if setting.is_flag:
                    control.set_active(value)
                elif setting.is_choice:
                    control.set_active_id(value)
                else:
                    control.set_text(value)

    def type_page_values(self, kind):
        """What the page of `kind` holds, by setting key: every one of its settings, which
        `invalid` and `stored_settings` read. Its defaults where no page was built."""
        if kind.id not in self.type_pages:
            return {setting.key: setting.default for setting in kind.settings}
        _page, controls = self.type_pages[kind.id]
        values = {}
        for setting in kind.settings:
            control = controls[setting.key]
            if setting.is_flag:
                values[setting.key] = control.get_active()
            elif setting.is_choice:
                values[setting.key] = control.get_active_id()
            else:
                values[setting.key] = control.get_text().strip()
        return values

    def init(self, group, host=None):
        self.cmbGroup.get_children()[0].set_text(group)
        if host is None:
            self.isNew = True
            return

        self.isNew = False
        self.oldGroup = group
        self.txtName.set_text(host.name)
        self.oldName = host.name
        # Saving builds a new Host rather than mutating this one, so the id has to be
        # carried across by hand or the edit would look like a different record. The
        # position too, or every edit would move the host in a folder someone arranged.
        self.oldId = host.id
        self.oldPosition = host.position
        self.txtDescription.set_text(host.description)
        self.txtHost.set_text(host.host)
        i = self.cmbType.get_model().get_iter_first()
        while i is not None:
            if host.type == self.cmbType.get_model()[i][0]:
                self.cmbType.set_active_iter(i)
                break
            else:
                i = self.cmbType.get_model().iter_next(i)
        self.txtUser.set_text(host.user)
        self.txtPass.set_text(host.password)
        self.txtPrivateKey.set_text(host.private_key)
        self.txtPort.set_text(host.port)
        for t in host.tunnel:
            if t != "":
                tun = t.split(":")
                tun.append(t)
                self.treeModel.append(tun)
        # The text is loaded whether or not it is enabled -- unticking the box turns the
        # commands off, it does not discard them (#151) -- so the checkbox is read from
        # the stored flag rather than derived from the text being non-empty.
        if host.commands is not None and host.commands != "":
            self.txtCommands.get_buffer().set_text(host.commands)
        self.chkCommands.set_active(host.commands_enabled)
        self.txtCommands.set_sensitive(
            host.commands_enabled and connections.named(host.type).sends_commands
        )
        use_keep_alive = (
            host.keep_alive != "" and host.keep_alive != "0" and host.keep_alive is not None
        )
        self.txtKeepAlive.set_sensitive(use_keep_alive)
        self.chkKeepAlive.set_active(use_keep_alive)
        self.txtKeepAlive.set_text(host.keep_alive)
        if (
            host.font_color != ""
            and host.font_color is not None
            and host.back_color != ""
            and host.back_color is not None
        ):
            self.get_widget("chkDefaultColors").set_active(False)
            self.btnFColor.set_sensitive(True)
            self.btnBColor.set_sensitive(True)
            fcolor = host.font_color
            bcolor = host.back_color
        else:
            self.get_widget("chkDefaultColors").set_active(True)
            self.btnFColor.set_sensitive(False)
            self.btnBColor.set_sensitive(False)
            fcolor = DEFAULT_FGCOLOR
            bcolor = DEFAULT_BGCOLOR

        self.btnFColor.set_rgba(parse_color_rgba(fcolor))
        self.btnBColor.set_rgba(parse_color_rgba(bcolor))

        self.btnFColor.selected_color = fcolor
        self.btnBColor.selected_color = bcolor
        self.chkX11.set_active(host.x11)
        self.chkAgent.set_active(host.agent)
        self.chkCompression.set_active(host.compression)
        self.txtCompressionLevel.set_text(host.compressionLevel)
        self.txtExtraParams.set_text(host.extra_params)
        self.chkLogging.set_active(host.log)
        self.cmbBackspace.set_active(host.backspace_key)
        self.cmbDelete.set_active(host.delete_key)
        self.update_texttags()
        self.txtTerm.set_text(host.term)
        self.txtBeforeCommand.set_text(host.before_command)
        self.txtAfterCommand.set_text(host.after_command)
        self.txtTabName.set_text(host.tab_name)
        # Unticked, the button shows the colour the host's tabs take from its folder, where
        # one gives them one (#350).
        own = tabcolors.color_of(host.tab_color)
        shown = own or tabcolors.folder_color(folders, host.folder)
        if shown:
            self.btnTabColor.set_rgba(parse_color_rgba(shown))
        self.chkTabColor.set_active(bool(own))
        self.fill_type_pages(host)

    def update_texttags(self, *args):
        buf = self.txtCommands.get_buffer()
        text_iter = buf.get_start_iter()
        buf.remove_all_tags(text_iter, buf.get_end_iter())
        while True:
            found = text_iter.forward_search("##D=", 0, None)
            if not found:
                break
            start, end = found
            n = end.copy()
            end.forward_line()
            if buf.get_text(n, end, False).rstrip().isdigit():
                buf.apply_tag_by_name("DELAY1", start, n)
                buf.apply_tag_by_name("DELAY2", n, end)
            text_iter = end

    # -- Whost custom methods }

    # -- Whost.on_cancelbutton1_clicked {
    def on_cancelbutton1_clicked(self, widget, *args):
        self.get_widget("wHost").destroy()

    # -- Whost.on_cancelbutton1_clicked }

    # -- Whost.on_okbutton1_clicked {
    def on_okbutton1_clicked(self, widget, *args):
        group = self.cmbGroup.get_active_text().strip()
        name = self.txtName.get_text().strip()
        description = self.txtDescription.get_text().strip()
        host = self.txtHost.get_text().strip()
        ctype = self.cmbType.get_active_text().strip()
        user = self.txtUser.get_text().strip()
        password = self.txtPass.get_text().strip()
        private_key = self.txtPrivateKey.get_text().strip()
        port = self.txtPort.get_text().strip()
        buf = self.txtCommands.get_buffer()
        commands = buf.get_text(buf.get_start_iter(), buf.get_end_iter(), False).strip()
        commands_enabled = self.chkCommands.get_active()
        keepalive = self.txtKeepAlive.get_text().strip()
        if self.get_widget("chkDefaultColors").get_active():
            fcolor = ""
            bcolor = ""
        else:
            fcolor = color_to_hex(self.btnFColor.get_rgba())
            bcolor = color_to_hex(self.btnBColor.get_rgba())

        x11 = self.chkX11.get_active()
        agent = self.chkAgent.get_active()
        compression = self.chkCompression.get_active()
        compressionLevel = self.txtCompressionLevel.get_text().strip()
        extra_params = self.txtExtraParams.get_text()
        log = self.chkLogging.get_active()
        backspace_key = self.cmbBackspace.get_active()
        delete_key = self.cmbDelete.get_active()

        if ctype == "":
            ctype = "ssh"
        kind = connections.named(ctype)
        tunnel = ""

        if kind.ssh_options:
            for x in self.treeModel:
                tunnel = f"{x[3]},{tunnel}"
            tunnel = tunnel[:-1]

        # Validar datos
        needs_address = kind.remote and not kind.runs_without_address
        if group == "" or name == "" or (host == "" and needs_address):
            msgbox(_("Los campos grupo, nombre y host son obligatorios"))
            return
        type_values = self.type_page_values(kind)
        # A greyed setting is checked as if it held its default: only a hand edit gives it
        # a value this refuses, and greyed, it could not be corrected here (#285).
        ignored = kind.ignores(connection_programs())
        problem = kind.invalid(
            {
                setting.key: setting.default if setting.key in ignored else type_values[setting.key]
                for setting in kind.settings
            }
        )
        if problem:
            msgbox(_(problem))
            return

        if not (port and port.isdigit() and 1 <= int(port) <= 65535):
            msgbox(_("Puerto invalido"))
            return

        term = self.txtTerm.get_text()

        host = Host(
            group,
            name,
            description,
            host,
            user,
            password,
            private_key,
            port,
            tunnel,
            ctype,
            commands,
            keepalive,
            fcolor,
            bcolor,
            x11,
            agent,
            compression,
            compressionLevel,
            extra_params,
            log,
            backspace_key,
            delete_key,
            term,
            commands_enabled,
            "" if self.isNew else self.oldId,
        )
        # The chosen type's only. Another type's page is hidden, and whatever it held is
        # not saved with this host, as Port forwarding is not for a type without it.
        host.type_settings = kind.stored_settings(type_values)
        host.before_command = self.txtBeforeCommand.get_text().strip()
        host.after_command = self.txtAfterCommand.get_text().strip() if kind.opens_tab else ""
        host.tab_name = self.txtTabName.get_text().strip() if kind.opens_tab else ""
        host.tab_color = (
            color_to_hex(self.btnTabColor.get_rgba())
            if kind.opens_tab and self.chkTabColor.get_active()
            else ""
        )
        if not self.isNew and group == self.oldGroup:
            # Only while it stays in the same folder: a position means nothing elsewhere.
            host.position = self.oldPosition

        try:
            # Guardar
            if group not in groups:  # not groups.has_key(group):
                groups[group] = []

            if self.isNew:
                for h in groups[group]:
                    if h.name == name:
                        msgbox(
                            "{} [{}] {} [{}]".format(
                                _("El nombre"), name, _("ya existe para el grupo"), group
                            )
                        )
                        return
                # agregar host a grupo
                groups[group].append(host)
            else:
                if self.oldGroup != group:
                    # revisar que no este el nombre en el nuevo grupo
                    if group not in groups:  # if not groups.has_key(group):
                        groups[group] = [host]
                    else:
                        for h in groups[group]:
                            if h.name == name:
                                msgbox(
                                    "{} [{}] {} [{}]".format(
                                        _("El nombre"), name, _("ya existe para el grupo"), group
                                    )
                                )
                                return
                        groups[group].append(host)
                        for h in groups[self.oldGroup]:
                            if h.name == self.oldName:
                                groups[self.oldGroup].remove(h)
                                break
                else:
                    if self.oldName != name:
                        for h in groups[self.oldGroup]:
                            if h.name == name:
                                msgbox(
                                    "{} [{}] {} [{}]".format(
                                        _("El nombre"), name, _("ya existe para el grupo"), group
                                    )
                                )
                                return
                        for h in groups[self.oldGroup]:
                            if h.name == self.oldName:
                                index = groups[self.oldGroup].index(h)
                                groups[self.oldGroup][index] = host
                                break
                    else:
                        for h in groups[self.oldGroup]:
                            if h.name == self.oldName:
                                index = groups[self.oldGroup].index(h)
                                groups[self.oldGroup][index] = host
                                break
        except (KeyError, ValueError, IndexError) as e:
            msgbox(f"{_('Error al guardar el host. Descripcion')} [{e}]")

        global wMain
        wMain.updateTree()
        wMain.writeConfig()

        self.get_widget("wHost").destroy()

    # -- Whost.on_okbutton1_clicked }

    # -- Whost.on_cmbType_changed {
    def on_cmbType_changed(self, widget, *args):
        kind = connections.named(widget.get_active_text())
        # Greyed and kept, what the program the host opens in leaves unused, such as an RDP
        # host's user and password while Windows Remote Desktop opens it (#285). What the
        # type never uses is cleared too, below.
        ignored = kind.ignores(connection_programs())
        credentials = kind.remote and kind.credentials and "credentials" not in ignored
        self.txtUser.set_sensitive(credentials)
        self.txtPassword.set_sensitive(credentials)
        self.txtPort.set_sensitive(kind.remote)
        self.txtHost.set_sensitive(kind.remote)
        self.txtExtraParams.set_sensitive(
            kind.remote and kind.arguments and "arguments" not in ignored
        )
        # Cleared as a local host's are, so a host keeps no password it never uses.
        if not kind.credentials:
            self.txtUser.set_text("")
            self.txtPassword.set_text("")
        if not kind.arguments:
            self.txtExtraParams.set_text("")

        # A type is shown the tabs it uses and no others (#277): SSH's own options and its
        # port forwarding for SSH alone, and the Terminal tab for a host whose tab is a
        # terminal. A field on a tab every type shows is greyed instead.
        self.get_widget("sshGrid").set_visible(kind.ssh_options)
        self.get_widget("tunnelGrid").set_visible(kind.ssh_options)
        self.get_widget("terminalPage").set_visible(opens_terminal(kind))
        if not kind.ssh_options:
            # Unticked too, so that choosing SSH again shows keep-alive off, as it then is.
            # It stayed ticked over a keep-alive of 0.
            self.chkKeepAlive.set_active(False)
            self.txtKeepAlive.set_text("0")
            if not kind.remote:
                self.txtUser.set_text("")
                self.txtPassword.set_text("")
                self.txtPort.set_text("")
                self.txtHost.set_text("")
        self.txtPort.set_text(kind.default_port)

        self.chkCommands.set_sensitive(kind.sends_commands)
        self.txtCommands.set_sensitive(kind.sends_commands and self.chkCommands.get_active())
        # A host that opens no tab has no session to end, so nothing runs after one, and no
        # tab to name (#349) or to colour (#350).
        self.txtAfterCommand.set_sensitive(kind.opens_tab)
        self.txtTabName.set_sensitive(kind.opens_tab)
        self.chkTabColor.set_sensitive(kind.opens_tab)
        if not kind.opens_tab:
            self.txtAfterCommand.set_text("")
            self.txtTabName.set_text("")
            self.chkTabColor.set_active(False)
        self.btnTabColor.set_sensitive(kind.opens_tab and self.chkTabColor.get_active())
        self.show_type_page(kind, ignored)

    # -- Whost.on_cmbType_changed }

    # -- Whost.on_chkKeepAlive_toggled {
    def on_chkKeepAlive_toggled(self, widget, *args):
        if widget.get_active():
            self.txtKeepAlive.set_text("120")
        else:
            self.txtKeepAlive.set_text("0")
        self.txtKeepAlive.set_sensitive(widget.get_active())

