    def _on_action_console_close(self, action, _param):
        if self._controller is not None:
            # A tab action: it closes the tab, whatever the tab holds (#223). "X" used to
            # read popupMenu.terminal, which only the terminal branch sets, so sending it
            # down the tab branch raised instead of closing (#95). Reading that, Ctrl+W
            # could not close a tab without a terminal.
            self._controller.trigger_popup_action("X", "X")

    def _on_action_console_window(self, action, _param):
        if self._controller is not None:
            # A tab action, like Close console: out to a window of its own, or back (#255).
            self._controller.trigger_popup_action("W", "W")

    def _on_action_console_log(self, action, state):
        if self._controller is None:
            return
        enable = state.get_boolean()
        terminal = self._controller.get_target_terminal()
        if terminal is None:
            return
        if not self._controller.set_terminal_logger(terminal, enable):
            enable = False
        action.set_state(GLib.Variant("b", enable))
        self._controller.clear_context_terminal()
        self._controller.clear_context_tab_widget()

