# -- main {


def main(argv=None):
    if argv is None:
        argv = sys.argv
    require_expect()
    require_config_dir()
    require_readable_config()
    application = GcmApplication()
    return application.run(argv)


if __name__ == "__main__":
    raise SystemExit(main())

